window.MT_DATA['vi'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours au Viêt Nam, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Hanoï","phrases":[{"fr":"Bienvenue à Hanoï !","tgt":"Chào mừng bạn đến Hà Nội!","lit":"bienvenue · toi · arriver · Hanoï"},{"fr":"Bonjour, je viens de France.","tgt":"Xin chào, tôi đến từ Pháp.","lit":"bonjour · je · venir · de · France"},{"fr":"Je suis arrivé à Hanoï hier.","tgt":"Tôi đến Hà Nội hôm qua.","lit":"je · arriver · Hanoï · hier"},{"fr":"Mon ami arrive demain.","tgt":"Bạn tôi đến ngày mai.","lit":"ami · je · arriver · demain"},{"fr":"Nous logeons dans le vieux quartier.","tgt":"Chúng tôi ở phố cổ.","lit":"nous · habiter · rue · ancien"},{"fr":"Je parle un peu vietnamien.","tgt":"Tôi nói một chút tiếng Việt.","lit":"je · parler · un · peu · langue · Viêt"},{"fr":"Hier j'ai mangé un phở, demain j'en mangerai encore un.","tgt":"Hôm qua tôi ăn phở, ngày mai tôi lại ăn phở.","lit":"hier · je · manger · phở · demain · je · encore · manger · phở"},{"fr":"Je vais au marché chaque matin.","tgt":"Tôi đi chợ mỗi sáng.","lit":"je · aller · marché · chaque · matin"},{"fr":"Demain, nous allons au lac Hoàn Kiếm.","tgt":"Ngày mai chúng tôi đi hồ Hoàn Kiếm.","lit":"demain · nous · aller · lac · Hoàn Kiếm"},{"fr":"J'aime beaucoup Hanoï.","tgt":"Tôi rất thích Hà Nội.","lit":"je · très · aimer · Hanoï"}],"tip":{"title":"Pas de conjugaison : le verbe ne change jamais","example":"Hier j'ai mangé un phở, demain j'en mangerai encore un. — Hôm qua tôi <b>ăn</b> phở, ngày mai tôi lại <b>ăn</b> phở.","body":"Bonne nouvelle pour commencer : en vietnamien, le verbe ne se conjugue jamais. « Ăn », manger, reste « ăn » avec je, avec nous, hier comme demain. Il n'y a ni terminaisons, ni temps à apprendre par cœur. Pour situer l'action, on ajoute simplement un mot de temps, souvent en début de phrase : « hôm qua », hier, ou « ngày mai », demain. Décomposons « hôm qua tôi ăn phở » : mot à mot hier, je, manger, « phở », c'est-à-dire hier j'ai mangé un « phở ». Autres exemples : « tôi đi », je vais, « chúng tôi đi », nous allons, et « ngày mai tôi đi », demain j'irai. Astuce : voyez le verbe comme une brique qui ne bouge jamais, et posez simplement l'horloge à côté.","lit":"hier · je · manger · phở · demain · je · encore · manger · phở","say":{"Ăn":"Ăn","ăn":"ăn","hôm qua":"hôm qua","ngày mai":"ngày mai","hôm qua tôi ăn phở":"hôm qua tôi ăn phở","tôi đi":"tôi đi","chúng tôi đi":"chúng tôi đi","ngày mai tôi đi":"ngày mai tôi đi"}}},{"title":"Un café glacé sur un tabouret","phrases":[{"fr":"Un café noir glacé, s'il vous plaît.","tgt":"Cho tôi một cà phê đen đá.","lit":"donner · je · un · café · noir · glace"},{"fr":"Je voudrais un café au lait glacé.","tgt":"Cho tôi một cà phê sữa đá.","lit":"donner · je · un · café · lait · glace"},{"fr":"Je peux m'installer ici, sur ce tabouret ?","tgt":"Tôi ngồi ghế này được không?","lit":"je · s'asseoir · chaise · ceci · pouvoir · [question]"},{"fr":"Le café est trop sucré.","tgt":"Cà phê ngọt quá.","lit":"café · sucré · trop"},{"fr":"Peu de sucre pour moi, s'il vous plaît.","tgt":"Cho tôi ít đường.","lit":"donner · je · peu · sucre"},{"fr":"Il fait chaud, je bois un thé glacé.","tgt":"Trời nóng, tôi uống trà đá.","lit":"ciel · chaud · je · boire · thé · glace"},{"fr":"Ici, le café est vraiment bon.","tgt":"Cà phê ở đây ngon lắm.","lit":"café · à · ici · bon · très"},{"fr":"Je vous dois combien ?","tgt":"Bao nhiêu tiền?","lit":"combien · argent"},{"fr":"Ça fait vingt mille dongs.","tgt":"Hai mươi nghìn đồng.","lit":"deux · dix · mille · dong"},{"fr":"Le café vietnamien est très fort.","tgt":"Cà phê Việt Nam rất đậm.","lit":"café · Viêt Nam · très · fort"}],"tip":{"title":"Les six tons du vietnamien : la mélodie change le sens","example":"Ici, le café est vraiment bon. — Cà phê ở đây <b>ngon</b> lắm.","body":"Le vietnamien est une langue à tons : chaque syllabe porte une mélodie, et cette mélodie fait partie du mot. Il y en a six : un ton plat et égal, un ton qui monte, un ton qui descend doucement, un ton qui plonge puis remonte, un ton cassé au milieu, et un ton bref et grave qui tombe d'un coup. Changez la mélodie et vous changez le mot : « ma » sur un ton plat, c'est un fantôme, « má » qui monte, c'est la joue, « mà » qui descend, c'est mais. Au café, c'est très concret : « bán » veut dire vendre, « bàn » veut dire table, et « bạn » veut dire ami. Dans « cà phê đá », café glacé, « cà » descend, « phê » reste plat et « đá » monte. Au début, exagérez les mélodies, presque comme si vous chantiez. Astuce : répétez chaque phrase en imitant la voix comme une petite chanson, plutôt que syllabe par syllabe.","lit":"café · à · ici · bon · très","say":{"ma":"ma","má":"má","mà":"mà","bán":"bán","bàn":"bàn","bạn":"bạn","cà phê đá":"cà phê đá","cà":"cà","phê":"phê","đá":"đá"}}},{"title":"Le vieux quartier de Hanoï","phrases":[{"fr":"C'est le vieux quartier de Hanoï.","tgt":"Đây là phố cổ Hà Nội.","lit":"ici · être · rue · ancien · Hanoï"},{"fr":"Voici la rue Hàng Bạc.","tgt":"Đây là phố Hàng Bạc.","lit":"ici · être · rue · Hàng Bạc"},{"fr":"Moi, je suis touriste.","tgt":"Tôi là khách du lịch.","lit":"je · être · visiteur · voyage"},{"fr":"Lui, c'est mon voisin.","tgt":"Anh ấy là hàng xóm của tôi.","lit":"grand frère · ce · être · voisin · de · je"},{"fr":"Elle est enseignante.","tgt":"Chị ấy là giáo viên.","lit":"grande sœur · ce · être · enseignant"},{"fr":"Hanoï est la capitale du Viêt Nam.","tgt":"Hà Nội là thủ đô của Việt Nam.","lit":"Hanoï · être · capitale · de · Viêt Nam"},{"fr":"Ici, c'est le lac Hoàn Kiếm.","tgt":"Đây là hồ Hoàn Kiếm.","lit":"ici · être · lac · Hoàn Kiếm"},{"fr":"Mon nom est Lucie.","tgt":"Tên tôi là Lucie.","lit":"nom · je · être · Lucie"},{"fr":"C'est une maison-tube typique.","tgt":"Đây là nhà ống.","lit":"ici · être · maison · tube"},{"fr":"Moi, je suis de nationalité française, et toi ?","tgt":"Tôi là người Pháp, còn bạn?","lit":"je · être · personne · France · et · toi"}],"tip":{"title":"« Là » : être, entre deux noms","example":"Moi, je suis touriste. — Tôi <b>là</b> khách du lịch.","body":"Le mot « là » joue le rôle du verbe être, mais seulement quand il relie deux noms : je suis touriste, c'est le lac, elle est enseignante. Comme tous les verbes vietnamiens, il ne change jamais, quel que soit le sujet. Décomposons « tôi là khách du lịch » : « tôi », je, « là », être, et « khách du lịch », touriste. Autres exemples : « đây là hồ Hoàn Kiếm », ici c'est le lac « Hoàn Kiếm », et « tên tôi là Lucie », mon nom est Lucie. Attention, « là » ne s'emploie pas devant un adjectif : pour dire je suis fatigué, on s'en passe, nous le verrons bientôt. Astuce : imaginez « là » comme un petit signe égal entre deux choses, comme dans une équation.","lit":"je · être · visiteur · voyage","say":{"Là":"Là","là":"là","tôi là khách du lịch":"tôi là khách du lịch","tôi":"tôi","khách du lịch":"khách du lịch","đây là hồ Hoàn Kiếm":"đây là hồ Hoàn Kiếm","tên tôi là Lucie":"tên tôi là Lucie"}}},{"title":"Un appartement dans le vieux quartier","phrases":[{"fr":"Ce n'est pas mon appartement.","tgt":"Đây không phải là căn hộ của tôi.","lit":"ici · pas · exact · être · appartement · de · je"},{"fr":"L'appartement n'est pas spacieux.","tgt":"Căn hộ không rộng.","lit":"appartement · pas · spacieux"},{"fr":"Il n'y a pas d'ascenseur.","tgt":"Không có thang máy.","lit":"pas · avoir · escalier · machine"},{"fr":"Je ne suis pas étudiant.","tgt":"Tôi không phải là sinh viên.","lit":"je · pas · exact · être · étudiant"},{"fr":"Le loyer n'est pas cher.","tgt":"Tiền nhà không đắt.","lit":"argent · maison · pas · cher"},{"fr":"La cuisine n'est pas très propre.","tgt":"Bếp không sạch lắm.","lit":"cuisine · pas · propre · très"},{"fr":"Je ne fume pas.","tgt":"Tôi không hút thuốc.","lit":"je · pas · aspirer · tabac"},{"fr":"Le propriétaire n'habite pas ici.","tgt":"Chủ nhà không ở đây.","lit":"maître · maison · pas · habiter · ici"},{"fr":"Ici, ce n'est pas loin du marché.","tgt":"Ở đây không xa chợ.","lit":"à · ici · pas · loin · marché"},{"fr":"Ce n'est pas mon scooter.","tgt":"Đây không phải là xe máy của tôi.","lit":"ici · pas · exact · être · véhicule · machine · de · je"}],"tip":{"title":"« Không » : la négation, et « không phải là »","example":"Je ne suis pas étudiant. — Tôi <b>không phải là</b> sinh viên.","body":"Pour dire ne pas, le vietnamien utilise un seul petit mot : « không ». On le place juste devant le verbe ou l'adjectif, et c'est tout, pas besoin de deux morceaux comme ne et pas. On dit « tôi không hút thuốc », je ne fume pas, et « tiền nhà không đắt », le loyer n'est pas cher. Mais pour nier « là », être entre deux noms, on dit « không phải là », mot à mot pas, exact, être. Décomposons « tôi không phải là sinh viên » : je, pas exact, être, étudiant, donc je ne suis pas étudiant. C'est un peu comme dire en français : il n'est pas exact que je sois étudiant. Astuce : devant un verbe ou un adjectif, « không » tout seul ; à la place de « là », « không phải là ».","lit":"je · pas · exact · être · étudiant","say":{"Không":"Không","không phải là":"không phải là","không":"không","tôi không hút thuốc":"tôi không hút thuốc","tiền nhà không đắt":"tiền nhà không đắt","là":"là","tôi không phải là sinh viên":"tôi không phải là sinh viên"}}},{"title":"Le bol de phở au coin de la rue","phrases":[{"fr":"Tu as un petit creux ?","tgt":"Bạn đói không?","lit":"toi · affamé · [question]"},{"fr":"On va manger un phở ?","tgt":"Đi ăn phở không?","lit":"aller · manger · phở · [question]"},{"fr":"Le phở ici est bon ?","tgt":"Phở ở đây ngon không?","lit":"phở · à · ici · bon · [question]"},{"fr":"Il y a du phở au poulet ?","tgt":"Có phở gà không?","lit":"avoir · phở · poulet · [question]"},{"fr":"Oui, nous en avons.","tgt":"Dạ, có.","lit":"[politesse] oui · avoir"},{"fr":"Un bol de phở au bœuf, s'il vous plaît.","tgt":"Cho tôi một bát phở bò.","lit":"donner · je · un · bol · phở · bœuf"},{"fr":"Vous prenez des herbes aromatiques ?","tgt":"Anh ăn rau thơm không?","lit":"grand frère · manger · herbe · parfumé · [question]"},{"fr":"Ça pique ?","tgt":"Cái này cay không?","lit":"[classificateur] · ceci · piquant · [question]"},{"fr":"Non, pas très piquant.","tgt":"Không cay lắm.","lit":"pas · piquant · très"},{"fr":"Tu en reprends ?","tgt":"Bạn ăn nữa không?","lit":"toi · manger · encore · [question]"}],"tip":{"title":"« … không ? » : transformer une phrase en question","example":"Le phở ici est bon ? — Phở ở đây ngon <b>không</b>?","body":"Pour poser une question fermée, inutile de changer l'ordre des mots : on prend la phrase et on ajoute « không » tout à la fin. « Phở ở đây ngon », le « phở » ici est bon, devient « phở ở đây ngon không ? », il est bon, le « phở » ici ? Décomposons : « phở », à, ici, bon, et « không » qui joue le rôle du point d'interrogation. Pour répondre, on ne dit pas simplement oui : on répète le verbe ou l'adjectif, « ngon », c'est bon, ou « không ngon », ce n'est pas bon. Avec avoir, on entend souvent « có … không ? », comme « có phở gà không ? », il y a du « phở » au poulet ? La voix reste naturelle, c'est le petit mot final qui fait tout le travail. Astuce : imaginez que « không » à la fin veut dire, ou pas ?","lit":"phở · à · ici · bon · [question]","say":{"… không ?":"… không ?","không":"không","Phở ở đây ngon":"Phở ở đây ngon","phở ở đây ngon không ?":"phở ở đây ngon không ?","ngon":"ngon","không ngon":"không ngon","có … không ?":"có … không ?","có phở gà không ?":"có phở gà không ?"}}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Bonjour, comment allez-vous ? (à une femme un peu plus âgée)","tgt":"Chào chị, chị khỏe không?","lit":"saluer · grande sœur · grande sœur · en forme · [question]"},{"fr":"Je vais bien, merci. Et toi ?","tgt":"Chị khỏe, cảm ơn em. Còn em?","lit":"grande sœur · en forme · merci · cadet · et · cadet"},{"fr":"Bonjour ! (à un homme un peu plus âgé)","tgt":"Chào anh!","lit":"saluer · grand frère"},{"fr":"Je m'appelle Paul, et vous ?","tgt":"Tôi tên là Paul, còn anh?","lit":"je · nom · être · Paul · et · grand frère"},{"fr":"Moi, je m'appelle Minh.","tgt":"Anh tên là Minh.","lit":"grand frère · nom · être · Minh"},{"fr":"Tu es étudiante ? (à une jeune femme)","tgt":"Em có phải là sinh viên không?","lit":"cadet · [affirmation] · exact · être · étudiant · [question]"},{"fr":"Oui, je suis étudiante.","tgt":"Vâng, em là sinh viên.","lit":"oui · cadet · être · étudiant"},{"fr":"Bonjour, monsieur ! (à un voisin âgé)","tgt":"Cháu chào bác ạ!","lit":"neveu · saluer · oncle · [politesse]"},{"fr":"Cette vieille dame, c'est madame Hoa.","tgt":"Bà ấy là bà Hoa.","lit":"grand-mère · ce · être · grand-mère · Hoa"},{"fr":"Elle travaille au marché.","tgt":"Chị ấy làm ở chợ.","lit":"grande sœur · ce · travailler · à · marché"}],"tip":{"title":"Les pronoms : « tôi », et « anh », « chị », « em » selon l'âge","example":"Je vais bien, merci. Et toi ? — <b>Chị</b> khỏe, cảm ơn <b>em</b>. Còn <b>em</b>?","body":"En vietnamien, on ne dit pas simplement tu ou vous : on choisit un mot de la famille selon l'âge de la personne. À un homme un peu plus âgé que vous, on dit « anh », grand frère ; à une femme un peu plus âgée, « chị », grande sœur ; à quelqu'un de plus jeune, « em », petit frère ou petite sœur. Et chacun utilise aussi ce mot pour parler de soi : la voisine plus âgée dira « chị khỏe », mot à mot grande sœur en forme, pour dire je vais bien. Pour une personne âgée, on emploie « bác », et l'on se présente comme « cháu », neveu, en ajoutant « ạ » par respect : « cháu chào bác ạ ». Quand on hésite, « tôi », je, reste neutre et toujours correct. Astuce : avant de parler, demandez-vous qui est l'aîné, c'est lui qui donne le ton de la conversation.","lit":"grande sœur · en forme · merci · cadet · et · cadet","say":{"tôi":"tôi","anh":"anh","chị":"chị","em":"em","chị khỏe":"chị khỏe","bác":"bác","cháu":"cháu","ạ":"ạ","cháu chào bác ạ":"cháu chào bác ạ"}}},{"title":"S'installer dans l'appartement","phrases":[{"fr":"C'est ma chambre.","tgt":"Đây là phòng của tôi.","lit":"ici · être · chambre · de · je"},{"fr":"Où est ta valise ?","tgt":"Va li của bạn ở đâu?","lit":"valise · de · toi · se trouver · où"},{"fr":"Ce sont les clés de la propriétaire.","tgt":"Đây là chìa khóa của bà chủ nhà.","lit":"ici · être · clé · de · dame · maître · maison"},{"fr":"Ma chambre donne sur la rue.","tgt":"Phòng của tôi nhìn ra phố.","lit":"chambre · de · je · regarder · sortir · rue"},{"fr":"Le scooter de Minh est tout neuf.","tgt":"Xe máy của anh Minh rất mới.","lit":"véhicule · machine · de · grand frère · Minh · très · neuf"},{"fr":"Mon livre est sur la table.","tgt":"Sách của tôi ở trên bàn.","lit":"livre · de · je · se trouver · sur · table"},{"fr":"À qui est ce chat ?","tgt":"Con mèo này của ai?","lit":"[classificateur] · chat · ceci · de · qui"},{"fr":"C'est celui de la voisine.","tgt":"Của chị hàng xóm.","lit":"de · grande sœur · voisin"},{"fr":"Ma famille habite en France.","tgt":"Gia đình tôi ở Pháp.","lit":"famille · je · habiter · France"},{"fr":"Votre appartement est vraiment beau !","tgt":"Căn hộ của anh đẹp quá!","lit":"appartement · de · grand frère · beau · trop"}],"tip":{"title":"« Của » : le possessif, « sách của tôi »","example":"Mon livre est sur la table. — Sách <b>của</b> tôi ở trên bàn.","body":"Pour dire mon, ton ou son, le vietnamien met la chose d'abord, puis « của », qui veut dire de, puis le propriétaire. « Sách của tôi », mot à mot livre de moi, c'est mon livre. Décomposons « sách của tôi ở trên bàn » : livre, de, je, se trouver, sur, table, donc mon livre est sur la table. De la même façon, « phòng của tôi », c'est ma chambre, et « chìa khóa của bà chủ nhà », les clés de la propriétaire. Avec la famille et les proches, on supprime souvent « của » : « gia đình tôi », ma famille, « bạn tôi », mon ami. On peut même répondre avec « của » tout seul : « của chị hàng xóm », c'est à la voisine. Astuce : pensez à la tournure le livre de moi, et vous aurez l'ordre exact.","lit":"livre · de · je · se trouver · sur · table","say":{"Của":"Của","của":"của","Sách của tôi":"Sách của tôi","sách của tôi ở trên bàn":"sách của tôi ở trên bàn","phòng của tôi":"phòng của tôi","chìa khóa của bà chủ nhà":"chìa khóa của bà chủ nhà","gia đình tôi":"gia đình tôi","bạn tôi":"bạn tôi","của chị hàng xóm":"của chị hàng xóm"}}},{"title":"La chaleur de Hanoï","phrases":[{"fr":"Je suis tellement fatigué !","tgt":"Tôi mệt quá!","lit":"je · fatigué · trop"},{"fr":"Aujourd'hui, il fait vraiment très chaud.","tgt":"Hôm nay trời rất nóng.","lit":"aujourd'hui · ciel · très · chaud"},{"fr":"La rue est très bruyante.","tgt":"Phố rất ồn.","lit":"rue · très · bruyant"},{"fr":"Je suis très content d'être ici.","tgt":"Tôi rất vui được ở đây.","lit":"je · très · content · [pouvoir] · être à · ici"},{"fr":"Le café est un peu amer.","tgt":"Cà phê hơi đắng.","lit":"café · un peu · amer"},{"fr":"Hanoï est très animée.","tgt":"Hà Nội rất nhộn nhịp.","lit":"Hanoï · très · animé"},{"fr":"J'ai terriblement soif.","tgt":"Tôi khát nước quá.","lit":"je · assoiffé · eau · trop"},{"fr":"Mon voisin est très gentil.","tgt":"Hàng xóm của tôi rất tốt bụng.","lit":"voisin · de · je · très · bon · ventre"},{"fr":"Le matin, le lac est très calme.","tgt":"Buổi sáng, hồ rất yên tĩnh.","lit":"moment · matin · lac · très · calme"},{"fr":"Il y a vraiment trop de scooters !","tgt":"Nhiều xe máy quá!","lit":"nombreux · véhicule · machine · trop"}],"tip":{"title":"Adjectif sans verbe être : « tôi mệt », et « rất » pour très","example":"Je suis tellement fatigué ! — Tôi <b>mệt</b> quá!","body":"En vietnamien, l'adjectif fonctionne comme un verbe : il se place directement après le sujet, sans « là ». Pour dire je suis fatigué, on dit simplement « tôi mệt », mot à mot je fatigué. Dire « tôi là mệt » serait une erreur typique de débutant. Pour dire très, on place « rất » juste devant l'adjectif : « hôm nay trời rất nóng », aujourd'hui, ciel, très, chaud, il fait très chaud. À l'oral, on entend aussi « lắm » ou « quá » après l'adjectif : « nóng quá », qu'il fait chaud ! D'autres exemples : « tôi khát nước », j'ai soif, et « phố rất ồn », la rue est très bruyante. Astuce : le sujet, puis directement l'état, comme dans un télégramme.","lit":"je · fatigué · trop","say":{"tôi mệt":"tôi mệt","rất":"rất","là":"là","tôi là mệt":"tôi là mệt","hôm nay trời rất nóng":"hôm nay trời rất nóng","lắm":"lắm","quá":"quá","nóng quá":"nóng quá","tôi khát nước":"tôi khát nước","phố rất ồn":"phố rất ồn"}}},{"title":"Le petit marché du matin","phrases":[{"fr":"Ce marché ouvre très tôt.","tgt":"Chợ này mở cửa rất sớm.","lit":"marché · ceci · ouvrir · porte · très · tôt"},{"fr":"Combien le kilo de ces mangues ?","tgt":"Xoài này bao nhiêu tiền một cân?","lit":"mangue · ceci · combien · argent · un · kilo"},{"fr":"Ces légumes sont très frais.","tgt":"Rau này rất tươi.","lit":"légume · ceci · très · frais"},{"fr":"Je prends ce poisson-là.","tgt":"Tôi lấy con cá kia.","lit":"je · prendre · [classificateur] · poisson · là-bas"},{"fr":"Ce stand-là vend des fleurs.","tgt":"Hàng kia bán hoa.","lit":"stand · là-bas · vendre · fleur"},{"fr":"La dame là-bas vend des bánh mì.","tgt":"Bà kia bán bánh mì.","lit":"dame · là-bas · vendre · bánh mì"},{"fr":"Cette pastèque est sucrée ?","tgt":"Dưa hấu này ngọt không?","lit":"pastèque · ceci · sucré · [question]"},{"fr":"Non, prenez plutôt celle-là.","tgt":"Không, chị lấy quả kia đi.","lit":"non · grande sœur · prendre · [classificateur] · là-bas · [incitation]"},{"fr":"Ces œufs, c'est combien ?","tgt":"Trứng này bán thế nào?","lit":"œuf · ceci · vendre · comment"},{"fr":"Ce matin, il y a foule au marché.","tgt":"Sáng nay chợ rất đông.","lit":"matin · ceci · marché · très · bondé"}],"tip":{"title":"« Này » et « kia » : ceci et cela, placés après le nom","example":"Ces légumes sont très frais. — Rau <b>này</b> rất tươi.","body":"En français, on dit ce marché, avec le démonstratif devant. En vietnamien, c'est l'inverse : on dit le nom, puis « này », ceci, pour ce qui est près de vous, ou « kia », là-bas, pour ce qui est plus loin. « Rau này rất tươi », mot à mot légume ceci très frais, veut dire ces légumes sont très frais. Et « hàng kia bán hoa », stand là-bas vendre fleur, veut dire ce stand-là vend des fleurs. Le même petit mot se cache dans des expressions courantes : « sáng nay », ce matin, et « hôm nay », aujourd'hui. Au marché, c'est votre meilleur allié : il suffit de montrer du doigt et de dire « cái này », celui-ci, ou « cái kia », celui-là. Astuce : le nom d'abord, puis le doigt qui pointe.","lit":"légume · ceci · très · frais","say":{"Này":"Này","kia":"kia","này":"này","Rau này rất tươi":"Rau này rất tươi","hàng kia bán hoa":"hàng kia bán hoa","sáng nay":"sáng nay","hôm nay":"hôm nay","cái này":"cái này","cái kia":"cái kia"}}},{"title":"Les vêtements et les couleurs","phrases":[{"fr":"Je cherche une simple chemise blanche.","tgt":"Tôi tìm áo sơ mi trắng.","lit":"je · chercher · vêtement · chemise · blanc"},{"fr":"J'aime ce chapeau conique.","tgt":"Tôi thích cái nón lá này.","lit":"je · aimer · [classificateur] · chapeau · feuille · ceci"},{"fr":"Elle porte une jolie robe rouge.","tgt":"Chị ấy mặc váy đỏ rất đẹp.","lit":"grande sœur · ce · porter · robe · rouge · très · beau"},{"fr":"Le pantalon noir est trop long.","tgt":"Quần đen dài quá.","lit":"pantalon · noir · long · trop"},{"fr":"Vous avez un sac bleu ?","tgt":"Có túi màu xanh dương không?","lit":"avoir · sac · couleur · bleu · océan · [question]"},{"fr":"J'aime bien le jaune.","tgt":"Tôi thích màu vàng.","lit":"je · aimer · couleur · jaune"},{"fr":"L'áo dài est très élégant.","tgt":"Áo dài rất đẹp.","lit":"vêtement · long · très · beau"},{"fr":"Je voudrais acheter un t-shirt vert.","tgt":"Tôi muốn mua áo phông xanh lá.","lit":"je · vouloir · acheter · vêtement · t-shirt · vert · feuille"},{"fr":"Ces chaussures sont neuves ?","tgt":"Đôi giày này mới không?","lit":"[paire] · chaussure · ceci · neuf · [question]"},{"fr":"Un petit café vert au coin de la rue.","tgt":"Một quán cà phê nhỏ màu xanh ở góc phố.","lit":"un · boutique · café · petit · couleur · vert · à · coin · rue"}],"tip":{"title":"L'ordre des mots : le nom d'abord, l'adjectif ensuite","example":"Je cherche une simple chemise blanche. — Tôi tìm áo sơ mi <b>trắng</b>.","body":"En vietnamien, l'adjectif vient toujours après le nom, comme dans une chemise blanche, mais sans aucune exception, même pour petit ou beau. On dit « áo sơ mi trắng », mot à mot vêtement, chemise, blanc. Vous connaissez déjà des exemples : « phố cổ », la rue ancienne, c'est le vieux quartier, et « cà phê đen », le café noir. Même le nom de la tunique traditionnelle, « áo dài », signifie simplement vêtement long. Pour une couleur, on ajoute souvent « màu », couleur, juste avant : « túi màu xanh dương », un sac de couleur bleue. Et quand il y a plusieurs mots, on les empile dans l'ordre : le nom, l'adjectif, puis « này » ou « kia ». Astuce : commencez toujours par la chose, puis décrivez-la.","lit":"je · chercher · vêtement · chemise · blanc","say":{"áo sơ mi trắng":"áo sơ mi trắng","phố cổ":"phố cổ","cà phê đen":"cà phê đen","áo dài":"áo dài","màu":"màu","túi màu xanh dương":"túi màu xanh dương","này":"này","kia":"kia"}}},{"title":"Les prix au marché","phrases":[{"fr":"Un, deux, trois, on commence !","tgt":"Một, hai, ba, bắt đầu!","lit":"un · deux · trois · commencer"},{"fr":"Je voudrais deux kilos de riz.","tgt":"Cho tôi hai cân gạo.","lit":"donner · je · deux · kilo · riz"},{"fr":"Ça fait cinquante mille dongs.","tgt":"Năm mươi nghìn đồng.","lit":"cinq · dix · mille · dong"},{"fr":"Trois bánh mì, s'il vous plaît.","tgt":"Cho tôi ba cái bánh mì.","lit":"donner · je · trois · [classificateur] · bánh mì"},{"fr":"Dix œufs, ça fait combien ?","tgt":"Mười quả trứng bao nhiêu tiền?","lit":"dix · [classificateur] · œuf · combien · argent"},{"fr":"Quinze mille dongs.","tgt":"Mười lăm nghìn đồng.","lit":"dix · cinq · mille · dong"},{"fr":"Ma voisine a quatre enfants.","tgt":"Chị hàng xóm có bốn con.","lit":"grande sœur · voisin · avoir · quatre · enfant"},{"fr":"J'ai vingt et un ans.","tgt":"Tôi hai mươi mốt tuổi.","lit":"je · deux · dix · un · âge"},{"fr":"Un café coûte vingt-cinq mille dongs.","tgt":"Một cốc cà phê hai mươi lăm nghìn đồng.","lit":"un · verre · café · deux · dix · cinq · mille · dong"},{"fr":"En tout, ça fait cent mille dongs.","tgt":"Tất cả là một trăm nghìn đồng.","lit":"tout · être · un · cent · mille · dong"}],"tip":{"title":"Compter de un à dix, et au-delà","example":"Ça fait cinquante mille dongs. — <b>Năm mươi</b> nghìn đồng.","body":"Les nombres de un à dix sont courts et faciles : « một, hai, ba, bốn, năm, sáu, bảy, tám, chín, mười ». Ensuite, tout se construit comme un jeu de briques. Onze, c'est « mười một », dix un, et vingt, c'est « hai mươi », deux dix. Décomposons « năm mươi nghìn đồng » : cinq, dix, mille, dong, donc cinquante mille dongs, un prix très courant au marché. Deux petits pièges : après dix, cinq devient « lăm », comme dans « mười lăm », quinze, et après vingt, un devient « mốt », comme dans « hai mươi mốt », vingt et un. Pour cent, on dit « trăm », et pour mille, « nghìn ». Astuce : entraînez-vous en disant à voix haute les prix au marché, les dongs ont toujours beaucoup de zéros !","lit":"cinq · dix · mille · dong","say":{"một, hai, ba, bốn, năm, sáu, bảy, tám, chín, mười":"một, hai, ba, bốn, năm, sáu, bảy, tám, chín, mười","mười một":"mười một","hai mươi":"hai mươi","năm mươi nghìn đồng":"năm mươi nghìn đồng","lăm":"lăm","mười lăm":"mười lăm","mốt":"mốt","hai mươi mốt":"hai mươi mốt","trăm":"trăm","nghìn":"nghìn"}}},{"title":"Les scooters de Hanoï","phrases":[{"fr":"J'ai un scooter rouge.","tgt":"Tôi có một chiếc xe máy màu đỏ.","lit":"je · avoir · un · [classificateur] · véhicule · machine · couleur · rouge"},{"fr":"Regarde le chien sur ce scooter-là !","tgt":"Nhìn con chó trên xe máy kia!","lit":"regarder · [classificateur] · chien · sur · véhicule · machine · là-bas"},{"fr":"Je voudrais acheter une chaise.","tgt":"Tôi muốn mua một cái ghế.","lit":"je · vouloir · acheter · un · [classificateur] · chaise"},{"fr":"Il y a deux chats devant la porte.","tgt":"Có hai con mèo trước cửa.","lit":"avoir · deux · [classificateur] · chat · devant · porte"},{"fr":"Ce vélo est déjà vieux.","tgt":"Chiếc xe đạp này cũ rồi.","lit":"[classificateur] · véhicule · pédaler · ceci · vieux · [accompli]"},{"fr":"Tu peux me prêter un stylo ?","tgt":"Bạn cho tôi mượn cái bút được không?","lit":"toi · donner · je · emprunter · [classificateur] · stylo · pouvoir · [question]"},{"fr":"Ce poulet est vraiment gros.","tgt":"Con gà này to quá.","lit":"[classificateur] · poulet · ceci · gros · trop"},{"fr":"Mon voisin a trois scooters.","tgt":"Hàng xóm tôi có ba chiếc xe máy.","lit":"voisin · je · avoir · trois · [classificateur] · véhicule · machine"},{"fr":"Une table et quatre petites chaises en plastique.","tgt":"Một cái bàn và bốn cái ghế nhựa.","lit":"un · [classificateur] · table · et · quatre · [classificateur] · chaise · plastique"},{"fr":"Les scooters passent partout.","tgt":"Xe máy đi khắp nơi.","lit":"véhicule · machine · aller · partout"}],"tip":{"title":"Les classificateurs : « cái », « con », « chiếc »","example":"Je voudrais acheter une chaise. — Tôi muốn mua một <b>cái</b> ghế.","body":"En vietnamien, on ne compte pas les choses directement : entre le nombre et le nom, on glisse un petit mot qui annonce la catégorie, appelé classificateur. Le français fait parfois pareil quand il dit une tête de bétail ou une feuille de papier. « Con » sert pour les animaux : « hai con mèo », deux chats. « Cái » sert pour la plupart des objets : « một cái ghế », une chaise. « Chiếc » s'emploie souvent pour les véhicules : « một chiếc xe máy », un scooter. Décomposons « tôi muốn mua một cái ghế » : je, vouloir, acheter, un, classificateur, chaise. Le classificateur revient aussi avec « này » : « con mèo này », ce chat. Astuce : si vous hésitez pour un objet, « cái » est la valeur sûre.","lit":"je · vouloir · acheter · un · [classificateur] · chaise","say":{"cái":"cái","con":"con","chiếc":"chiếc","Con":"Con","hai con mèo":"hai con mèo","Cái":"Cái","một cái ghế":"một cái ghế","Chiếc":"Chiếc","một chiếc xe máy":"một chiếc xe máy","tôi muốn mua một cái ghế":"tôi muốn mua một cái ghế","này":"này","con mèo này":"con mèo này"}}},{"title":"Ce qu'il y a dans le quartier","phrases":[{"fr":"Près d'ici, il y a un petit marché.","tgt":"Gần đây có một cái chợ nhỏ.","lit":"près · ici · avoir · un · [classificateur] · marché · petit"},{"fr":"Il y a beaucoup de cafés dans cette rue.","tgt":"Phố này có nhiều quán cà phê.","lit":"rue · ceci · avoir · beaucoup · boutique · café"},{"fr":"Ici, il n'y a pas de supermarché.","tgt":"Ở đây không có siêu thị.","lit":"à · ici · pas · avoir · supermarché"},{"fr":"Tu as un vélo ?","tgt":"Bạn có xe đạp không?","lit":"toi · avoir · véhicule · pédaler · [question]"},{"fr":"Non, je n'en ai pas.","tgt":"Không, tôi không có.","lit":"non · je · pas · avoir"},{"fr":"J'ai deux grands frères à Huế.","tgt":"Tôi có hai anh trai ở Huế.","lit":"je · avoir · deux · grand frère · masculin · à · Huế"},{"fr":"Il y a une pharmacie au coin de la rue.","tgt":"Ở góc phố có hiệu thuốc.","lit":"à · coin · rue · avoir · boutique · médicament"},{"fr":"Vous avez du thé vert ?","tgt":"Chị có trà xanh không?","lit":"grande sœur · avoir · thé · vert · [question]"},{"fr":"Ce soir, la rue est pleine de monde.","tgt":"Tối nay ngoài phố có nhiều người.","lit":"soir · ceci · dehors · rue · avoir · beaucoup · personne"},{"fr":"Il n'y a pas d'arbres dans ma rue.","tgt":"Phố tôi không có cây.","lit":"rue · je · pas · avoir · arbre"}],"tip":{"title":"« Có » et « không có » : avoir, et il y a","example":"Tu as un vélo ? — Bạn <b>có</b> xe đạp <b>không</b>?","body":"Le mot « có » fait double emploi : il veut dire avoir, et aussi il y a. « Tôi có xe đạp », j'ai un vélo, et « gần đây có chợ », près d'ici, il y a un marché. Pour la négation, on place « không » devant : « không có », ne pas avoir, ou il n'y a pas. Pour poser la question, on encadre : « bạn có xe đạp không ? », mot à mot toi, avoir, vélo, question, tu as un vélo ? La réponse est toute simple : « có », oui, j'en ai, ou « không », non. Retenez aussi « phố này có nhiều quán cà phê », il y a beaucoup de cafés dans cette rue. Astuce : quand vous cherchez quelque chose, commencez par « có … không ? », c'est la question la plus utile du quartier.","lit":"toi · avoir · véhicule · pédaler · [question]","say":{"Có":"Có","không có":"không có","có":"có","Tôi có xe đạp":"Tôi có xe đạp","gần đây có chợ":"gần đây có chợ","không":"không","bạn có xe đạp không ?":"bạn có xe đạp không ?","phố này có nhiều quán cà phê":"phố này có nhiều quán cà phê","có … không ?":"có … không ?"}}},{"title":"Demander son chemin","phrases":[{"fr":"Excusez-moi, où est le lac Hoàn Kiếm ?","tgt":"Xin lỗi, hồ Hoàn Kiếm ở đâu?","lit":"pardon · lac · Hoàn Kiếm · se trouver · où"},{"fr":"Le lac est tout près d'ici.","tgt":"Hồ ở gần đây thôi.","lit":"lac · se trouver · près · ici · seulement"},{"fr":"Où habites-tu ?","tgt":"Bạn ở đâu?","lit":"toi · habiter · où"},{"fr":"J'habite rue Hàng Gai.","tgt":"Tôi ở phố Hàng Gai.","lit":"je · habiter · rue · Hàng Gai"},{"fr":"La poste est à côté de la banque.","tgt":"Bưu điện ở cạnh ngân hàng.","lit":"poste · se trouver · à côté · banque"},{"fr":"Mes amis sont au café.","tgt":"Các bạn tôi đang ở quán cà phê.","lit":"[pluriel] · ami · je · [en cours] · être à · boutique · café"},{"fr":"Je suis à la maison.","tgt":"Tôi đang ở nhà.","lit":"je · [en cours] · être à · maison"},{"fr":"Au carrefour, tournez à gauche.","tgt":"Đến ngã tư thì rẽ trái.","lit":"arriver · carrefour · alors · tourner · gauche"},{"fr":"Le marché est au bout de la rue.","tgt":"Chợ ở cuối phố.","lit":"marché · se trouver · bout · rue"},{"fr":"Ah, c'est ici !","tgt":"À, ở đây rồi!","lit":"ah · à · ici · [accompli]"}],"tip":{"title":"« Ở » : être à un endroit","example":"J'habite rue Hàng Gai. — Tôi <b>ở</b> phố Hàng Gai.","body":"Le petit mot « ở » indique où l'on se trouve. Selon la phrase, il se traduit par être à, se trouver, habiter, ou simplement à. « Tôi ở phố Hàng Gai », mot à mot je, être à, rue « Hàng Gai », veut dire j'habite rue « Hàng Gai ». « Chợ ở cuối phố », le marché est au bout de la rue. Combiné avec « đâu », où, il donne la question la plus pratique en ville : « hồ Hoàn Kiếm ở đâu ? », où est le lac « Hoàn Kiếm » ? Remarquez que là où le français dit toujours être, le vietnamien dit « ở » pour un lieu, et « là » pour une identité. Astuce : « là » répond à qui ou quoi, « ở » répond à où.","lit":"je · habiter · rue · Hàng Gai","say":{"Ở":"Ở","ở":"ở","Tôi ở phố Hàng Gai":"Tôi ở phố Hàng Gai","Chợ ở cuối phố":"Chợ ở cuối phố","đâu":"đâu","hồ Hoàn Kiếm ở đâu ?":"hồ Hoàn Kiếm ở đâu ?","là":"là"}}},{"title":"Les horaires de la journée","phrases":[{"fr":"Il est quelle heure ?","tgt":"Mấy giờ rồi?","lit":"combien · heure · [accompli]"},{"fr":"Il est déjà sept heures.","tgt":"Bảy giờ rồi.","lit":"sept · heure · [accompli]"},{"fr":"Le petit marché ouvre dès cinq heures du matin.","tgt":"Chợ mở cửa lúc năm giờ sáng.","lit":"marché · ouvrir · porte · à · cinq · heure · matin"},{"fr":"Je bois mon café à huit heures.","tgt":"Tôi uống cà phê lúc tám giờ.","lit":"je · boire · café · à · huit · heure"},{"fr":"Il est neuf heures quinze.","tgt":"Chín giờ mười lăm phút.","lit":"neuf · heure · dix · cinq · minute"},{"fr":"Il est dix heures et demie.","tgt":"Mười giờ rưỡi.","lit":"dix · heure · et demie"},{"fr":"Nous déjeunons à midi.","tgt":"Chúng tôi ăn trưa lúc mười hai giờ.","lit":"nous · manger · midi · à · dix · deux · heure"},{"fr":"Le bus part dans vingt minutes.","tgt":"Hai mươi phút nữa xe buýt chạy.","lit":"deux · dix · minute · encore · bus · partir"},{"fr":"Tu finis le travail à quelle heure ?","tgt":"Mấy giờ bạn tan làm?","lit":"combien · heure · toi · finir · travail"},{"fr":"Je rentre à six heures du soir.","tgt":"Tôi về nhà lúc sáu giờ tối.","lit":"je · rentrer · maison · à · six · heure · soir"}],"tip":{"title":"L'heure : « giờ », « phút », et « mấy giờ rồi »","example":"Il est quelle heure ? — <b>Mấy giờ rồi</b>?","body":"Pour demander l'heure, une seule formule à retenir : « mấy giờ rồi ? », mot à mot combien, heure, déjà, autrement dit il est déjà quelle heure ? On répond avec le nombre devant « giờ », heure : « bảy giờ », sept heures, et on ajoute les minutes avec « phút » : « chín giờ mười lăm phút », neuf heures quinze. Pour la demie, on dit « rưỡi » : « mười giờ rưỡi », dix heures et demie. Pour un rendez-vous, on place « lúc », à, devant l'heure : « lúc tám giờ », à huit heures. Et pour préciser le moment, on ajoute « sáng », matin, ou « tối », soir, à la fin. Astuce : le petit « rồi » de la question rappelle que le temps a déjà avancé.","lit":"combien · heure · [accompli]","say":{"giờ":"giờ","phút":"phút","mấy giờ rồi":"mấy giờ rồi","mấy giờ rồi ?":"mấy giờ rồi ?","bảy giờ":"bảy giờ","chín giờ mười lăm phút":"chín giờ mười lăm phút","rưỡi":"rưỡi","mười giờ rưỡi":"mười giờ rưỡi","lúc":"lúc","lúc tám giờ":"lúc tám giờ","sáng":"sáng","tối":"tối","rồi":"rồi"}}},{"title":"Faire connaissance au café","phrases":[{"fr":"Tu t'appelles comment ?","tgt":"Bạn tên là gì?","lit":"toi · nom · être · quoi"},{"fr":"Tu viens d'où ?","tgt":"Bạn từ đâu đến?","lit":"toi · depuis · où · venir"},{"fr":"Tu fais quoi dans la vie ?","tgt":"Bạn làm nghề gì?","lit":"toi · faire · métier · quoi"},{"fr":"Qui est cette personne-là ?","tgt":"Người kia là ai?","lit":"personne · là-bas · être · qui"},{"fr":"Tu as quel âge, petit ?","tgt":"Cháu mấy tuổi?","lit":"neveu · combien · âge"},{"fr":"Tu bois quoi ?","tgt":"Bạn uống gì?","lit":"toi · boire · quoi"},{"fr":"Tu vis où, à Hanoï ?","tgt":"Ở Hà Nội bạn sống ở đâu?","lit":"à · Hanoï · toi · vivre · à · où"},{"fr":"Tu es venu avec qui ?","tgt":"Bạn đi với ai?","lit":"toi · aller · avec · qui"},{"fr":"Tu as combien de frères et sœurs ?","tgt":"Bạn có mấy anh chị em?","lit":"toi · avoir · combien · grand frère · grande sœur · cadet"},{"fr":"Qu'est-ce que c'est, ça ?","tgt":"Cái này là cái gì?","lit":"[classificateur] · ceci · être · [classificateur] · quoi"}],"tip":{"title":"Les mots interrogatifs : « gì, đâu, ai, mấy »","example":"Tu t'appelles comment ? — Bạn tên là <b>gì</b>?","body":"Pour poser une question ouverte en vietnamien, on garde l'ordre normal de la phrase et on met le mot interrogatif exactement là où viendra la réponse. « Gì » veut dire quoi, « đâu » où, « ai » qui, et « mấy » combien, pour les petits nombres. Décomposons « bạn tên là gì ? » : toi, nom, être, quoi, comment tu t'appelles ? Et la réponse reprend la même place : « tôi tên là Lucie ». De même, « bạn uống gì ? », tu bois quoi ?, et « bạn đi với ai ? », tu es venu avec qui ? « Mấy » sert pour l'heure, les frères et sœurs, ou l'âge d'un enfant : « cháu mấy tuổi ? », tu as quel âge, petit ? Astuce : pensez aux questions familières comme tu fais quoi ?, c'est exactement le même ordre.","lit":"toi · nom · être · quoi","say":{"Gì":"Gì","đâu":"đâu","ai":"ai","mấy":"mấy","bạn tên là gì ?":"bạn tên là gì ?","tôi tên là Lucie":"tôi tên là Lucie","bạn uống gì ?":"bạn uống gì ?","bạn đi với ai ?":"bạn đi với ai ?","Mấy":"Mấy","cháu mấy tuổi ?":"cháu mấy tuổi ?"}}},{"title":"La routine du matin","phrases":[{"fr":"Moi, je me lève à six heures.","tgt":"Tôi dậy lúc sáu giờ.","lit":"je · se lever · à · six · heure"},{"fr":"Ma femme se lève aussi à six heures.","tgt":"Vợ tôi cũng dậy lúc sáu giờ.","lit":"épouse · je · aussi · se lever · à · six · heure"},{"fr":"Le matin, les Hanoïens font du sport autour du lac.","tgt":"Buổi sáng, người Hà Nội tập thể dục quanh hồ.","lit":"moment · matin · personne · Hanoï · pratiquer · exercice · autour · lac"},{"fr":"Nous aimons tous le phở.","tgt":"Chúng tôi đều thích phở.","lit":"nous · tous · aimer · phở"},{"fr":"Moi aussi, j'aime le bánh mì.","tgt":"Tôi cũng thích bánh mì.","lit":"je · aussi · aimer · bánh mì"},{"fr":"Mes deux enfants vont à l'école à pied.","tgt":"Hai đứa con tôi đều đi bộ đến trường.","lit":"deux · [classificateur] · enfant · je · tous · aller · pied · arriver · école"},{"fr":"Mes voisins sont tous très gentils.","tgt":"Hàng xóm của tôi đều rất tốt.","lit":"voisin · de · je · tous · très · bon"},{"fr":"Je prends une douche, puis je m'habille.","tgt":"Tôi tắm rồi mặc quần áo.","lit":"je · se laver · puis · porter · pantalon · vêtement"},{"fr":"Mon mari boit du café, moi aussi.","tgt":"Chồng tôi uống cà phê, tôi cũng vậy.","lit":"mari · je · boire · café · je · aussi · ainsi"},{"fr":"Tous les matins, je pars au travail à sept heures et demie.","tgt":"Sáng nào tôi cũng đi làm lúc bảy giờ rưỡi.","lit":"matin · quel · je · aussi · aller · travailler · à · sept · heure · et demie"}],"tip":{"title":"« Cũng » et « đều » : aussi et tous","example":"Ma femme se lève aussi à six heures. — Vợ tôi <b>cũng</b> dậy lúc sáu giờ.","body":"Pour dire aussi, on utilise « cũng », placé juste devant le verbe, et non à la fin comme souvent en français. « Vợ tôi cũng dậy lúc sáu giờ », mot à mot épouse, je, aussi, se lever, à six heures : ma femme se lève aussi à six heures. Pour dire tous, ou tous les deux, on utilise « đều », lui aussi juste devant le verbe, avec un sujet au pluriel : « chúng tôi đều thích phở », nous aimons tous le « phở ». Pour répondre moi aussi, on dit « tôi cũng vậy ». Une tournure très courante combine « nào » et « cũng » : « sáng nào tôi cũng đi làm », tous les matins, je vais travailler. Astuce : le sujet, puis le petit mot, puis le verbe, toujours dans cet ordre.","lit":"épouse · je · aussi · se lever · à · six · heure","say":{"Cũng":"Cũng","đều":"đều","cũng":"cũng","Vợ tôi cũng dậy lúc sáu giờ":"Vợ tôi cũng dậy lúc sáu giờ","chúng tôi đều thích phở":"chúng tôi đều thích phở","tôi cũng vậy":"tôi cũng vậy","nào":"nào","sáng nào tôi cũng đi làm":"sáng nào tôi cũng đi làm"}}},{"title":"Les courses de la semaine","phrases":[{"fr":"Je veux acheter des fruits.","tgt":"Tôi muốn mua hoa quả.","lit":"je · vouloir · acheter · fleur · fruit"},{"fr":"J'ai besoin de riz et de sauce de poisson.","tgt":"Tôi cần gạo và nước mắm.","lit":"je · avoir besoin · riz · et · eau · poisson fermenté"},{"fr":"Tu veux venir avec moi ?","tgt":"Bạn muốn đi cùng tôi không?","lit":"toi · vouloir · aller · avec · je · [question]"},{"fr":"Nous avons besoin d'un nouveau ventilateur.","tgt":"Chúng tôi cần một cái quạt mới.","lit":"nous · avoir besoin · un · [classificateur] · ventilateur · neuf"},{"fr":"Je n'ai pas besoin de sac en plastique.","tgt":"Tôi không cần túi ni lông.","lit":"je · pas · avoir besoin · sac · nylon"},{"fr":"Elle veut un kilo de tomates.","tgt":"Chị ấy muốn một cân cà chua.","lit":"grande sœur · ce · vouloir · un · kilo · tomate"},{"fr":"Il nous faut combien d'œufs ?","tgt":"Cần mấy quả trứng?","lit":"avoir besoin · combien · [classificateur] · œuf"},{"fr":"J'ai besoin de petite monnaie.","tgt":"Tôi cần tiền lẻ.","lit":"je · avoir besoin · argent · menu"},{"fr":"Tu veux manger quoi ce soir ?","tgt":"Tối nay bạn muốn ăn gì?","lit":"soir · ceci · toi · vouloir · manger · quoi"},{"fr":"Je veux cuisiner un plat vietnamien.","tgt":"Tôi muốn nấu một món Việt Nam.","lit":"je · vouloir · cuisiner · un · plat · Viêt Nam"}],"tip":{"title":"« Muốn » et « cần » : vouloir et avoir besoin","example":"Je veux acheter des fruits. — Tôi <b>muốn</b> mua hoa quả.","body":"Pour exprimer un désir, on place « muốn », vouloir, devant le verbe ou la chose voulue : « tôi muốn mua hoa quả », mot à mot je, vouloir, acheter, fruits, je veux acheter des fruits. Pour un besoin, on utilise « cần », avoir besoin : « tôi cần gạo », j'ai besoin de riz. Aucun petit mot de liaison comme de n'est nécessaire, et le verbe ne change jamais. La négation suit la règle habituelle : « tôi không cần túi ni lông », je n'ai pas besoin de sac en plastique, une phrase précieuse au marché. Pour une question, on ajoute « không » à la fin : « bạn muốn đi cùng tôi không ? », tu veux venir avec moi ? Astuce : « muốn » pour l'envie, « cần » pour la liste de courses.","lit":"je · vouloir · acheter · fleur · fruit","say":{"Muốn":"Muốn","cần":"cần","muốn":"muốn","tôi muốn mua hoa quả":"tôi muốn mua hoa quả","tôi cần gạo":"tôi cần gạo","tôi không cần túi ni lông":"tôi không cần túi ni lông","không":"không","bạn muốn đi cùng tôi không ?":"bạn muốn đi cùng tôi không ?"}}},{"title":"Une soirée entre voisins","phrases":[{"fr":"Allons boire une bière, d'accord ?","tgt":"Chúng ta đi uống bia nhé!","lit":"nous · aller · boire · bière · [adoucissant]"},{"fr":"Viens chez moi ce soir, ça te dit ?","tgt":"Tối nay đến nhà tôi chơi nhé.","lit":"soir · ceci · venir · maison · je · jouer · [adoucissant]"},{"fr":"On se revoit demain, d'accord ?","tgt":"Mai gặp lại nhé!","lit":"demain · voir · de nouveau · [adoucissant]"},{"fr":"Assieds-toi là, je t'en prie.","tgt":"Em ngồi đây nhé.","lit":"cadet · s'asseoir · ici · [adoucissant]"},{"fr":"Reprends-en un peu.","tgt":"Ăn thêm nhé.","lit":"manger · ajouter · [adoucissant]"},{"fr":"Je t'appelle demain, d'accord ?","tgt":"Mai anh gọi em nhé.","lit":"demain · grand frère · appeler · cadet · [adoucissant]"},{"fr":"Attends-moi un petit instant.","tgt":"Chờ tôi một chút nhé.","lit":"attendre · je · un · peu · [adoucissant]"},{"fr":"Rentre bien, fais attention !","tgt":"Về cẩn thận nhé!","lit":"rentrer · prudent · [adoucissant]"},{"fr":"Quelle bonne soirée !","tgt":"Tối nay vui quá!","lit":"soir · ceci · joyeux · trop"},{"fr":"À ta santé !","tgt":"Chúc sức khỏe!","lit":"souhaiter · santé"}],"tip":{"title":"« Nhé » : proposer, adoucir une phrase","example":"Allons boire une bière, d'accord ? — Chúng ta đi uống bia <b>nhé</b>!","body":"Le petit mot « nhé », placé à la fin d'une phrase, est l'un des plus chaleureux du vietnamien. Il transforme un ordre ou une proposition en invitation amicale, un peu comme d'accord ?, hein, ou s'il te plaît en français. « Chúng ta đi uống bia nhé », mot à mot nous, aller, boire, bière, d'accord, veut dire allons boire une bière, ça te dit ? Sans « nhé », la phrase sonnerait plus sèche, presque comme un ordre. On l'utilise aussi pour se dire au revoir : « mai gặp lại nhé », on se revoit demain, ou pour prendre soin de l'autre : « về cẩn thận nhé », rentre bien. Prononcez-le avec un ton qui monte, léger et souriant. Astuce : dans le doute, ajoutez « nhé », vous paraîtrez tout de suite plus gentil.","lit":"nous · aller · boire · bière · [adoucissant]","say":{"Nhé":"Nhé","nhé":"nhé","Chúng ta đi uống bia nhé":"Chúng ta đi uống bia nhé","mai gặp lại nhé":"mai gặp lại nhé","về cẩn thận nhé":"về cẩn thận nhé"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Voilà, notre premier module est terminé.","tgt":"Vậy là học phần đầu tiên đã kết thúc.","lit":"ainsi · être · étudier · partie · premier · [accompli] · terminer"},{"fr":"Je sais dire bonjour en vietnamien.","tgt":"Tôi biết nói xin chào bằng tiếng Việt.","lit":"je · savoir · dire · bonjour · par · langue · Viêt"},{"fr":"Merci beaucoup à toi !","tgt":"Cảm ơn bạn rất nhiều!","lit":"merci · toi · très · beaucoup"},{"fr":"Pardon, je suis en retard.","tgt":"Xin lỗi, tôi đến muộn.","lit":"pardon · je · arriver · tard"},{"fr":"Ce n'est pas grave du tout.","tgt":"Không sao đâu.","lit":"pas · quoi · [insistance]"},{"fr":"Le vietnamien a six tons.","tgt":"Tiếng Việt có sáu thanh điệu.","lit":"langue · Viêt · avoir · six · ton"},{"fr":"Maintenant, je connais mes voisins.","tgt":"Bây giờ tôi đã quen hàng xóm rồi.","lit":"maintenant · je · [accompli] · connaître · voisin · [accompli]"},{"fr":"Ensuite, on part en voyage !","tgt":"Tiếp theo, chúng ta đi du lịch!","lit":"ensuite · nous · aller · voyager"},{"fr":"Au revoir, et à très bientôt à Hanoï !","tgt":"Tạm biệt, hẹn gặp lại ở Hà Nội!","lit":"au revoir · promettre · voir · de nouveau · à · Hanoï"},{"fr":"Bravo, tu es vraiment doué !","tgt":"Bạn giỏi lắm!","lit":"toi · doué · très"}],"tip":{"title":"Les formules magiques : « xin chào, cảm ơn, xin lỗi, không sao »","example":"Ce n'est pas grave du tout. — <b>Không sao</b> đâu.","body":"Quatre petites formules suffisent à ouvrir bien des portes à Hanoï. « Xin chào » veut dire bonjour, et l'on dit plus souvent « chào » suivi du bon pronom, comme « chào anh » ou « chào chị ». « Cảm ơn » veut dire merci, et « cảm ơn nhiều », merci beaucoup. « Xin lỗi » sert à s'excuser, mais aussi à attirer l'attention, comme excusez-moi. Et la réponse idéale à une excuse, c'est « không sao », mot à mot pas quoi, autrement dit ce n'est rien. Décomposons « không sao đâu » : pas, quoi, et « đâu » qui insiste, ce n'est vraiment pas grave. Ajoutez un sourire et le bon pronom, et ces formules feront de vous un voisin apprécié. Astuce : dites-les dès aujourd'hui, au marché ou au café, c'est en les répétant qu'elles deviennent naturelles.","lit":"pas · quoi · [insistance]","say":{"Xin chào":"Xin chào","chào":"chào","chào anh":"chào anh","chào chị":"chào chị","Cảm ơn":"Cảm ơn","cảm ơn nhiều":"cảm ơn nhiều","Xin lỗi":"Xin lỗi","không sao":"không sao","không sao đâu":"không sao đâu","đâu":"đâu"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus au Viêt Nam.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport de Saïgon","phrases":[{"fr":"Bonjour, voici mon passeport.","tgt":"Xin chào, đây là hộ chiếu của tôi.","lit":"bonjour · ceci · être · passeport · de · moi"},{"fr":"Vous êtes de quel pays ?","tgt":"Anh là người nước nào?","lit":"grand frère (vous) · être · personne · pays · quel"},{"fr":"Je suis français, je suis ici en touriste.","tgt":"Tôi là người Pháp, tôi đi du lịch.","lit":"je · être · personne · France · je · aller · voyager"},{"fr":"Vous restez ici combien de jours ?","tgt":"Anh ở mấy ngày?","lit":"grand frère (vous) · rester · combien · jour"},{"fr":"Je reste dix jours en tout.","tgt":"Tôi ở mười ngày.","lit":"je · rester · dix · jour"},{"fr":"Où est-ce qu'on récupère les bagages ?","tgt":"Lấy hành lý ở đâu?","lit":"prendre · bagages · à · où"},{"fr":"Ma valise est ici.","tgt":"Va li của tôi ở đây.","lit":"valise · de · moi · se trouver · ici"},{"fr":"Excusez-moi, où est la sortie ?","tgt":"Xin hỏi, lối ra ở đâu?","lit":"prier · demander · passage · sortir · se trouver · où"},{"fr":"Qu'il fait chaud à Saïgon !","tgt":"Sài Gòn nóng quá!","lit":"Saïgon · chaud · trop"},{"fr":"Bienvenue au Viêt Nam !","tgt":"Chào mừng anh đến Việt Nam!","lit":"bienvenue · grand frère (vous) · arriver · Viêt Nam"}]},{"title":"Premier jour à Saïgon","phrases":[{"fr":"Aujourd'hui, je visite Saïgon.","tgt":"Hôm nay tôi đi thăm Sài Gòn.","lit":"aujourd'hui · je · aller · visiter · Saïgon"},{"fr":"Je suis arrivé hier soir.","tgt":"Tôi đến tối hôm qua.","lit":"je · arriver · soir · hier"},{"fr":"Demain, je vais au marché Bến Thành.","tgt":"Ngày mai tôi đi chợ Bến Thành.","lit":"demain · je · aller · marché · Bến Thành"},{"fr":"Aujourd'hui, le ciel est magnifique.","tgt":"Hôm nay trời đẹp.","lit":"aujourd'hui · ciel · beau"},{"fr":"Hier, il a plu toute la nuit.","tgt":"Hôm qua trời mưa cả đêm.","lit":"hier · ciel · pleuvoir · toute · nuit"},{"fr":"Aujourd'hui, on est quel jour de la semaine ?","tgt":"Hôm nay là thứ mấy?","lit":"aujourd'hui · être · jour n° · combien"},{"fr":"Aujourd'hui, on est samedi.","tgt":"Hôm nay là thứ bảy.","lit":"aujourd'hui · être · jour n° · sept"},{"fr":"Et demain, c'est dimanche.","tgt":"Còn ngày mai là chủ nhật.","lit":"et · demain · être · dimanche"},{"fr":"Tu es libre demain matin ?","tgt":"Sáng mai em có rảnh không?","lit":"matin · demain · petit frère (tu) · [est-ce] · libre · [question]"},{"fr":"Hier, j'étais vraiment épuisé.","tgt":"Hôm qua tôi mệt quá.","lit":"hier · je · fatigué · trop"}],"tip":{"title":"« Hôm nay », « ngày mai », « hôm qua » : aujourd'hui, demain, hier","example":"Demain, je vais au marché Bến Thành. — <b>Ngày mai</b> tôi đi chợ Bến Thành.","body":"En vietnamien, le verbe ne change jamais : c'est le mot de temps qui dit si l'on parle d'hier, d'aujourd'hui ou de demain. Retenez trois mots : « hôm nay », aujourd'hui, « ngày mai », demain, et « hôm qua », hier. On les place le plus souvent au tout début de la phrase, comme en français quand on dit demain, je pars. Prenons « ngày mai tôi đi chợ Bến Thành » : mot à mot demain, je, aller, marché « Bến Thành ». Le verbe « đi », aller, reste identique ; seul « ngày mai » nous dit que c'est pour demain. De même, « hôm qua tôi rất mệt » veut dire hier j'étais très fatigué, et « hôm nay trời đẹp », aujourd'hui il fait beau. Pour un moment de la journée, on met ce moment devant : « sáng mai », demain matin, « tối qua », hier soir. Astuce : le mot « qua » veut aussi dire passer, alors hier, c'est tout simplement le jour qui est passé.","lit":"demain · je · aller · marché · Bến Thành","say":{"Hôm nay":"Hôm nay","ngày mai":"ngày mai","hôm qua":"hôm qua","hôm nay":"hôm nay","ngày mai tôi đi chợ Bến Thành":"ngày mai tôi đi chợ Bến Thành","đi":"đi","hôm qua tôi rất mệt":"hôm qua tôi rất mệt","hôm nay trời đẹp":"hôm nay trời đẹp","sáng mai":"sáng mai","tối qua":"tối qua","qua":"qua"}}},{"title":"Le taxi depuis l'aéroport","phrases":[{"fr":"Je voudrais prendre un taxi.","tgt":"Tôi muốn đi tắc xi.","lit":"je · vouloir · aller · taxi"},{"fr":"Bonjour monsieur, vous allez où ?","tgt":"Chào anh, anh đi đâu?","lit":"bonjour · grand frère · grand frère (vous) · aller · où"},{"fr":"Emmenez-moi à cet hôtel.","tgt":"Cho tôi đến khách sạn này.","lit":"donner · moi · arriver · hôtel · ce"},{"fr":"Voici l'adresse.","tgt":"Đây là địa chỉ.","lit":"ceci · être · adresse"},{"fr":"C'est loin, monsieur ?","tgt":"Có xa không anh?","lit":"[est-ce] · loin · [question] · grand frère"},{"fr":"Une trentaine de minutes.","tgt":"Khoảng ba mươi phút.","lit":"environ · trois · dix · minute"},{"fr":"Mettez le compteur, s'il vous plaît.","tgt":"Anh bật đồng hồ nhé.","lit":"grand frère (vous) · allumer · compteur · [d'accord ?]"},{"fr":"Que de scooters dans la rue !","tgt":"Ngoài đường nhiều xe máy quá!","lit":"dehors · rue · beaucoup · moto · trop"},{"fr":"Arrêtez-vous ici.","tgt":"Anh dừng ở đây nhé.","lit":"grand frère (vous) · s'arrêter · à · ici · [d'accord ?]"},{"fr":"Merci, gardez la monnaie.","tgt":"Cảm ơn anh, anh giữ tiền thừa nhé.","lit":"merci · grand frère · grand frère (vous) · garder · argent · en trop · [d'accord ?]"}]},{"title":"À la réception de l'hôtel","phrases":[{"fr":"Bonsoir madame, j'ai une réservation.","tgt":"Chào chị, tôi có đặt phòng.","lit":"bonjour · grande sœur · je · [bien] · réserver · chambre"},{"fr":"Votre nom, s'il vous plaît ?","tgt":"Anh vui lòng cho em xin tên ạ.","lit":"grand frère (vous) · bien vouloir · donner · moi (petite sœur) · demander · nom · [politesse]"},{"fr":"Je m'appelle Pierre Martin.","tgt":"Tôi tên là Pierre Martin.","lit":"je · nom · être · Pierre Martin"},{"fr":"Pourriez-vous me montrer votre passeport ?","tgt":"Anh vui lòng cho em xem hộ chiếu ạ.","lit":"grand frère (vous) · bien vouloir · donner · moi (petite sœur) · voir · passeport · [politesse]"},{"fr":"Merci de patienter une petite minute.","tgt":"Anh vui lòng chờ một chút.","lit":"grand frère (vous) · bien vouloir · attendre · un · peu"},{"fr":"Une chambre calme, s'il vous plaît.","tgt":"Làm ơn cho tôi một phòng yên tĩnh.","lit":"faire · faveur · donner · moi · une · chambre · calme"},{"fr":"Le petit-déjeuner, c'est à quelle heure ici ?","tgt":"Bữa sáng lúc mấy giờ?","lit":"repas · matin · à · combien · heure"},{"fr":"Et le mot de passe du wifi ?","tgt":"Còn mật khẩu wifi là gì ạ?","lit":"et · mot de passe · wifi · être · quoi · [politesse]"},{"fr":"S'il vous plaît, aidez-moi à monter ma valise.","tgt":"Làm ơn giúp tôi mang va li lên.","lit":"faire · faveur · aider · moi · porter · valise · monter"},{"fr":"Voici votre clé, chambre trois cent deux.","tgt":"Đây là chìa khóa, phòng ba trăm linh hai.","lit":"ceci · être · clé · chambre · trois · cent · zéro · deux"}],"tip":{"title":"« Làm ơn » et « vui lòng » : s'il vous plaît","example":"Une chambre calme, s'il vous plaît. — <b>Làm ơn</b> cho tôi một phòng yên tĩnh.","body":"Pour dire s'il vous plaît, le vietnamien a deux formules. « Làm ơn », mot à mot faire une faveur, se place en tête de phrase quand vous demandez un service : « làm ơn cho tôi một phòng yên tĩnh », s'il vous plaît, donnez-moi une chambre calme. « Vui lòng », mot à mot avoir le cœur content, est plus formel : c'est ce que dit le personnel de l'hôtel, avec le pronom devant, comme dans « anh vui lòng chờ một chút », veuillez patienter un instant. Vous l'entendrez beaucoup à la réception, à l'aéroport et dans les annonces. Au quotidien, les Vietnamiens disent aussi très souvent « cho tôi », donnez-moi, suivi de ce qu'ils veulent : « cho tôi một vé », un billet, s'il vous plaît. Pour rester bien poli, ajoutez à la fin le petit mot « ạ », qui marque le respect. Astuce : « làm ơn » quand c'est vous qui demandez, « vui lòng » quand on vous prie de faire quelque chose.","lit":"faire · faveur · donner · moi · une · chambre · calme","say":{"Làm ơn":"Làm ơn","vui lòng":"vui lòng","làm ơn cho tôi một phòng yên tĩnh":"làm ơn cho tôi một phòng yên tĩnh","Vui lòng":"Vui lòng","anh vui lòng chờ một chút":"anh vui lòng chờ một chút","cho tôi":"cho tôi","cho tôi một vé":"cho tôi một vé","ạ":"ạ","làm ơn":"làm ơn"}}},{"title":"Dans la chambre d'hôtel","phrases":[{"fr":"La chambre est très propre.","tgt":"Phòng rất sạch.","lit":"chambre · très · propre"},{"fr":"La clim de la chambre ne marche pas.","tgt":"Điều hòa trong phòng không chạy.","lit":"climatiseur · dans · chambre · [négation] · fonctionner"},{"fr":"Il n'y a pas d'eau chaude dans la douche.","tgt":"Vòi sen không có nước nóng.","lit":"pomme de douche · [négation] · avoir · eau · chaud"},{"fr":"Vous pouvez monter voir ?","tgt":"Chị lên xem giúp tôi nhé.","lit":"grande sœur (vous) · monter · voir · aider · moi · [d'accord ?]"},{"fr":"Il me faut deux serviettes de plus.","tgt":"Tôi cần thêm hai cái khăn tắm.","lit":"je · avoir besoin · ajouter · deux · [classificateur] · serviette de bain"},{"fr":"La fenêtre donne sur la rue.","tgt":"Cửa sổ nhìn ra đường.","lit":"fenêtre · regarder · sortir · rue"},{"fr":"C'est un peu bruyant la nuit.","tgt":"Ban đêm hơi ồn.","lit":"nuit · un peu · bruyant"},{"fr":"Où est l'interrupteur de la lumière ?","tgt":"Công tắc đèn ở đâu?","lit":"interrupteur · lampe · se trouver · où"},{"fr":"Le lit est grand et confortable.","tgt":"Giường to và êm.","lit":"lit · grand · et · moelleux"},{"fr":"Cette chambre me plaît bien.","tgt":"Tôi thích phòng này.","lit":"je · aimer · chambre · ce"}]},{"title":"Au marché Bến Thành","phrases":[{"fr":"Le marché Bến Thành est immense !","tgt":"Chợ Bến Thành to quá!","lit":"marché · Bến Thành · grand · trop"},{"fr":"Et celui-ci, il fait combien ?","tgt":"Cái này bao nhiêu tiền?","lit":"[classificateur] · ce · combien · argent"},{"fr":"Cinquante mille dongs.","tgt":"Năm mươi nghìn đồng.","lit":"cinq · dix · mille · dong"},{"fr":"Et ce chapeau conique, combien ?","tgt":"Còn cái nón này bao nhiêu tiền?","lit":"et · [classificateur] · chapeau conique · ce · combien · argent"},{"fr":"Combien coûte un kilo de mangues ?","tgt":"Một cân xoài bao nhiêu tiền?","lit":"un · kilo · mangue · combien · argent"},{"fr":"Soixante mille dongs le kilo.","tgt":"Sáu mươi nghìn một cân.","lit":"six · dix · mille · un · kilo"},{"fr":"Combien pour les deux ?","tgt":"Hai cái bao nhiêu tiền?","lit":"deux · [classificateur] · combien · argent"},{"fr":"Je prends un kilo.","tgt":"Tôi lấy một cân.","lit":"je · prendre · un · kilo"},{"fr":"Je vous dois combien pour le tout ?","tgt":"Tất cả bao nhiêu tiền?","lit":"tout · combien · argent"},{"fr":"Ça fait cent vingt mille dongs.","tgt":"Hết một trăm hai mươi nghìn.","lit":"en tout · un · cent · deux · dix · mille"}],"tip":{"title":"« Bao nhiêu tiền » : demander un prix, les dongs","example":"Et celui-ci, il fait combien ? — Cái này <b>bao nhiêu tiền</b>?","body":"Pour demander un prix, on dit « bao nhiêu tiền », mot à mot combien d'argent, et on le place après la chose dont on parle. « Cái này bao nhiêu tiền ? », c'est combien, celui-ci ? Mot à mot : classificateur, ce, combien, argent. Pas besoin du verbe coûter : la phrase est complète ainsi. La monnaie s'appelle « đồng », le dong, et les prix se comptent en milliers, « nghìn ». Cinquante mille dongs se dit « năm mươi nghìn đồng », mot à mot cinq, dix, mille, dong. Au marché, on laisse souvent tomber « đồng » : la vendeuse dira simplement « năm mươi nghìn ». Pour le total, demandez « tất cả bao nhiêu tiền ? », combien en tout. Attention au ton de « tiền », qui descend doucement, comme une voix qui se pose. Astuce : « bao nhiêu », combien, sert aussi pour l'âge ou pour compter des personnes, vous le réutiliserez partout.","lit":"[classificateur] · ce · combien · argent","say":{"Bao nhiêu tiền":"Bao nhiêu tiền","bao nhiêu tiền":"bao nhiêu tiền","Cái này bao nhiêu tiền ?":"Cái này bao nhiêu tiền ?","đồng":"đồng","nghìn":"nghìn","năm mươi nghìn đồng":"năm mươi nghìn đồng","năm mươi nghìn":"năm mươi nghìn","tất cả bao nhiêu tiền ?":"tất cả bao nhiêu tiền ?","tiền":"tiền","bao nhiêu":"bao nhiêu"}}},{"title":"Marchander au marché","phrases":[{"fr":"C'est trop cher !","tgt":"Đắt quá!","lit":"cher · trop"},{"fr":"Vous me faites un petit prix ?","tgt":"Chị bớt cho em một chút nhé?","lit":"grande sœur (vous) · réduire · pour · moi (petit frère) · un · peu · [d'accord ?]"},{"fr":"Quarante mille, ça vous va ?","tgt":"Bốn mươi nghìn, được không chị?","lit":"quatre · dix · mille · possible · [question] · grande sœur"},{"fr":"Non, c'est déjà le prix le plus bas.","tgt":"Không được, giá này rẻ nhất rồi.","lit":"[négation] · possible · prix · ce · bon marché · le plus · [déjà]"},{"fr":"Bon, d'accord pour quarante-cinq mille.","tgt":"Thôi, chị bán cho em bốn mươi lăm nghìn.","lit":"bon · grande sœur (moi) · vendre · pour · petit frère (toi) · quatre · dix · cinq · mille"},{"fr":"Entendu, je le prends.","tgt":"Vâng, em lấy.","lit":"oui · moi (petit frère) · prendre"},{"fr":"Vous l'avez dans une autre couleur ?","tgt":"Chị có màu khác không?","lit":"grande sœur (vous) · avoir · couleur · autre · [question]"},{"fr":"Je préfère le rouge.","tgt":"Em thích màu đỏ hơn.","lit":"moi (petit frère) · aimer · couleur · rouge · plus"},{"fr":"Je vais y réfléchir.","tgt":"Để em suy nghĩ thêm.","lit":"laisser · moi (petit frère) · réfléchir · encore"},{"fr":"Merci, au revoir madame !","tgt":"Cảm ơn chị, em chào chị!","lit":"merci · grande sœur · moi (petit frère) · saluer · grande sœur"}]},{"title":"De l'hôtel à la gare","phrases":[{"fr":"Le marché ouvre de six heures du matin à sept heures du soir.","tgt":"Chợ mở cửa từ sáu giờ sáng đến bảy giờ tối.","lit":"marché · ouvrir · porte · de · six · heure · matin · à · sept · heure · soir"},{"fr":"De l'hôtel au marché, il faut dix minutes à pied.","tgt":"Từ khách sạn đến chợ đi bộ mất mười phút.","lit":"de · hôtel · à · marché · aller · pied · prendre · dix · minute"},{"fr":"Combien de temps faut-il de Saïgon à Mũi Né ?","tgt":"Từ Sài Gòn đến Mũi Né mất bao lâu?","lit":"de · Saïgon · à · Mũi Né · prendre · combien · longtemps"},{"fr":"Environ quatre heures.","tgt":"Khoảng bốn tiếng.","lit":"environ · quatre · heure"},{"fr":"Je reste ici du lundi au vendredi.","tgt":"Tôi ở đây từ thứ hai đến thứ sáu.","lit":"je · rester · ici · de · jour n° · deux · à · jour n° · six"},{"fr":"Le musée fait une pause de midi à une heure et demie.","tgt":"Bảo tàng nghỉ trưa từ mười hai giờ đến một giờ rưỡi.","lit":"musée · se reposer · midi · de · douze · heure · à · une · heure · et demie"},{"fr":"Le taxi de l'aéroport à l'hôtel, c'est cher ?","tgt":"Đi tắc xi từ sân bay đến khách sạn có đắt không?","lit":"aller · taxi · de · aéroport · à · hôtel · [est-ce] · cher · [question]"},{"fr":"Le car part de quelle gare routière ?","tgt":"Xe đi từ bến xe nào?","lit":"véhicule · partir · de · gare routière · quel"},{"fr":"Du matin au soir, la rue est pleine de monde.","tgt":"Từ sáng đến tối phố rất đông.","lit":"de · matin · à · soir · rue · très · bondé"},{"fr":"Le petit-déjeuner est servi de six heures à neuf heures.","tgt":"Bữa sáng phục vụ từ sáu giờ đến chín giờ.","lit":"repas · matin · servir · de · six · heure · à · neuf · heure"}],"tip":{"title":"« Từ… đến… » : de… à…","example":"De l'hôtel au marché, il faut dix minutes à pied. — <b>Từ</b> khách sạn <b>đến</b> chợ đi bộ mất mười phút.","body":"Pour dire de… à…, le vietnamien utilise « từ », depuis, et « đến », jusqu'à. La construction suit exactement l'ordre du français : « từ khách sạn đến chợ », de l'hôtel au marché, mot à mot depuis, hôtel, jusqu'à, marché. Elle marche pour les lieux comme pour le temps : « từ sáu giờ đến chín giờ », de six heures à neuf heures, ou « từ thứ hai đến thứ sáu », du lundi au vendredi. Pour dire combien de temps prend un trajet, ajoutez « mất », qui veut dire ici prendre du temps : « từ Sài Gòn đến Mũi Né mất bao lâu ? », combien de temps faut-il de Saïgon à « Mũi Né » ? Notez que « đến » est aussi le verbe arriver, ce qui le rend très facile à retenir. À l'oral, dites « từ » avec un ton qui descend, et « đến » avec un ton qui monte. Astuce : imaginez un trait tiré sur une carte, « từ » au départ, « đến » à l'arrivée.","lit":"de · hôtel · à · marché · aller · pied · prendre · dix · minute","say":{"Từ… đến…":"Từ… đến…","từ":"từ","đến":"đến","từ khách sạn đến chợ":"từ khách sạn đến chợ","từ sáu giờ đến chín giờ":"từ sáu giờ đến chín giờ","từ thứ hai đến thứ sáu":"từ thứ hai đến thứ sáu","mất":"mất","từ Sài Gòn đến Mũi Né mất bao lâu ?":"từ Sài Gòn đến Mũi Né mất bao lâu ?"}}},{"title":"Un bánh mì dans la rue","phrases":[{"fr":"Ça sent vraiment bon ici !","tgt":"Ở đây thơm quá!","lit":"à · ici · parfumé · trop"},{"fr":"Un bánh mì, s'il vous plaît.","tgt":"Cho em một cái bánh mì ạ.","lit":"donner · moi (petit frère) · un · [classificateur] · bánh mì · [politesse]"},{"fr":"Tu veux du pâté et de la viande ?","tgt":"Em ăn pa tê với thịt không?","lit":"petit frère (tu) · manger · pâté · avec · viande · [question]"},{"fr":"Oui, mais sans piment.","tgt":"Dạ có, nhưng đừng cho ớt nhé.","lit":"[politesse] · oui · mais · ne pas · mettre · piment · [d'accord ?]"},{"fr":"Juste un peu de coriandre.","tgt":"Cho ít rau mùi thôi.","lit":"mettre · peu · coriandre · [seulement]"},{"fr":"Il coûte combien, le bánh mì ?","tgt":"Bánh mì bao nhiêu tiền một cái?","lit":"bánh mì · combien · argent · un · [classificateur]"},{"fr":"Vingt-cinq mille dongs.","tgt":"Hai mươi lăm nghìn.","lit":"deux · dix · cinq · mille"},{"fr":"Je m'assois pour manger ici.","tgt":"Em ngồi ăn ở đây.","lit":"moi (petit frère) · s'asseoir · manger · à · ici"},{"fr":"C'est drôlement bon !","tgt":"Ngon quá!","lit":"délicieux · trop"},{"fr":"Et un café glacé en plus.","tgt":"Thêm một cốc cà phê đá nữa.","lit":"ajouter · un · verre · café · glace · encore"}]},{"title":"Une journée bien remplie","phrases":[{"fr":"J'ai déjà visité le marché.","tgt":"Tôi đã đi chợ rồi.","lit":"je · [accompli] · aller · marché · [déjà]"},{"fr":"Tu as déjà mangé, toi ?","tgt":"Em ăn cơm chưa?","lit":"petit frère (tu) · manger · riz · [question : pas encore ?]"},{"fr":"Oui, j'ai mangé.","tgt":"Em ăn rồi ạ.","lit":"moi (petit frère) · manger · [déjà] · [politesse]"},{"fr":"Ce matin, j'ai bu un café glacé.","tgt":"Sáng nay tôi đã uống cà phê đá.","lit":"matin · ce · je · [accompli] · boire · café · glace"},{"fr":"Le bus est déjà parti !","tgt":"Xe buýt đi rồi!","lit":"bus · partir · [déjà]"},{"fr":"J'ai acheté deux chemises au marché.","tgt":"Tôi đã mua hai cái áo ở chợ.","lit":"je · [accompli] · acheter · deux · [classificateur] · chemise · à · marché"},{"fr":"Tu as acheté les billets ?","tgt":"Anh mua vé chưa?","lit":"grand frère (tu) · acheter · billet · [question : pas encore ?]"},{"fr":"Non, toujours pas.","tgt":"Chưa, anh chưa mua.","lit":"[pas encore] · moi (grand frère) · [pas encore] · acheter"},{"fr":"Nous avons beaucoup marché aujourd'hui.","tgt":"Hôm nay chúng tôi đã đi bộ nhiều.","lit":"aujourd'hui · nous · [accompli] · marcher · beaucoup"},{"fr":"Il est déjà dix heures du soir.","tgt":"Mười giờ tối rồi.","lit":"dix · heure · soir · [déjà]"}],"tip":{"title":"« Đã » et « rồi » : l'action accomplie","example":"J'ai déjà visité le marché. — Tôi <b>đã</b> đi chợ <b>rồi</b>.","body":"Le verbe vietnamien ne se conjugue pas, alors comment dire qu'une action est faite ? On utilise deux petits mots. « Đã » se place juste avant le verbe et marque l'action accomplie ; « rồi » se place en fin de phrase et veut dire déjà. Souvent, on les combine : « tôi đã đi chợ rồi », j'ai déjà visité le marché, mot à mot je, accompli, aller, marché, déjà. À l'oral, « rồi » tout seul suffit très souvent : « em ăn rồi », j'ai mangé. Pour demander si c'est fait, on termine la question par « chưa », pas encore : « anh mua vé chưa ? », tu as acheté les billets ? On répond « rồi » pour dire oui, c'est fait, ou « chưa » pour dire non, pas encore. Quand le moment est déjà clair, avec « hôm qua » par exemple, on peut même se passer de « đã ». Astuce : « rồi » ferme la phrase comme une porte qu'on referme derrière une chose terminée.","lit":"je · [accompli] · aller · marché · [déjà]","say":{"Đã":"Đã","rồi":"rồi","tôi đã đi chợ rồi":"tôi đã đi chợ rồi","em ăn rồi":"em ăn rồi","chưa":"chưa","anh mua vé chưa ?":"anh mua vé chưa ?","hôm qua":"hôm qua","đã":"đã"}}},{"title":"En scooter-taxi","phrases":[{"fr":"Je prends un scooter-taxi.","tgt":"Tôi đi xe ôm.","lit":"je · aller · véhicule · enlacer (moto-taxi)"},{"fr":"Mets bien le casque.","tgt":"Đội mũ bảo hiểm vào nhé.","lit":"coiffer · casque · [bien en place] · [d'accord ?]"},{"fr":"Tiens-toi bien !","tgt":"Ngồi chắc vào nhé!","lit":"s'asseoir · solide · [bien en place] · [d'accord ?]"},{"fr":"Moins vite, s'il vous plaît !","tgt":"Anh đi chậm thôi!","lit":"grand frère (vous) · aller · lent · [seulement]"},{"fr":"Tournez à gauche ici.","tgt":"Rẽ trái ở đây.","lit":"tourner · gauche · à · ici"},{"fr":"Ensuite, continuez tout droit.","tgt":"Rồi đi thẳng.","lit":"ensuite · aller · droit"},{"fr":"Il y a tellement de circulation !","tgt":"Đường đông xe quá!","lit":"rue · bondé · véhicule · trop"},{"fr":"On arrive bientôt, monsieur ?","tgt":"Sắp đến chưa anh?","lit":"bientôt · arriver · [question : pas encore ?] · grand frère"},{"fr":"Voilà, on est arrivés.","tgt":"Đến nơi rồi.","lit":"arriver · endroit · [déjà]"},{"fr":"Ça fait combien pour la course ?","tgt":"Cuốc xe này bao nhiêu tiền?","lit":"course · véhicule · ce · combien · argent"}]},{"title":"Demander son chemin","phrases":[{"fr":"Pardon, je me suis perdu.","tgt":"Xin lỗi, tôi bị lạc đường.","lit":"pardon · je · [subir] · s'égarer · chemin"},{"fr":"Comment dit-on « gare » en vietnamien ?","tgt":"« Gare » tiếng Việt nói thế nào?","lit":"« gare » · langue · Viêt · dire · comment"},{"fr":"Comment va-t-on au marché Bến Thành ?","tgt":"Đến chợ Bến Thành đi thế nào ạ?","lit":"arriver · marché · Bến Thành · aller · comment · [politesse]"},{"fr":"Allez tout droit, puis tournez à droite.","tgt":"Anh đi thẳng, rồi rẽ phải.","lit":"grand frère (vous) · aller · droit · ensuite · tourner · droite"},{"fr":"C'est à côté du parc, c'est ça ?","tgt":"Ở cạnh công viên à?","lit":"se trouver · à côté · parc · [question surprise]"},{"fr":"Comment s'appelle cette rue ?","tgt":"Phố này tên là gì?","lit":"rue · ce · nom · être · quoi"},{"fr":"Comment trouvez-vous Saïgon ?","tgt":"Anh thấy Sài Gòn thế nào?","lit":"grand frère (vous) · trouver · Saïgon · comment"},{"fr":"Je ne comprends pas, vous pouvez répéter ?","tgt":"Tôi không hiểu, anh nói lại được không?","lit":"je · [négation] · comprendre · grand frère (vous) · dire · de nouveau · possible · [question]"},{"fr":"Vous pouvez me montrer sur la carte ?","tgt":"Anh chỉ trên bản đồ giúp tôi nhé.","lit":"grand frère (vous) · montrer · sur · carte · aider · moi · [d'accord ?]"},{"fr":"Merci, monsieur, de m'avoir aidé.","tgt":"Cảm ơn anh đã giúp tôi.","lit":"merci · grand frère · [accompli] · aider · moi"}],"tip":{"title":"« Thế nào » : comment, et demander son chemin","example":"Comment va-t-on au marché Bến Thành ? — Đến chợ Bến Thành đi <b>thế nào</b> ạ?","body":"« Thế nào » veut dire comment, et il se place à la fin de la phrase, là où le français le met au début. Pour demander votre chemin, dites d'abord le lieu, puis « đi thế nào », mot à mot aller comment. Par exemple « đến chợ Bến Thành đi thế nào ạ ? », comment va-t-on au marché « Bến Thành » ? Mot à mot : arriver, marché « Bến Thành », aller, comment, politesse. Le même mot sert à demander un avis : « anh thấy Sài Gòn thế nào ? », comment trouvez-vous Saïgon ? Et pour apprendre un mot, demandez « tiếng Việt nói thế nào ? », comment le dit-on en vietnamien ? Retenez aussi les réponses qu'on vous fera : « đi thẳng », tout droit, « rẽ trái », à gauche, et « rẽ phải », à droite. Astuce : en vietnamien, le mot de la question tombe à la fin, comme la chute d'une petite histoire.","lit":"arriver · marché · Bến Thành · aller · comment · [politesse]","say":{"Thế nào":"Thế nào","đi thế nào":"đi thế nào","đến chợ Bến Thành đi thế nào ạ ?":"đến chợ Bến Thành đi thế nào ạ ?","anh thấy Sài Gòn thế nào ?":"anh thấy Sài Gòn thế nào ?","tiếng Việt nói thế nào ?":"tiếng Việt nói thế nào ?","đi thẳng":"đi thẳng","rẽ trái":"rẽ trái","rẽ phải":"rẽ phải"}}},{"title":"Flâner dans le centre","phrases":[{"fr":"Allons flâner au bord de la rivière.","tgt":"Mình đi dạo bờ sông đi.","lit":"nous · aller · flâner · rive · rivière · [allez]"},{"fr":"La rue des livres est vraiment agréable.","tgt":"Phố sách dễ chịu thật.","lit":"rue · livre · agréable · vraiment"},{"fr":"Il y a plein de cafés dans ce quartier.","tgt":"Khu này có nhiều quán cà phê.","lit":"quartier · ce · avoir · beaucoup · établissement · café"},{"fr":"On s'assoit un moment ?","tgt":"Mình ngồi nghỉ một lát nhé?","lit":"nous · s'asseoir · se reposer · un · moment · [d'accord ?]"},{"fr":"Je voudrais prendre une photo.","tgt":"Tôi muốn chụp ảnh.","lit":"je · vouloir · photographier · image"},{"fr":"Vous pouvez me prendre en photo ?","tgt":"Anh chụp giúp tôi một tấm ảnh nhé?","lit":"grand frère (vous) · photographier · aider · moi · un · [classificateur] · photo · [d'accord ?]"},{"fr":"Ce bâtiment est superbe.","tgt":"Tòa nhà này đẹp quá.","lit":"[classificateur] · bâtiment · ce · beau · trop"},{"fr":"C'est la grande poste de la ville.","tgt":"Đây là bưu điện thành phố.","lit":"ceci · être · poste · ville"},{"fr":"Tiens, voilà la pluie qui commence.","tgt":"Ơ, trời bắt đầu mưa rồi.","lit":"tiens · ciel · commencer · pleuvoir · [déjà]"},{"fr":"Abritons-nous dans ce café.","tgt":"Mình vào quán này trú mưa đi.","lit":"nous · entrer · établissement · ce · s'abriter · pluie · [allez]"}]},{"title":"À la gare de Saïgon","phrases":[{"fr":"Je peux acheter un billet ici ?","tgt":"Tôi có thể mua vé ở đây không?","lit":"je · pouvoir · acheter · billet · à · ici · [question]"},{"fr":"Oui, c'est possible.","tgt":"Được ạ.","lit":"possible · [politesse]"},{"fr":"Est-ce que vous savez parler français ?","tgt":"Anh có biết nói tiếng Pháp không?","lit":"grand frère (vous) · [est-ce] · savoir · parler · langue · France · [question]"},{"fr":"Je parle un petit peu vietnamien.","tgt":"Tôi biết nói một chút tiếng Việt.","lit":"je · savoir · parler · un · peu · langue · Viêt"},{"fr":"Vous parlez vraiment bien !","tgt":"Anh nói giỏi quá!","lit":"grand frère (vous) · parler · doué · trop"},{"fr":"Est-ce que je peux régler par carte ?","tgt":"Tôi trả bằng thẻ được không?","lit":"je · payer · par · carte · possible · [question]"},{"fr":"Désolé, seulement en espèces.","tgt":"Xin lỗi, chỉ nhận tiền mặt thôi.","lit":"pardon · seulement · accepter · argent · liquide · [seulement]"},{"fr":"Je n'arrive pas à trouver le quai.","tgt":"Tôi không tìm được sân ga.","lit":"je · [négation] · trouver · possible · quai"},{"fr":"Vous savez où est le quai numéro deux ?","tgt":"Anh có biết sân ga số hai ở đâu không?","lit":"grand frère (vous) · [est-ce] · savoir · quai · numéro · deux · se trouver · où · [question]"},{"fr":"On peut s'asseoir ici ?","tgt":"Chúng tôi có thể ngồi đây không?","lit":"nous · pouvoir · s'asseoir · ici · [question]"}],"tip":{"title":"« Có thể », « được », « biết » : pouvoir et savoir","example":"Je peux acheter un billet ici ? — Tôi <b>có thể</b> mua vé ở đây không?","body":"Le français dit pouvoir et savoir ; le vietnamien a trois mots à placer chacun au bon endroit. « Có thể » se met avant le verbe : « tôi có thể mua vé ở đây không ? », je peux acheter un billet ici ? Mot à mot je, pouvoir, acheter, billet, ici, question. « Được » se met après le verbe ou en fin de phrase, et c'est le plus courant à l'oral : « tôi trả bằng thẻ được không ? », je peux payer par carte ? Tout seul, « được » veut dire d'accord, c'est possible. « Biết », savoir, s'emploie pour une compétence apprise : « tôi biết nói một chút tiếng Việt », je sais parler un peu vietnamien. Pour la négation, on met « không » devant le verbe : « tôi không tìm được sân ga », je n'arrive pas à trouver le quai. Astuce : si vous hésitez, terminez votre question par « được không ? », on vous comprendra toujours.","lit":"je · pouvoir · acheter · billet · à · ici · [question]","say":{"Có thể":"Có thể","được":"được","biết":"biết","tôi có thể mua vé ở đây không ?":"tôi có thể mua vé ở đây không ?","Được":"Được","tôi trả bằng thẻ được không ?":"tôi trả bằng thẻ được không ?","Biết":"Biết","tôi biết nói một chút tiếng Việt":"tôi biết nói một chút tiếng Việt","không":"không","tôi không tìm được sân ga":"tôi không tìm được sân ga","được không ?":"được không ?"}}},{"title":"Acheter un billet de train","phrases":[{"fr":"Un billet pour Nha Trang, s'il vous plaît.","tgt":"Cho tôi một vé đi Nha Trang.","lit":"donner · moi · un · billet · aller · Nha Trang"},{"fr":"Vous partez quel jour ?","tgt":"Anh đi ngày nào?","lit":"grand frère (vous) · partir · jour · quel"},{"fr":"Jeudi de la semaine prochaine.","tgt":"Thứ năm tuần sau.","lit":"jour n° · cinq · semaine · suivante"},{"fr":"Couchette ou siège ?","tgt":"Giường nằm hay ghế ngồi?","lit":"lit · couché · ou · siège · assis"},{"fr":"Une couchette, c'est plus commode.","tgt":"Giường nằm cho tiện.","lit":"lit · couché · pour · pratique"},{"fr":"Le train pour Nha Trang part à quelle heure ?","tgt":"Tàu đi Nha Trang chạy lúc mấy giờ?","lit":"train · aller · Nha Trang · rouler · à · combien · heure"},{"fr":"À huit heures du soir.","tgt":"Lúc tám giờ tối.","lit":"à · huit · heure · soir"},{"fr":"Le trajet prend combien de temps ?","tgt":"Đi mất bao lâu?","lit":"aller · prendre · combien · longtemps"},{"fr":"À peu près huit heures.","tgt":"Khoảng tám tiếng.","lit":"environ · huit · heure"},{"fr":"Voici votre billet, bon voyage !","tgt":"Vé của anh đây, chúc anh đi vui vẻ!","lit":"billet · de · grand frère (vous) · voici · souhaiter · grand frère (vous) · aller · joyeux"}]},{"title":"Le bus et le train vers la côte","phrases":[{"fr":"Comment vas-tu à la plage ?","tgt":"Em đi biển bằng gì?","lit":"petit frère (tu) · aller · mer · par · quoi"},{"fr":"J'y vais en train.","tgt":"Em đi tàu.","lit":"moi (petit frère) · aller · train"},{"fr":"Mon ami y va à scooter.","tgt":"Bạn em đi xe máy.","lit":"ami · moi · aller · moto"},{"fr":"Le bus, c'est moins cher.","tgt":"Đi xe buýt rẻ hơn.","lit":"aller · bus · bon marché · plus"},{"fr":"Je préfère aller à pied.","tgt":"Tôi thích đi bộ hơn.","lit":"je · aimer · aller · pied · plus"},{"fr":"On prend l'avion pour Hanoï ?","tgt":"Mình đi máy bay ra Hà Nội nhé?","lit":"nous · aller · avion · sortir (vers le nord) · Hanoï · [d'accord ?]"},{"fr":"Non, en train on peut admirer les paysages.","tgt":"Không, đi tàu được ngắm cảnh.","lit":"non · aller · train · pouvoir · admirer · paysage"},{"fr":"Le bus de nuit part à dix heures.","tgt":"Xe đêm chạy lúc mười giờ.","lit":"véhicule · nuit · rouler · à · dix · heure"},{"fr":"Je n'ai jamais pris le bus de nuit.","tgt":"Tôi chưa đi xe đêm bao giờ.","lit":"je · [pas encore] · aller · véhicule · nuit · jamais"},{"fr":"Allons-y en taxi, c'est plus rapide.","tgt":"Mình đi tắc xi đi, nhanh hơn.","lit":"nous · aller · taxi · [allez] · rapide · plus"}],"tip":{"title":"« Đi » + moyen de transport : « đi xe máy, đi tàu »","example":"Mon ami y va à scooter. — Bạn em <b>đi xe máy</b>.","body":"Pour dire comment vous voyagez, rien de plus simple : le verbe « đi », aller, suivi du moyen de transport. « Đi tàu », c'est prendre le train ; « đi xe máy », aller à scooter ; « đi xe buýt », prendre le bus ; « đi máy bay », prendre l'avion ; et « đi bộ », aller à pied. Prenons « bạn em đi xe máy » : mot à mot ami, moi, aller, moto, donc mon ami y va à scooter. Le français a besoin de prendre, en ou à ; le vietnamien se contente de « đi ». Pour poser la question, dites « đi bằng gì ? », mot à mot aller par quoi. Le mot « xe » désigne tout véhicule à roues : on le retrouve dans « xe máy », « xe buýt » ou « xe ôm », le scooter-taxi. Astuce : imaginez « đi » comme un petit moteur qui démarre devant chaque véhicule.","lit":"ami · moi · aller · moto","say":{"Đi":"Đi","đi":"đi","Đi tàu":"Đi tàu","đi xe máy":"đi xe máy","đi xe buýt":"đi xe buýt","đi máy bay":"đi máy bay","đi bộ":"đi bộ","bạn em đi xe máy":"bạn em đi xe máy","đi bằng gì ?":"đi bằng gì ?","xe":"xe","xe máy":"xe máy","xe buýt":"xe buýt","xe ôm":"xe ôm"}}},{"title":"Dans le train vers Nha Trang","phrases":[{"fr":"Je crois que c'est ma couchette.","tgt":"Hình như đây là giường của tôi.","lit":"il semble · ceci · être · lit · de · moi"},{"fr":"Vous m'aidez à poser ma valise en haut ?","tgt":"Anh giúp tôi để va li lên trên nhé?","lit":"grand frère (vous) · aider · moi · poser · valise · monter · dessus · [d'accord ?]"},{"fr":"Vous aussi, vous allez à Nha Trang ?","tgt":"Chị cũng đi Nha Trang à?","lit":"grande sœur (vous) · aussi · aller · Nha Trang · [question surprise]"},{"fr":"Oui, je rentre dans mon village.","tgt":"Ừ, chị về quê.","lit":"oui · moi (grande sœur) · rentrer · village natal"},{"fr":"Regarde, on voit la mer !","tgt":"Nhìn kìa, thấy biển rồi!","lit":"regarder · là-bas · voir · mer · [déjà]"},{"fr":"Les rizières sont magnifiques.","tgt":"Ruộng lúa đẹp quá.","lit":"champ · riz · beau · trop"},{"fr":"Il y a un wagon-restaurant ?","tgt":"Trên tàu có toa ăn không?","lit":"sur · train · avoir · wagon · manger · [question]"},{"fr":"Une vendeuse passe avec du café.","tgt":"Có chị bán cà phê đi qua.","lit":"avoir · grande sœur · vendre · café · aller · passer"},{"fr":"Je vais dormir un peu.","tgt":"Tôi ngủ một lát đây.","lit":"je · dormir · un · moment · [maintenant]"},{"fr":"Réveille-moi à l'arrivée, s'il te plaît.","tgt":"Đến nơi thì gọi tôi dậy nhé.","lit":"arriver · endroit · alors · appeler · moi · se lever · [d'accord ?]"}]},{"title":"À la plage de Nha Trang","phrases":[{"fr":"La plage est loin d'ici ?","tgt":"Bãi biển có xa đây không?","lit":"plage · [est-ce] · loin · ici · [question]"},{"fr":"Non, c'est vraiment à deux pas.","tgt":"Không, gần lắm.","lit":"non · près · très"},{"fr":"C'est à cinq cents mètres d'ici.","tgt":"Cách đây năm trăm mét.","lit":"être distant · ici · cinq · cent · mètre"},{"fr":"Notre hôtel est près de la mer.","tgt":"Khách sạn của chúng tôi gần biển.","lit":"hôtel · de · nous · près · mer"},{"fr":"L'île est à quelle distance ?","tgt":"Hòn đảo cách đây bao xa?","lit":"[classificateur] · île · être distant · ici · combien · loin"},{"fr":"Environ dix kilomètres en bateau.","tgt":"Khoảng mười cây số đi thuyền.","lit":"environ · dix · kilomètre · aller · bateau"},{"fr":"Il y a un restaurant de fruits de mer près d'ici ?","tgt":"Gần đây có quán hải sản nào không?","lit":"près · ici · avoir · établissement · fruits de mer · quel · [question]"},{"fr":"Le centre-ville est un peu loin.","tgt":"Trung tâm thành phố hơi xa.","lit":"centre · ville · un peu · loin"},{"fr":"Je suis arrivé il y a trois jours.","tgt":"Tôi đến cách đây ba ngày.","lit":"je · arriver · être distant · ici · trois · jour"},{"fr":"Ce n'est pas loin, on peut y aller à pied.","tgt":"Không xa đâu, đi bộ được.","lit":"[négation] · loin · [du tout] · aller · pied · possible"}],"tip":{"title":"« Xa » et « gần » : loin et près, et « cách đây »","example":"C'est à cinq cents mètres d'ici. — <b>Cách đây</b> năm trăm mét.","body":"« Xa » veut dire loin et « gần » veut dire près ; ce sont des adjectifs, donc pas besoin du verbe être. « Khách sạn gần biển », l'hôtel est près de la mer, mot à mot hôtel, près, mer. Pour poser la question, encadrez le mot avec « có » et « không » : « bãi biển có xa đây không ? », la plage est loin d'ici ? Pour une distance précise, on utilise « cách đây », mot à mot séparé d'ici : « cách đây năm trăm mét », c'est à cinq cents mètres d'ici. La question devient alors « cách đây bao xa ? », à quelle distance ? En bonus, « cách đây » sert aussi pour le temps, comme il y a en français : « cách đây ba ngày », il y a trois jours. Et « gần đây » veut simplement dire près d'ici. Astuce : « gần » se dit sur un ton qui descend, comme une distance qui se raccourcit.","lit":"être distant · ici · cinq · cent · mètre","say":{"Xa":"Xa","gần":"gần","cách đây":"cách đây","Khách sạn gần biển":"Khách sạn gần biển","có":"có","không":"không","bãi biển có xa đây không ?":"bãi biển có xa đây không ?","cách đây năm trăm mét":"cách đây năm trăm mét","cách đây bao xa ?":"cách đây bao xa ?","cách đây ba ngày":"cách đây ba ngày","gần đây":"gần đây"}}},{"title":"Un petit souci en voyage","phrases":[{"fr":"J'ai perdu mon téléphone.","tgt":"Tôi bị mất điện thoại.","lit":"je · [subir] · perdre · téléphone"},{"fr":"Je l'ai peut-être oublié dans le taxi.","tgt":"Có lẽ tôi để quên trên tắc xi.","lit":"peut-être · je · laisser · oublier · sur · taxi"},{"fr":"Vous pouvez appeler la compagnie de taxi pour moi ?","tgt":"Anh gọi cho hãng tắc xi giúp tôi được không?","lit":"grand frère (vous) · appeler · pour · compagnie · taxi · aider · moi · possible · [question]"},{"fr":"J'ai mal au ventre depuis ce matin.","tgt":"Từ sáng tôi bị đau bụng.","lit":"depuis · matin · je · [subir] · avoir mal · ventre"},{"fr":"Où se trouve la pharmacie la plus proche d'ici ?","tgt":"Hiệu thuốc gần nhất ở đâu?","lit":"boutique · médicament · près · le plus · se trouver · où"},{"fr":"Tu dois boire beaucoup d'eau.","tgt":"Em phải uống nhiều nước.","lit":"petit frère (tu) · devoir · boire · beaucoup · eau"},{"fr":"J'ai raté mon bus.","tgt":"Tôi bị lỡ xe buýt.","lit":"je · [subir] · manquer · bus"},{"fr":"Le suivant part dans une heure.","tgt":"Một tiếng nữa có chuyến sau.","lit":"un · heure · encore · avoir · trajet · suivant"},{"fr":"Ce n'est rien, ne t'inquiète pas.","tgt":"Không sao, đừng lo.","lit":"[négation] · quoi · ne pas · s'inquiéter"},{"fr":"Finalement, tout s'est bien passé.","tgt":"Cuối cùng mọi việc đều ổn.","lit":"finalement · toute · affaire · tous · bien"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, nous avons voyagé à Saïgon.","tgt":"Trong phần này, chúng ta đã đi du lịch Sài Gòn.","lit":"dans · partie · ce · nous · [accompli] · voyager · Saïgon"},{"fr":"Vous savez maintenant prendre un taxi en vietnamien.","tgt":"Bây giờ bạn đã biết gọi tắc xi bằng tiếng Việt.","lit":"maintenant · vous · [accompli] · savoir · appeler · taxi · par · langue · Viêt"},{"fr":"Vous pouvez demander un prix au marché.","tgt":"Bạn có thể hỏi giá ở chợ.","lit":"vous · pouvoir · demander · prix · à · marché"},{"fr":"Vous savez aussi demander votre chemin.","tgt":"Bạn cũng biết hỏi đường rồi.","lit":"vous · aussi · savoir · demander · chemin · [déjà]"},{"fr":"Le prochain module parlera de rencontres.","tgt":"Phần sau sẽ nói về những cuộc gặp gỡ.","lit":"partie · suivante · [futur] · parler · de · [pluriel] · [classificateur] · rencontre"},{"fr":"Demain, je vais réviser ces leçons.","tgt":"Ngày mai tôi sẽ ôn lại các bài này.","lit":"demain · je · [futur] · réviser · de nouveau · [pluriel] · leçon · ce"},{"fr":"Un jour, j'irai vraiment à Saïgon.","tgt":"Một ngày nào đó tôi sẽ đi Sài Gòn thật.","lit":"un · jour · quel · là · je · [futur] · aller · Saïgon · vraiment"},{"fr":"Je parlerai vietnamien avec les gens.","tgt":"Tôi sẽ nói tiếng Việt với mọi người.","lit":"je · [futur] · parler · langue · Viêt · avec · tout le monde"},{"fr":"Bravo, vous avez fait de beaux progrès !","tgt":"Bạn tiến bộ nhiều lắm, giỏi quá!","lit":"vous · progresser · beaucoup · très · doué · trop"},{"fr":"À bientôt pour le module suivant !","tgt":"Hẹn gặp lại ở phần sau nhé!","lit":"promettre · rencontrer · de nouveau · à · partie · suivante · [d'accord ?]"}],"tip":{"title":"« Sẽ » : le futur, ce que je vais faire","example":"Un jour, j'irai vraiment à Saïgon. — Một ngày nào đó tôi <b>sẽ</b> đi Sài Gòn thật.","body":"Pour parler de l'avenir, il suffit de placer « sẽ » juste avant le verbe. « Tôi sẽ đi Sài Gòn », j'irai à Saïgon, mot à mot je, futur, aller, Saïgon. Le verbe ne bouge pas : c'est « sẽ » qui fait tout le travail, un peu comme le petit verbe aller dans je vais partir. Avec un mot de temps, la phrase devient très claire : « ngày mai tôi sẽ ôn lại các bài này », demain je vais réviser ces leçons. Vous avez maintenant trois petits mots pour situer une action : « đã » pour ce qui est fait, « đang » pour ce qui est en cours, et « sẽ » pour ce qui viendra. À l'oral, quand le moment est évident, on omet souvent « sẽ » : « ngày mai tôi đi », demain je pars. Le ton de « sẽ » monte avec une petite cassure dans la voix. Astuce : retenez la suite « đã, đang, sẽ » comme hier, aujourd'hui, demain.","lit":"un · jour · quel · là · je · [futur] · aller · Saïgon · vraiment","say":{"Sẽ":"Sẽ","sẽ":"sẽ","Tôi sẽ đi Sài Gòn":"Tôi sẽ đi Sài Gòn","ngày mai tôi sẽ ôn lại các bài này":"ngày mai tôi sẽ ôn lại các bài này","đã":"đã","đang":"đang","ngày mai tôi đi":"ngày mai tôi đi","đã, đang, sẽ":"đã, đang, sẽ"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Chez une famille à Huế","phrases":[{"fr":"Bonsoir, je suis l'ami de Lan.","tgt":"Cháu chào bác, cháu là bạn của Lan.","lit":"neveu (je) · saluer · oncle (vous) · neveu (je) · être · ami · de · Lan"},{"fr":"Entre donc à la maison !","tgt":"Cháu vào nhà đi!","lit":"neveu (toi) · entrer · maison · [incitation]"},{"fr":"J'ai apporté quelques fruits.","tgt":"Cháu mang ít hoa quả đến.","lit":"neveu (je) · apporter · un peu · fruits · venir"},{"fr":"Oh, il ne fallait pas !","tgt":"Ôi, cháu khách sáo quá!","lit":"oh · neveu (toi) · cérémonieux · trop"},{"fr":"Assieds-toi ici, mon petit.","tgt":"Cháu ngồi đây đi.","lit":"neveu (toi) · s'asseoir · ici · [incitation]"},{"fr":"Votre maison est vraiment belle.","tgt":"Nhà bác rất đẹp.","lit":"maison · oncle (vous) · très · beau"},{"fr":"Tu veux boire un peu de thé ?","tgt":"Cháu có uống trà không?","lit":"neveu (toi) · [affirmatif] · boire · thé · [question]"},{"fr":"Oui, avec plaisir, merci.","tgt":"Dạ, cháu cảm ơn bác.","lit":"[oui poli] · neveu (je) · remercier · oncle (vous)"},{"fr":"C'est la première fois que tu viens à Huế ?","tgt":"Lần đầu cháu đến Huế phải không?","lit":"fois · premier · neveu (toi) · venir · Huế · [question : n'est-ce pas]"},{"fr":"Oui, c'est la toute première fois.","tgt":"Dạ, lần đầu ạ.","lit":"[oui poli] · fois · premier · [politesse]"}]},{"title":"Se présenter","phrases":[{"fr":"Moi, je m'appelle Paul.","tgt":"Tôi tên là Paul.","lit":"je · nom · être · Paul"},{"fr":"Et toi, c'est quoi ton prénom ?","tgt":"Bạn tên là gì?","lit":"ami (tu) · nom · être · quoi"},{"fr":"Moi, c'est Hoa.","tgt":"Mình tên là Hoa.","lit":"moi · nom · être · Hoa"},{"fr":"Je viens de France, je suis français.","tgt":"Tôi đến từ Pháp, tôi là người Pháp.","lit":"je · venir · depuis · France · je · être · personne · France"},{"fr":"Tu es de quel pays ?","tgt":"Bạn là người nước nào?","lit":"tu · être · personne · pays · lequel"},{"fr":"Moi, je suis de Huế.","tgt":"Mình là người Huế.","lit":"moi · être · personne · Huế"},{"fr":"Ma femme s'appelle Claire.","tgt":"Vợ tôi tên là Claire.","lit":"épouse · je · nom · être · Claire"},{"fr":"Elle aussi, elle est française.","tgt":"Cô ấy cũng là người Pháp.","lit":"elle · aussi · être · personne · France"},{"fr":"Très heureux de faire ta connaissance.","tgt":"Rất vui được làm quen với bạn.","lit":"très · content · [avoir l'occasion] · faire connaissance · avec · toi"},{"fr":"Moi aussi, je suis ravie.","tgt":"Mình cũng rất vui.","lit":"moi · aussi · très · content"}],"tip":{"title":"Se présenter : « tên là », et « tôi là người Pháp »","example":"Moi, je m'appelle Paul. — Tôi <b>tên là</b> Paul.","body":"Pour dire son prénom, le vietnamien utilise une petite formule toute simple : « tôi tên là », mot à mot je, nom, être. On dit donc « tôi tên là Paul », je m'appelle Paul. Pour poser la question, on remplace le prénom par « gì », qui veut dire quoi : « bạn tên là gì ? », comment tu t'appelles ? Pour l'origine, on emploie « người », la personne, suivi du nom du pays : « người Pháp », c'est une personne de France, donc un Français. « Tôi là người Pháp » veut dire je suis français, et cela marche aussi pour une ville : « mình là người Huế », je suis de « Huế ». Le verbe « là », être, ne change jamais, que l'on parle de soi, de toi ou d'elle. Astuce pour retenir : « người » plus un lieu, et vous avez dit d'où vous venez.","lit":"je · nom · être · Paul","say":{"tên là":"tên là","tôi là người Pháp":"tôi là người Pháp","tôi tên là":"tôi tên là","tôi tên là Paul":"tôi tên là Paul","gì":"gì","bạn tên là gì ?":"bạn tên là gì ?","người":"người","người Pháp":"người Pháp","Tôi là người Pháp":"Tôi là người Pháp","mình là người Huế":"mình là người Huế","là":"là"}}},{"title":"Parler de son métier","phrases":[{"fr":"Et toi, tu travailles dans quoi ?","tgt":"Bạn làm nghề gì?","lit":"tu · faire · métier · quoi"},{"fr":"Je suis prof de français.","tgt":"Tôi là giáo viên tiếng Pháp.","lit":"je · être · enseignant · langue · France"},{"fr":"Je travaille dans un hôtel de Huế.","tgt":"Mình làm việc ở một khách sạn ở Huế.","lit":"moi · travailler · à · un · hôtel · à · Huế"},{"fr":"Ton boulot, ça te plaît ?","tgt":"Bạn có thích công việc của mình không?","lit":"tu · [affirmatif] · aimer · travail · de · soi · [question]"},{"fr":"Oui, même si c'est un peu fatigant.","tgt":"Có, nhưng hơi mệt.","lit":"oui · mais · un peu · fatigué"},{"fr":"Je commence le travail à sept heures.","tgt":"Mình bắt đầu làm lúc bảy giờ.","lit":"moi · commencer · travailler · à · sept · heure"},{"fr":"Tu es étudiant, c'est ça ?","tgt":"Bạn là sinh viên phải không?","lit":"tu · être · étudiant · [question : n'est-ce pas]"},{"fr":"Non, moi je suis ingénieur.","tgt":"Không, tôi là kỹ sư.","lit":"non · je · être · ingénieur"},{"fr":"Ma copine est guide touristique.","tgt":"Bạn gái tôi là hướng dẫn viên du lịch.","lit":"petite amie · je · être · guide · tourisme"},{"fr":"Elle fait visiter la cité ancienne.","tgt":"Cô ấy dẫn khách đi thăm kinh thành.","lit":"elle · guider · client · aller · visiter · citadelle"}]},{"title":"Ce que j'aime","phrases":[{"fr":"J'aime beaucoup Huế.","tgt":"Tôi rất thích Huế.","lit":"je · très · aimer · Huế"},{"fr":"Tu aimes la cuisine de Huế ?","tgt":"Bạn có thích món ăn Huế không?","lit":"tu · [affirmatif] · aimer · plat · Huế · [question]"},{"fr":"Oui, j'adore ça.","tgt":"Có, mình thích lắm.","lit":"oui · moi · aimer · très"},{"fr":"Je n'aime pas trop le piment.","tgt":"Tôi không thích ớt lắm.","lit":"je · ne pas · aimer · piment · très"},{"fr":"J'aime me promener le soir.","tgt":"Tôi thích đi dạo buổi tối.","lit":"je · aimer · aller · flâner · moment · soir"},{"fr":"Qu'est-ce que tu aimes faire le week-end ?","tgt":"Cuối tuần bạn thích làm gì?","lit":"fin · semaine · tu · aimer · faire · quoi"},{"fr":"J'aime lire et écouter de la musique.","tgt":"Mình thích đọc sách và nghe nhạc.","lit":"moi · aimer · lire · livre · et · écouter · musique"},{"fr":"Ma femme adore les fleurs de lotus.","tgt":"Vợ tôi thích hoa sen.","lit":"épouse · je · aimer · fleur · lotus"},{"fr":"Tu préfères le café ou le thé ?","tgt":"Bạn thích cà phê hay trà?","lit":"tu · aimer · café · ou · thé"},{"fr":"Moi, je préfère le café glacé.","tgt":"Mình thích cà phê đá hơn.","lit":"moi · aimer · café · glace · plus"}],"tip":{"title":"« Thích » : aimer","example":"J'aime beaucoup Huế. — Tôi rất <b>thích</b> Huế.","body":"« Thích » veut dire aimer, au sens d'apprécier quelque chose. Il se place juste avant ce que l'on aime, comme en français : « tôi thích Huế », j'aime « Huế ». Il peut aussi être suivi d'une action : « tôi thích đi dạo », j'aime me promener, mot à mot je, aimer, aller, flâner. Pour insister, on ajoute « rất », très, devant le verbe : « tôi rất thích Huế », j'aime beaucoup « Huế ». Pour la question, on encadre le verbe avec « có » et « không » : « bạn có thích cà phê không ? », tu aimes le café ? On répond simplement « có », oui, ou « không », non. Et pour dire que l'on préfère, il suffit d'ajouter « hơn », plus, à la fin : « thích cà phê đá hơn », je préfère le café glacé. Astuce : « thích » se dit court et montant, comme un petit cri de joie.","lit":"je · très · aimer · Huế","say":{"Thích":"Thích","tôi thích Huế":"tôi thích Huế","tôi thích đi dạo":"tôi thích đi dạo","rất":"rất","tôi rất thích Huế":"tôi rất thích Huế","có":"có","không":"không","bạn có thích cà phê không ?":"bạn có thích cà phê không ?","hơn":"hơn","thích cà phê đá hơn":"thích cà phê đá hơn","thích":"thích"}}},{"title":"Le repas partagé","phrases":[{"fr":"À table, tout le monde !","tgt":"Mời cả nhà ăn cơm!","lit":"inviter · toute · maison · manger · riz"},{"fr":"Je vous en prie, bon appétit à vous deux.","tgt":"Cháu mời hai bác ăn cơm ạ.","lit":"neveu (je) · inviter · deux · oncle (vous) · manger · riz · [politesse]"},{"fr":"Sers-toi, ne sois pas timide.","tgt":"Cháu ăn đi, đừng ngại.","lit":"neveu (toi) · manger · [incitation] · ne pas · être gêné"},{"fr":"Ce plat est délicieux !","tgt":"Món này ngon quá!","lit":"plat · ce · délicieux · trop"},{"fr":"C'est quoi, ce plat-là ?","tgt":"Món này là món gì ạ?","lit":"plat · ce · être · plat · quoi · [politesse]"},{"fr":"Ce sont des crêpes croustillantes de Huế.","tgt":"Đây là bánh khoái.","lit":"ceci · être · crêpe (bánh khoái)"},{"fr":"Tu en reprends un peu ?","tgt":"Cháu ăn thêm không?","lit":"neveu (toi) · manger · en plus · [question]"},{"fr":"Oui, juste un tout petit peu.","tgt":"Dạ, một chút thôi ạ.","lit":"[oui poli] · un · peu · seulement · [politesse]"},{"fr":"Tu me passes la sauce de poisson ?","tgt":"Bạn đưa mình nước mắm nhé.","lit":"toi · passer · moi · sauce de poisson · [d'accord]"},{"fr":"J'ai assez mangé, merci beaucoup.","tgt":"Cháu no rồi, cảm ơn bác.","lit":"neveu (je) · rassasié · [déjà] · remercier · oncle (vous)"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Je te présente mon père et ma mère.","tgt":"Đây là bố mẹ mình.","lit":"ceci · être · père · mère · moi"},{"fr":"Tu as des frères et des sœurs, de ton côté ?","tgt":"Bạn có anh chị em không?","lit":"tu · avoir · aîné · aînée · cadet · [question]"},{"fr":"Moi, j'ai un grand frère et une petite sœur.","tgt":"Mình có một anh trai và một em gái.","lit":"moi · avoir · un · aîné · garçon · et · un · cadet · fille"},{"fr":"Ma grande sœur habite à Hội An.","tgt":"Chị gái mình sống ở Hội An.","lit":"aînée · fille · moi · vivre · à · Hội An"},{"fr":"Mon petit frère est encore au lycée.","tgt":"Em trai mình vẫn đang học cấp ba.","lit":"cadet · garçon · moi · encore · [en cours] · étudier · niveau · trois"},{"fr":"Et ton père, il fait quoi ?","tgt":"Bố bạn làm nghề gì?","lit":"père · toi · faire · métier · quoi"},{"fr":"Ma mère cuisine très bien.","tgt":"Mẹ mình nấu ăn rất ngon.","lit":"mère · moi · cuisiner · très · délicieux"},{"fr":"Je n'ai pas de frère.","tgt":"Tôi không có anh em trai.","lit":"je · ne pas · avoir · aîné · cadet · garçon"},{"fr":"C'est moi, l'aîné de la famille.","tgt":"Tôi là con cả trong nhà.","lit":"je · être · enfant · aîné · dans · maison"},{"fr":"Ta famille est vraiment accueillante.","tgt":"Gia đình bạn rất mến khách.","lit":"famille · toi · très · hospitalier"}],"tip":{"title":"La famille : « bố, mẹ, anh, chị, em »","example":"Moi, j'ai un grand frère et une petite sœur. — Mình có một <b>anh</b> trai và một <b>em</b> gái.","body":"En vietnamien, les mots de la famille servent aussi de pronoms, et c'est essentiel pour bien parler. « Bố » veut dire papa et « mẹ » maman ; ensemble, « bố mẹ », ce sont les parents. Pour les frères et sœurs, on regarde d'abord l'âge et non le sexe : « anh » est le grand frère, « chị » la grande sœur, et « em » le petit frère ou la petite sœur. Pour préciser, on ajoute « trai », garçon, ou « gái », fille : « em gái », mot à mot cadet, fille, c'est la petite sœur. Ces mêmes mots s'emploient avec tout le monde : on appelle « anh » un homme un peu plus âgé que soi, « chị » une femme un peu plus âgée, et « em » une personne plus jeune. Ainsi, une jeune serveuse vous appellera « anh » ou « chị », et vous, vous l'appellerez « em ». Astuce : avant de parler, demandez-vous simplement qui est le plus âgé, et le bon mot viendra tout seul.","lit":"moi · avoir · un · aîné · garçon · et · un · cadet · fille","say":{"Bố":"Bố","mẹ":"mẹ","bố mẹ":"bố mẹ","anh":"anh","chị":"chị","em":"em","trai":"trai","gái":"gái","em gái":"em gái"}}},{"title":"Le bún bò Huế","phrases":[{"fr":"On va manger un bún bò ?","tgt":"Mình đi ăn bún bò nhé?","lit":"nous · aller · manger · bún bò · [proposition]"},{"fr":"Le bún bò, c'est la spécialité de Huế.","tgt":"Bún bò là món đặc sản của Huế.","lit":"bún bò · être · plat · spécialité · de · Huế"},{"fr":"Je connais une bonne gargote près du marché Đông Ba.","tgt":"Mình biết một quán ngon gần chợ Đông Ba.","lit":"moi · connaître · un · échoppe · délicieux · près · marché · Đông Ba"},{"fr":"Deux bols de bún bò, s'il vous plaît.","tgt":"Cho em hai bát bún bò.","lit":"donner · moi (cadet) · deux · bol · bún bò"},{"fr":"Le mien, peu épicé, s'il vous plaît.","tgt":"Bát của em ít cay thôi nhé.","lit":"bol · de · moi (cadet) · peu · épicé · seulement · [d'accord]"},{"fr":"Le bouillon sent vraiment bon.","tgt":"Nước dùng thơm quá.","lit":"bouillon · parfumé · trop"},{"fr":"Il y a de la citronnelle dans le bouillon.","tgt":"Trong nước dùng có sả.","lit":"dans · bouillon · il y a · citronnelle"},{"fr":"Tu veux encore des herbes ?","tgt":"Bạn có muốn thêm rau không?","lit":"tu · [affirmatif] · vouloir · ajouter · herbes · [question]"},{"fr":"Ça fait combien, les deux bols ?","tgt":"Hai bát bao nhiêu tiền ạ?","lit":"deux · bol · combien · argent · [politesse]"},{"fr":"Ça fait soixante mille dongs.","tgt":"Sáu mươi nghìn đồng anh ạ.","lit":"six · dizaine · mille · dong · grand frère (vous) · [politesse]"}]},{"title":"Qu'est-ce que tu fais ?","phrases":[{"fr":"Tu fais quoi en ce moment ?","tgt":"Bạn đang làm gì đấy?","lit":"tu · [en cours] · faire · quoi · [particule]"},{"fr":"Je suis en train de cuisiner avec ma mère.","tgt":"Mình đang nấu cơm với mẹ.","lit":"moi · [en cours] · cuire · riz · avec · mère"},{"fr":"Papa est en train de lire le journal.","tgt":"Bố đang đọc báo.","lit":"père · [en cours] · lire · journal"},{"fr":"En ce moment, il pleut.","tgt":"Bây giờ trời đang mưa.","lit":"maintenant · ciel · [en cours] · pleuvoir"},{"fr":"Tu es en train de manger, c'est ça ?","tgt":"Bạn đang ăn cơm phải không?","lit":"tu · [en cours] · manger · riz · [question : n'est-ce pas]"},{"fr":"Non, je regarde la télé.","tgt":"Không, mình đang xem ti vi.","lit":"non · moi · [en cours] · regarder · télé"},{"fr":"Les enfants jouent dans la cour.","tgt":"Bọn trẻ đang chơi ngoài sân.","lit":"groupe · enfant · [en cours] · jouer · dehors · cour"},{"fr":"Ma grande sœur est en train de se préparer.","tgt":"Chị mình đang chuẩn bị.","lit":"aînée · moi · [en cours] · se préparer"},{"fr":"Ces temps-ci, j'apprends le vietnamien.","tgt":"Dạo này tôi đang học tiếng Việt.","lit":"ces temps-ci · je · [en cours] · apprendre · langue · Viêt"},{"fr":"Je suis en route, j'arrive.","tgt":"Mình đang trên đường đến.","lit":"moi · [en cours] · sur · route · venir"}],"tip":{"title":"« Đang » : être en train de","example":"Papa est en train de lire le journal. — Bố <b>đang</b> đọc báo.","body":"« Đang » indique qu'une action est en train de se dérouler. On le place juste devant le verbe, et le verbe, lui, ne change jamais : « bố đang đọc báo », papa est en train de lire le journal, mot à mot père, en cours, lire, journal. En français, on dit souvent simplement il lit, mais le vietnamien aime préciser avec « đang » que cela se passe maintenant. Pour demander ce que fait quelqu'un, on dit « bạn đang làm gì ? », qu'est-ce que tu fais en ce moment ? Cela marche aussi pour la météo : « trời đang mưa », il pleut. Et au téléphone, « mình đang trên đường đến » veut dire je suis en route. Vous connaissez peut-être déjà ses deux cousins, « đã » pour le passé et « sẽ » pour le futur, qui se placent au même endroit. Astuce : retenez le trio « đã », « đang », « sẽ », passé, présent, futur, toujours juste avant le verbe.","lit":"père · [en cours] · lire · journal","say":{"Đang":"Đang","bố đang đọc báo":"bố đang đọc báo","đang":"đang","bạn đang làm gì ?":"bạn đang làm gì ?","trời đang mưa":"trời đang mưa","mình đang trên đường đến":"mình đang trên đường đến","đã":"đã","sẽ":"sẽ"}}},{"title":"Sur la rivière des Parfums","phrases":[{"fr":"On fait un tour en bateau sur la rivière des Parfums ce soir ?","tgt":"Tối nay mình đi thuyền trên sông Hương nhé?","lit":"soir · ce · nous · aller · bateau · sur · rivière · Hương · [proposition]"},{"fr":"Bonne idée, on y va !","tgt":"Hay đấy, đi thôi!","lit":"intéressant · [particule] · aller · [allons]"},{"fr":"Le bateau part à quelle heure ?","tgt":"Mấy giờ thuyền chạy?","lit":"combien · heure · bateau · partir"},{"fr":"Ce soir, la rivière est très calme.","tgt":"Tối nay sông rất êm.","lit":"soir · ce · rivière · très · calme"},{"fr":"Regarde, le pont Trường Tiền !","tgt":"Nhìn kìa, cầu Trường Tiền!","lit":"regarder · là-bas · pont · Trường Tiền"},{"fr":"Le soir, le pont s'illumine, c'est superbe.","tgt":"Buổi tối cầu lên đèn rất đẹp.","lit":"moment · soir · pont · allumer · lampe · très · beau"},{"fr":"Sur le bateau, quelqu'un chante des chansons de Huế.","tgt":"Trên thuyền có người hát ca Huế.","lit":"sur · bateau · il y a · personne · chanter · chant · Huế"},{"fr":"Il y a un petit vent frais, c'est agréable.","tgt":"Gió mát, dễ chịu quá.","lit":"vent · frais · agréable · trop"},{"fr":"Tu peux nous prendre en photo ?","tgt":"Bạn chụp ảnh cho bọn mình nhé.","lit":"toi · prendre · photo · pour · groupe · nous · [d'accord]"},{"fr":"Cette soirée est vraiment chouette !","tgt":"Tối nay vui quá!","lit":"soir · ce · joyeux · trop"}]},{"title":"Comparer","phrases":[{"fr":"Huế est plus calme que Hanoï.","tgt":"Huế yên tĩnh hơn Hà Nội.","lit":"Huế · calme · plus · Hà Nội"},{"fr":"Le bún bò est plus épicé que le phở.","tgt":"Bún bò cay hơn phở.","lit":"bún bò · épicé · plus · phở"},{"fr":"Mon frère aîné est plus grand que moi.","tgt":"Anh trai mình cao hơn mình.","lit":"aîné · garçon · moi · grand · plus · moi"},{"fr":"Ici, il fait plus chaud qu'à Đà Lạt.","tgt":"Ở đây nóng hơn Đà Lạt.","lit":"à · ici · chaud · plus · Đà Lạt"},{"fr":"Le train coûte moins cher que l'avion.","tgt":"Đi tàu rẻ hơn đi máy bay.","lit":"aller · train · bon marché · plus · aller · avion"},{"fr":"Lequel des deux est le meilleur ?","tgt":"Cái nào ngon hơn?","lit":"[classificateur] · lequel · délicieux · plus"},{"fr":"Celui-ci est meilleur.","tgt":"Cái này ngon hơn.","lit":"[classificateur] · ce · délicieux · plus"},{"fr":"Tu parles vietnamien mieux que moi.","tgt":"Bạn nói tiếng Việt giỏi hơn mình.","lit":"tu · parler · langue · Viêt · doué · plus · moi"},{"fr":"Parle un tout petit peu plus lentement, s'il te plaît.","tgt":"Bạn nói chậm hơn một chút nhé.","lit":"tu · parler · lent · plus · un · peu · [d'accord]"},{"fr":"Je trouve la cuisine de Huế plus raffinée.","tgt":"Mình thấy món Huế tinh tế hơn.","lit":"moi · trouver · plat · Huế · raffiné · plus"}],"tip":{"title":"Comparer avec « hơn »","example":"Huế est plus calme que Hanoï. — Huế yên tĩnh <b>hơn</b> Hà Nội.","body":"Pour comparer, le vietnamien est d'une grande simplicité : on prend l'adjectif, on ajoute « hơn », qui veut dire plus, puis ce à quoi on compare. La phrase « Huế yên tĩnh hơn Hà Nội » se décompose en « Huế », calme, plus, Hanoï : « Huế » est plus calme que Hanoï. Il n'y a ni mot pour que, ni verbe être. De la même façon, « bún bò cay hơn phở » veut dire le « bún bò » est plus épicé que le « phở ». Pour dire moins, on prend plutôt l'adjectif contraire : moins cher se dit « rẻ hơn », mot à mot plus bon marché. Et quand on ne cite rien, « hơn » tout seul suffit : « cái này ngon hơn », celui-ci est meilleur. Astuce : en français, le mot plus vient avant l'adjectif ; en vietnamien, il vient après, comme un petit bonus ajouté au bout.","lit":"Huế · calme · plus · Hà Nội","say":{"hơn":"hơn","Huế yên tĩnh hơn Hà Nội":"Huế yên tĩnh hơn Hà Nội","bún bò cay hơn phở":"bún bò cay hơn phở","rẻ hơn":"rẻ hơn","cái này ngon hơn":"cái này ngon hơn"}}},{"title":"Visiter la cité ancienne","phrases":[{"fr":"Demain, on visite la cité ancienne.","tgt":"Ngày mai mình đi thăm Đại Nội.","lit":"jour · demain · nous · aller · visiter · Đại Nội"},{"fr":"Le billet d'entrée coûte combien ?","tgt":"Vé vào cửa bao nhiêu tiền?","lit":"billet · entrer · porte · combien · argent"},{"fr":"Deux cent mille dongs par personne.","tgt":"Hai trăm nghìn đồng một người.","lit":"deux · cent · mille · dong · un · personne"},{"fr":"C'est immense, ici !","tgt":"Ở đây rộng quá!","lit":"à · ici · vaste · trop"},{"fr":"Les remparts de la cité sont très anciens.","tgt":"Tường thành rất cổ.","lit":"mur · citadelle · très · ancien"},{"fr":"On a le droit de prendre des photos ici ?","tgt":"Ở đây có được chụp ảnh không?","lit":"à · ici · [affirmatif] · [permis] · prendre · photo · [question]"},{"fr":"Oui, mais on n'a pas le droit de toucher.","tgt":"Được, nhưng không được sờ vào.","lit":"permis · mais · ne pas · [permis] · toucher · dedans"},{"fr":"Aujourd'hui, il y a énormément de touristes.","tgt":"Hôm nay có rất nhiều khách du lịch.","lit":"aujourd'hui · il y a · très · beaucoup · client · tourisme"},{"fr":"Je suis un peu fatigué, on fait une pause ?","tgt":"Mình hơi mệt, nghỉ một lát nhé?","lit":"moi · un peu · fatigué · se reposer · un · instant · [proposition]"},{"fr":"Allons nous asseoir à l'ombre, là-bas.","tgt":"Mình ra chỗ bóng mát kia ngồi đi.","lit":"nous · sortir · endroit · ombre · frais · là-bas · s'asseoir · [incitation]"}]},{"title":"Donner ses raisons","phrases":[{"fr":"Comme il pleut, on reste à la maison.","tgt":"Vì trời mưa nên mình ở nhà.","lit":"parce que · ciel · pleuvoir · donc · nous · rester · maison"},{"fr":"J'ai beaucoup marché, alors je suis fatigué.","tgt":"Vì đi bộ nhiều nên tôi mệt.","lit":"parce que · marcher · beaucoup · donc · je · fatigué"},{"fr":"Pourquoi tu apprends le vietnamien ?","tgt":"Tại sao bạn học tiếng Việt?","lit":"pourquoi · tu · apprendre · langue · Viêt"},{"fr":"Parce que j'aime le Viêt Nam.","tgt":"Vì mình thích Việt Nam.","lit":"parce que · moi · aimer · Viêt Nam"},{"fr":"Comme j'ai des amis ici, je viens souvent.","tgt":"Vì có bạn ở đây nên mình hay đến.","lit":"parce que · avoir · ami · à · ici · donc · moi · souvent · venir"},{"fr":"C'est très épicé, donc je bois beaucoup d'eau.","tgt":"Vì cay quá nên mình uống nhiều nước.","lit":"parce que · épicé · trop · donc · moi · boire · beaucoup · eau"},{"fr":"Pourquoi tu arrives si tard ?","tgt":"Sao bạn đến muộn thế?","lit":"pourquoi · tu · arriver · tard · [ainsi]"},{"fr":"Il y avait des bouchons, donc je suis en retard.","tgt":"Vì tắc đường nên mình đến muộn.","lit":"parce que · bouché · route · donc · moi · arriver · tard"},{"fr":"Comme il fait beau, allons au bord de la rivière.","tgt":"Vì trời đẹp nên mình ra bờ sông đi.","lit":"parce que · ciel · beau · donc · nous · sortir · rive · rivière · [incitation]"},{"fr":"Je ne mange pas de viande, parce que je n'aime pas ça.","tgt":"Mình không ăn thịt vì không thích.","lit":"moi · ne pas · manger · viande · parce que · ne pas · aimer"}],"tip":{"title":"« Vì… nên… » : parce que… donc…","example":"Comme il pleut, on reste à la maison. — <b>Vì</b> trời mưa <b>nên</b> mình ở nhà.","body":"Pour expliquer une raison, le vietnamien utilise un duo : « vì », parce que, au début, et « nên », donc, au milieu. « Vì trời mưa nên mình ở nhà » se dit mot à mot parce que, ciel, pleuvoir, donc, nous, rester, maison : comme il pleut, on reste à la maison. En français, on choisirait l'un ou l'autre, mais en vietnamien on aime mettre les deux, ce qui donne un rythme très régulier à la phrase. On peut aussi placer « vì » tout seul après la conséquence : « mình không ăn thịt vì không thích », je ne mange pas de viande parce que je n'aime pas ça. Pour demander pourquoi, on dit « tại sao », ou plus court à l'oral, « sao ». La réponse commence alors tout naturellement par « vì ». Astuce : imaginez une balançoire, « vì » d'un côté pour la cause, « nên » de l'autre pour la conséquence.","lit":"parce que · ciel · pleuvoir · donc · nous · rester · maison","say":{"Vì… nên…":"Vì… nên…","vì":"vì","nên":"nên","Vì trời mưa nên mình ở nhà":"Vì trời mưa nên mình ở nhà","mình không ăn thịt vì không thích":"mình không ăn thịt vì không thích","tại sao":"tại sao","sao":"sao"}}},{"title":"Parler du temps qu'il fait","phrases":[{"fr":"À Huế, il pleut énormément.","tgt":"Ở Huế mưa nhiều lắm.","lit":"à · Huế · pleuvoir · beaucoup · très"},{"fr":"Pense à prendre ton parapluie.","tgt":"Nhớ mang ô nhé.","lit":"se souvenir · apporter · parapluie · [d'accord]"},{"fr":"Il fait comment aujourd'hui ?","tgt":"Hôm nay trời thế nào?","lit":"aujourd'hui · ciel · comment"},{"fr":"Il fait chaud et humide.","tgt":"Trời nóng và ẩm.","lit":"ciel · chaud · et · humide"},{"fr":"En hiver, il fait assez froid ici.","tgt":"Mùa đông ở đây khá lạnh.","lit":"saison · hiver · à · ici · assez · froid"},{"fr":"Le ciel est bien gris.","tgt":"Trời âm u quá.","lit":"ciel · sombre · trop"},{"fr":"Cet après-midi, il va pleuvoir.","tgt":"Chiều nay trời sẽ mưa.","lit":"après-midi · ce · ciel · [futur] · pleuvoir"},{"fr":"Demain, il y aura du soleil.","tgt":"Ngày mai trời sẽ nắng.","lit":"jour · demain · ciel · [futur] · ensoleillé"},{"fr":"C'est quand, la meilleure saison pour venir à Huế ?","tgt":"Mùa nào đến Huế đẹp nhất?","lit":"saison · laquelle · venir · Huế · beau · le plus"},{"fr":"Au printemps, il fait doux.","tgt":"Mùa xuân trời mát mẻ.","lit":"saison · printemps · ciel · doux"}]},{"title":"Déjà fait ?","phrases":[{"fr":"Tu as mangé ?","tgt":"Bạn ăn cơm chưa?","lit":"tu · manger · riz · [question : déjà ?]"},{"fr":"Non, je n'ai pas encore mangé.","tgt":"Chưa, mình chưa ăn.","lit":"pas encore · moi · pas encore · manger"},{"fr":"Tu es déjà allé à Hội An ?","tgt":"Bạn đã đi Hội An bao giờ chưa?","lit":"tu · [accompli] · aller · Hội An · jamais · [question : déjà ?]"},{"fr":"Non, je n'y suis encore jamais allé.","tgt":"Chưa, mình chưa đi bao giờ.","lit":"pas encore · moi · pas encore · aller · jamais"},{"fr":"Tu es marié ou pas encore ?","tgt":"Bạn lập gia đình chưa?","lit":"tu · fonder · famille · [question : déjà ?]"},{"fr":"Pas encore, je suis encore jeune !","tgt":"Chưa, mình còn trẻ lắm!","lit":"pas encore · moi · encore · jeune · très"},{"fr":"Le riz est cuit ?","tgt":"Cơm chín chưa?","lit":"riz · cuit · [question : déjà ?]"},{"fr":"Lan est arrivée ?","tgt":"Lan đến chưa?","lit":"Lan · arriver · [question : déjà ?]"},{"fr":"Pas encore, elle est en route.","tgt":"Chưa, Lan đang trên đường đến.","lit":"pas encore · Lan · [en cours] · sur · route · venir"},{"fr":"Je ne comprends pas encore très bien.","tgt":"Mình chưa hiểu lắm.","lit":"moi · pas encore · comprendre · très"}],"tip":{"title":"« Chưa » : pas encore, et la question « … chưa ? »","example":"Tu as mangé ? — Bạn ăn cơm <b>chưa</b>?","body":"« Chưa » veut dire pas encore, et c'est un mot plein d'optimisme : il laisse entendre que la chose va arriver. Placé devant le verbe, il remplace la négation simple : « mình chưa ăn », je n'ai pas encore mangé. Placé à la fin, il transforme la phrase en question sur ce qui est déjà fait : « bạn ăn cơm chưa ? », mot à mot tu, manger, riz, pas encore, c'est-à-dire tu as mangé ? Cette question est d'ailleurs une façon très courante de saluer un proche, un peu comme un comment ça va. Pour répondre oui, on reprend le verbe avec « rồi », déjà : « ăn rồi », j'ai mangé. Pour répondre non, on dit simplement « chưa ». Même la question « bạn lập gia đình chưa ? », tu es marié ?, suppose gentiment que cela viendra un jour. Astuce : à une question en « chưa », la réponse est soit « rồi », soit « chưa ».","lit":"tu · manger · riz · [question : déjà ?]","say":{"Chưa":"Chưa","… chưa ?":"… chưa ?","mình chưa ăn":"mình chưa ăn","bạn ăn cơm chưa ?":"bạn ăn cơm chưa ?","rồi":"rồi","ăn rồi":"ăn rồi","chưa":"chưa","bạn lập gia đình chưa ?":"bạn lập gia đình chưa ?"}}},{"title":"Le sport et les loisirs","phrases":[{"fr":"Est-ce que tu fais du sport, toi ?","tgt":"Bạn có chơi thể thao không?","lit":"tu · [affirmatif] · jouer · sport · [question]"},{"fr":"Tous les matins, je cours le long de la rivière.","tgt":"Sáng nào mình cũng chạy bộ ven sông.","lit":"matin · chaque · moi · aussi · courir · le long · rivière"},{"fr":"Mon père joue au badminton.","tgt":"Bố mình chơi cầu lông.","lit":"père · moi · jouer · badminton"},{"fr":"Tu viens avec nous dimanche ?","tgt":"Chủ nhật bạn đi cùng bọn mình không?","lit":"dimanche · tu · aller · ensemble · groupe · nous · [question]"},{"fr":"Je fais souvent du vélo autour de la cité ancienne.","tgt":"Mình hay đạp xe quanh kinh thành.","lit":"moi · souvent · pédaler · vélo · autour · citadelle"},{"fr":"Je ne suis pas très doué pour le sport.","tgt":"Mình không giỏi thể thao.","lit":"moi · ne pas · doué · sport"},{"fr":"Tu regardes le foot ?","tgt":"Bạn có xem bóng đá không?","lit":"tu · [affirmatif] · regarder · football · [question]"},{"fr":"Oui, chaque week-end.","tgt":"Có, cuối tuần nào cũng xem.","lit":"oui · fin · semaine · chaque · aussi · regarder"},{"fr":"Tu nages vraiment bien !","tgt":"Bạn bơi giỏi quá!","lit":"tu · nager · doué · trop"},{"fr":"On va à la plage de Thuận An ?","tgt":"Mình đi biển Thuận An không?","lit":"nous · aller · mer · Thuận An · [question]"}]},{"title":"Offrir un cadeau","phrases":[{"fr":"Voici un petit cadeau pour toi.","tgt":"Đây là quà cho bạn.","lit":"ceci · être · cadeau · pour · toi"},{"fr":"Je te donne ce livre.","tgt":"Mình cho bạn quyển sách này.","lit":"moi · donner · toi · [classificateur] · livre · ce"},{"fr":"J'ai acheté des fruits pour ta mère.","tgt":"Mình mua hoa quả cho mẹ bạn.","lit":"moi · acheter · fruits · pour · mère · toi"},{"fr":"Tu peux me donner un peu de sel ?","tgt":"Cho mình xin ít muối.","lit":"donner · moi · demander · un peu · sel"},{"fr":"Attends, je t'écris mon numéro de téléphone.","tgt":"Để mình viết số điện thoại cho bạn.","lit":"laisser · moi · écrire · numéro · téléphone · pour · toi"},{"fr":"C'est ma mère qui m'a donné ce chapeau conique.","tgt":"Mẹ mình cho mình cái nón lá này.","lit":"mère · moi · donner · moi · [classificateur] · chapeau · feuille · ce"},{"fr":"Tu peux m'indiquer le chemin ?","tgt":"Bạn chỉ đường cho mình được không?","lit":"tu · indiquer · route · pour · moi · [possible] · [question]"},{"fr":"Ce soir, je cuisine pour mes amis.","tgt":"Tối nay mình nấu ăn cho các bạn.","lit":"soir · ce · moi · cuisiner · pour · [pluriel] · ami"},{"fr":"Merci de m'avoir offert un cadeau !","tgt":"Cảm ơn bạn đã tặng quà cho mình!","lit":"remercier · toi · [accompli] · offrir · cadeau · pour · moi"},{"fr":"Laisse, c'est moi qui paie pour toi.","tgt":"Để mình trả cho bạn.","lit":"laisser · moi · payer · pour · toi"}],"tip":{"title":"« Cho » : donner, et pour quelqu'un","example":"Je te donne ce livre. — Mình <b>cho</b> bạn quyển sách này.","body":"Le petit mot « cho » a deux emplois très pratiques. D'abord, c'est un verbe qui veut dire donner : « mình cho bạn quyển sách này », mot à mot moi, donner, toi, classificateur, livre, ce, c'est-à-dire je te donne ce livre. Ensuite, placé après une action, il veut dire pour quelqu'un : « mình mua hoa quả cho mẹ bạn », j'ai acheté des fruits pour ta mère. Vous l'entendrez aussi au restaurant, en début de phrase, pour commander poliment : « cho em hai bát bún bò », deux bols de « bún bò », s'il vous plaît. Avec « xin », demander, il devient très courtois : « cho mình xin ít muối », tu peux me donner un peu de sel ? L'ordre est toujours le même : celui qui donne, puis « cho », puis celui qui reçoit, puis la chose. Astuce : chaque fois que vous pensez donne-moi ou pour toi, pensez « cho ».","lit":"moi · donner · toi · [classificateur] · livre · ce","say":{"Cho":"Cho","cho":"cho","mình cho bạn quyển sách này":"mình cho bạn quyển sách này","mình mua hoa quả cho mẹ bạn":"mình mua hoa quả cho mẹ bạn","cho em hai bát bún bò":"cho em hai bát bún bò","xin":"xin","cho mình xin ít muối":"cho mình xin ít muối"}}},{"title":"Faire un compliment","phrases":[{"fr":"Tu parles drôlement bien français !","tgt":"Bạn nói tiếng Pháp giỏi quá!","lit":"tu · parler · langue · France · doué · trop"},{"fr":"Merci, tu exagères !","tgt":"Cảm ơn, bạn quá khen.","lit":"remercier · tu · trop · complimenter"},{"fr":"Ton áo dài est magnifique.","tgt":"Áo dài của bạn đẹp quá.","lit":"tunique · longue · de · toi · beau · trop"},{"fr":"Ta mère fait vraiment bien la cuisine.","tgt":"Mẹ bạn nấu ăn ngon lắm.","lit":"mère · toi · cuisiner · délicieux · très"},{"fr":"Ta maison est si chaleureuse.","tgt":"Nhà bạn ấm cúng quá.","lit":"maison · toi · chaleureux · trop"},{"fr":"Tu chantes vraiment bien.","tgt":"Bạn hát hay thật đấy.","lit":"tu · chanter · bien · vraiment · [particule]"},{"fr":"Les photos que tu prends sont superbes.","tgt":"Ảnh bạn chụp đẹp lắm.","lit":"photo · toi · prendre · beau · très"},{"fr":"Tu as l'air vraiment en forme.","tgt":"Trông bạn khỏe quá.","lit":"sembler · toi · en forme · trop"},{"fr":"Ton vietnamien fait des progrès rapides.","tgt":"Tiếng Việt của bạn tiến bộ nhanh quá.","lit":"langue · Viêt · de · toi · progresser · rapide · trop"},{"fr":"Ça me fait plaisir que tu dises ça.","tgt":"Bạn nói vậy mình vui lắm.","lit":"tu · dire · ainsi · moi · content · très"}]},{"title":"Trop et très","phrases":[{"fr":"Qu'il fait chaud aujourd'hui !","tgt":"Hôm nay nóng quá!","lit":"aujourd'hui · chaud · trop"},{"fr":"Ce bún bò est très bon.","tgt":"Bát bún bò này ngon lắm.","lit":"bol · bún bò · ce · délicieux · très"},{"fr":"Celui-ci est bien trop cher !","tgt":"Cái này đắt quá!","lit":"[classificateur] · ce · cher · trop"},{"fr":"La rivière des Parfums est très belle.","tgt":"Sông Hương đẹp lắm.","lit":"rivière · Hương · beau · très"},{"fr":"Je suis vraiment content d'être ici.","tgt":"Mình vui lắm khi được ở đây.","lit":"moi · content · très · quand · [avoir l'occasion] · être · ici"},{"fr":"Ce n'est pas très loin.","tgt":"Không xa lắm đâu.","lit":"ne pas · loin · très · [insistance]"},{"fr":"Oh là là, ça pique trop !","tgt":"Ôi, cay quá!","lit":"oh · épicé · trop"},{"fr":"Merci mille fois !","tgt":"Cảm ơn bạn nhiều lắm!","lit":"remercier · toi · beaucoup · très"},{"fr":"Le vietnamien, ce n'est pas si difficile.","tgt":"Tiếng Việt không khó lắm.","lit":"langue · Viêt · ne pas · difficile · très"},{"fr":"Tu es vraiment trop gentille !","tgt":"Bạn tốt quá!","lit":"tu · gentil · trop"}],"tip":{"title":"« Quá » et « lắm » : trop et très","example":"Ce bún bò est très bon. — Bát bún bò này ngon <b>lắm</b>.","body":"« Quá » et « lắm » se placent tous les deux après l'adjectif pour renforcer son sens, mais ils n'ont pas tout à fait la même couleur. « Quá » sert surtout à s'exclamer : « nóng quá ! », qu'il fait chaud !, ou « ngon quá ! », c'est trop bon ! « Lắm » est plus posé et veut simplement dire très : « bát bún bò này ngon lắm », mot à mot bol, « bún bò », ce, délicieux, très, ce « bún bò » est très bon. À la forme négative, on utilise « lắm » pour adoucir : « không xa lắm », ce n'est pas très loin. Placé avant l'adjectif, « quá » peut aussi vouloir dire trop, au sens d'excessif. N'oubliez pas non plus « rất », très, qui, lui, se place avant l'adjectif. Astuce : « quá » pour un cri du cœur, « lắm » pour une phrase calme.","lit":"bol · bún bò · ce · délicieux · très","say":{"Quá":"Quá","lắm":"lắm","nóng quá !":"nóng quá !","ngon quá !":"ngon quá !","Lắm":"Lắm","bát bún bò này ngon lắm":"bát bún bò này ngon lắm","không xa lắm":"không xa lắm","quá":"quá","rất":"rất"}}},{"title":"Se dire au revoir après une soirée","phrases":[{"fr":"Il est tard, il faut que je rentre.","tgt":"Muộn rồi, mình phải về đây.","lit":"tard · [déjà] · moi · devoir · rentrer · [particule]"},{"fr":"Merci à toute la famille pour ce soir.","tgt":"Cảm ơn cả nhà về buổi tối hôm nay.","lit":"remercier · toute · maison · concernant · moment · soir · aujourd'hui"},{"fr":"Quand tu as le temps, reviens nous voir.","tgt":"Lúc nào rảnh lại đến chơi nhé.","lit":"moment · quel · libre · de nouveau · venir · s'amuser · [d'accord]"},{"fr":"Je reviendrai bientôt.","tgt":"Mình sẽ sớm quay lại.","lit":"moi · [futur] · tôt · revenir"},{"fr":"Sois prudent sur la route du retour !","tgt":"Đi về cẩn thận nhé!","lit":"aller · rentrer · prudent · [d'accord]"},{"fr":"Comment tu rentres chez toi ?","tgt":"Bạn về bằng gì?","lit":"tu · rentrer · par · quoi"},{"fr":"Je rentre en scooter.","tgt":"Mình về bằng xe máy.","lit":"moi · rentrer · par · scooter"},{"fr":"Envoie-moi un petit message en arrivant.","tgt":"Về đến nhà thì nhắn tin cho mình nhé.","lit":"rentrer · arriver · maison · alors · envoyer message · pour · moi · [d'accord]"},{"fr":"Au revoir, on se voit demain !","tgt":"Tạm biệt, mai gặp lại nhé!","lit":"au revoir · demain · se voir · à nouveau · [d'accord]"},{"fr":"Bonne nuit à toute la famille !","tgt":"Chúc cả nhà ngủ ngon nhé!","lit":"souhaiter · toute · maison · dormir · bien · [d'accord]"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Tu sais déjà parler vietnamien ?","tgt":"Bạn nói được tiếng Việt rồi à?","lit":"tu · parler · [pouvoir] · langue · Viêt · [déjà] · [question : surprise]"},{"fr":"Oui, juste un petit peu !","tgt":"Ừ, một chút thôi!","lit":"oui · un · peu · seulement"},{"fr":"Le vietnamien, c'est une belle langue, hein ?","tgt":"Tiếng Việt hay nhỉ?","lit":"langue · Viêt · agréable · [n'est-ce pas]"},{"fr":"La prononciation, c'est difficile, hein ?","tgt":"Phát âm khó nhỉ?","lit":"prononcer · difficile · [n'est-ce pas]"},{"fr":"Ne t'en fais pas, tu en es capable !","tgt":"Không sao, bạn làm được mà!","lit":"pas de problème · tu · faire · [pouvoir] · [mais si]"},{"fr":"Je sais me présenter en vietnamien.","tgt":"Mình biết tự giới thiệu bằng tiếng Việt rồi.","lit":"moi · savoir · soi-même · présenter · en · langue · Viêt · [déjà]"},{"fr":"Je peux parler de ma famille et de mes goûts.","tgt":"Mình có thể nói về gia đình và sở thích của mình.","lit":"moi · pouvoir · parler · sur · famille · et · goût · de · moi"},{"fr":"Ah bon ? Bravo !","tgt":"Thật à? Giỏi quá!","lit":"vrai · [question : surprise] · doué · trop"},{"fr":"Mais je m'entraîne à parler tous les jours !","tgt":"Ngày nào mình cũng luyện nói mà!","lit":"jour · chaque · moi · aussi · s'entraîner · parler · [mais voyons]"},{"fr":"On continue la prochaine fois !","tgt":"Lần sau mình học tiếp nhé!","lit":"fois · suivant · nous · apprendre · continuer · [d'accord]"}],"tip":{"title":"Les petites particules de fin : « à, nhỉ, mà »","example":"Le vietnamien, c'est une belle langue, hein ? — Tiếng Việt hay <b>nhỉ</b>?","body":"À la fin des phrases, le vietnamien parlé ajoute souvent de petites particules qui donnent le ton, un peu comme hein, ah bon ou mais si en français. « À » marque la surprise dans une question : « thật à ? », ah bon, c'est vrai ? « Nhỉ » demande l'accord de l'autre, comme hein ou n'est-ce pas : « tiếng Việt hay nhỉ ? », mot à mot langue, vietnamienne, agréable, hein, c'est-à-dire le vietnamien, c'est joli, hein ? « Mà » insiste sur une évidence ou rassure : « bạn làm được mà ! », mais si, tu en es capable ! Ces mots ne changent pas le sens de la phrase, mais ils la rendent vivante et chaleureuse. Sans eux, on vous comprend parfaitement, mais vous sonnez un peu comme un manuel. Astuce : écoutez vos amis vietnamiens terminer leurs phrases, et amusez-vous à imiter cette petite note finale.","lit":"langue · Viêt · agréable · [n'est-ce pas]","say":{"À":"À","thật à ?":"thật à ?","Nhỉ":"Nhỉ","tiếng Việt hay nhỉ ?":"tiếng Việt hay nhỉ ?","Mà":"Mà","bạn làm được mà !":"bạn làm được mà !"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une nouvelle vie à Đà Lạt","phrases":[{"fr":"Je viens d'emménager à Đà Lạt le mois dernier.","tgt":"Tôi mới chuyển đến Đà Lạt tháng trước."},{"fr":"Mon appartement donne sur une colline couverte de pins.","tgt":"Căn hộ của tôi nhìn ra một ngọn đồi đầy cây thông."},{"fr":"Ici, il fait frais toute l'année, même en été.","tgt":"Ở đây trời mát quanh năm, kể cả mùa hè."},{"fr":"Le soir, j'ai besoin d'un pull et d'une couverture.","tgt":"Buổi tối, tôi cần áo len và chăn."},{"fr":"Les gens d'ici parlent doucement et sourient beaucoup.","tgt":"Người ở đây nói nhẹ nhàng và hay cười."},{"fr":"Ma propriétaire habite juste au rez-de-chaussée.","tgt":"Bà chủ nhà của tôi sống ngay ở tầng một."},{"fr":"Elle m'a apporté un pot de confiture de fraises.","tgt":"Bà ấy mang cho tôi một lọ mứt dâu."},{"fr":"Je ne connais encore personne dans le quartier.","tgt":"Tôi chưa quen ai trong khu phố này cả."},{"fr":"Il faut combien de temps pour aller au centre à pied ?","tgt":"Đi bộ ra trung tâm mất bao lâu?"},{"fr":"Environ quinze minutes, en descendant la colline.","tgt":"Khoảng mười lăm phút, đi xuống dốc."}]},{"title":"Une bonne nouvelle au travail","phrases":[{"fr":"J'ai une bonne nouvelle à t'annoncer !","tgt":"Em có một tin vui muốn báo với anh!"},{"fr":"J'ai été augmentée ce mois-ci.","tgt":"Tháng này em được tăng lương."},{"fr":"Mon chef m'a félicitée devant toute l'équipe.","tgt":"Em được sếp khen trước cả nhóm."},{"fr":"Nous avons eu trois jours de congé pour la fête des fleurs.","tgt":"Bọn em được nghỉ ba ngày dịp lễ hội hoa."},{"fr":"Félicitations, tu le mérites vraiment !","tgt":"Chúc mừng em, em xứng đáng lắm!"},{"fr":"Moi aussi, on m'a offert un panier de fraises hier.","tgt":"Anh cũng được tặng một giỏ dâu tây hôm qua."},{"fr":"Ma fille a été choisie pour chanter au festival.","tgt":"Con gái anh được chọn hát ở lễ hội."},{"fr":"On va fêter ça autour d'un café ce soir ?","tgt":"Tối nay mình đi cà phê ăn mừng nhé?"},{"fr":"Bonne idée, c'est moi qui t'invite.","tgt":"Ý hay đấy, anh mời em."},{"fr":"En plus, j'ai pu rentrer plus tôt aujourd'hui.","tgt":"Hôm nay em còn được về sớm nữa."}],"tip":{"title":"« Được » : quand il arrive quelque chose de bien","example":"J'ai été augmentée ce mois-ci. — Tháng này em <b>được</b> tăng lương.","body":"En vietnamien, quand il vous arrive quelque chose d'agréable, on place le petit mot « được », qui veut dire recevoir ou avoir la chance de, juste devant le verbe. Là où le français dit « j'ai été augmentée », le vietnamien dit simplement : ce mois-ci, moi, recevoir, augmenter salaire. On peut même glisser entre les deux la personne qui fait l'action : « em được sếp khen », moi, recevoir, chef, féliciter, c'est-à-dire mon chef m'a félicitée. Vous direz aussi « được nghỉ », avoir congé, ou « được tặng », recevoir en cadeau. Pour retenir, imaginez « được » comme un petit sourire posé devant le verbe : la nouvelle est bonne.","lit":"mois · ce · je · [recevoir, en bien] · augmenter · salaire","say":{"Được":"Được","được":"được","em được sếp khen":"em được sếp khen","được nghỉ":"được nghỉ","được tặng":"được tặng"}}},{"title":"Le marché aux fraises","phrases":[{"fr":"Le samedi matin, je vais au marché de Đà Lạt.","tgt":"Sáng thứ bảy, tôi đi chợ Đà Lạt."},{"fr":"En ce moment, les fraises sont rouges et très parfumées.","tgt":"Dạo này dâu tây đỏ và thơm lắm."},{"fr":"Combien coûte le kilo de fraises, madame ?","tgt":"Dâu này bao nhiêu tiền một cân hả chị?"},{"fr":"Quatre-vingt mille dongs le kilo.","tgt":"Tám mươi nghìn một cân em ạ."},{"fr":"C'est un peu cher, vous pouvez baisser un peu ?","tgt":"Hơi đắt, chị bớt cho em một chút được không?"},{"fr":"Je vous les laisse à soixante-dix mille, pas moins.","tgt":"Chị để em bảy mươi nghìn, không bớt nữa đâu."},{"fr":"D'accord, j'en prends deux kilos.","tgt":"Vâng, em lấy hai cân."},{"fr":"Choisissez-moi les plus fermes, s'il vous plaît.","tgt":"Chị chọn giúp em những quả chắc nhé."},{"fr":"Ces fraises ont été cueillies ce matin même.","tgt":"Dâu này mới hái sáng nay."},{"fr":"Je vais en faire du jus pour mes collègues.","tgt":"Em sẽ làm nước ép cho đồng nghiệp."}]},{"title":"Les artichauts de Đà Lạt","phrases":[{"fr":"Đà Lạt est célèbre pour ses artichauts.","tgt":"Đà Lạt nổi tiếng với atisô."},{"fr":"Je n'avais jamais bu d'infusion d'artichaut avant.","tgt":"Trước đây tôi chưa bao giờ uống trà atisô."},{"fr":"Le goût est un peu sucré, un peu amer.","tgt":"Vị hơi ngọt, hơi đắng."},{"fr":"On dit que c'est bon pour le foie.","tgt":"Người ta nói nó tốt cho gan."},{"fr":"Ma voisine fait mijoter les artichauts avec des os de porc.","tgt":"Chị hàng xóm hầm atisô với xương lợn."},{"fr":"C'est une soupe très nourrissante quand il fait froid.","tgt":"Đó là món canh rất bổ khi trời lạnh."},{"fr":"Où peut-on acheter des artichauts séchés ?","tgt":"Mua atisô khô ở đâu?"},{"fr":"Il y a un stand juste à côté de l'entrée du marché.","tgt":"Có một sạp ngay cạnh cổng chợ."},{"fr":"J'en rapporterai un paquet à ma mère en France.","tgt":"Tôi sẽ mang về Pháp một gói cho mẹ."},{"fr":"Elle adore découvrir des saveurs nouvelles.","tgt":"Mẹ tôi rất thích khám phá những hương vị mới."}]},{"title":"Une journée sans chance","phrases":[{"fr":"Aujourd'hui, c'était vraiment une journée sans chance.","tgt":"Hôm nay đúng là một ngày xui xẻo."},{"fr":"Ce matin, je me suis fait surprendre par une grosse averse.","tgt":"Sáng nay tôi bị mắc mưa to."},{"fr":"Mon scooter a crevé en montant la côte.","tgt":"Xe máy của tôi bị thủng lốp lúc lên dốc."},{"fr":"Je suis arrivé en retard et mon chef m'a grondé.","tgt":"Tôi đến muộn nên bị sếp mắng."},{"fr":"En plus, je crois que j'ai attrapé un rhume.","tgt":"Thêm nữa, hình như tôi bị cảm rồi."},{"fr":"Ma collègue s'est fait voler son portefeuille au marché.","tgt":"Chị đồng nghiệp của tôi bị móc mất ví ở chợ."},{"fr":"Oh là là, tu n'as vraiment pas eu de chance !","tgt":"Trời ơi, anh xui quá!"},{"fr":"Tu ne t'es pas fait mal, au moins ?","tgt":"Anh có bị đau ở đâu không?"},{"fr":"Non, heureusement, je suis juste un peu mouillé.","tgt":"Không, may quá, anh chỉ bị ướt một chút thôi."},{"fr":"Demain, ça ira sûrement mieux.","tgt":"Mai chắc sẽ tốt hơn."}],"tip":{"title":"« Bị » : quand il arrive quelque chose de mal","example":"Je suis arrivé en retard et mon chef m'a grondé. — Tôi đến muộn nên <b>bị</b> sếp mắng.","body":"« Bị » est le jumeau sombre de « được » : on le place devant le verbe quand il nous arrive quelque chose de désagréable. « Tôi bị mắc mưa », mot à mot je, subir, coincé, pluie, veut dire je me suis fait surprendre par la pluie. Il sert aussi pour la santé et les petits ennuis : « bị cảm », attraper un rhume, « bị ướt », être mouillé, « bị muộn », être en retard. Comme avec « được », on peut placer l'auteur au milieu : « bị sếp mắng », subir, chef, gronder, mon chef m'a grondé. Pour retenir, prononcez « bị » bas et bref, comme un petit soupir de contrariété.","lit":"je · arriver · en retard · donc · [subir, en mal] · chef · gronder","say":{"Bị":"Bị","được":"được","Tôi bị mắc mưa":"Tôi bị mắc mưa","bị cảm":"bị cảm","bị ướt":"bị ướt","bị muộn":"bị muộn","bị sếp mắng":"bị sếp mắng","bị":"bị"}}},{"title":"Fin de journée au bureau","phrases":[{"fr":"Tu as fini ton rapport ?","tgt":"Em làm xong báo cáo chưa?"},{"fr":"Oui, je l'ai terminé il y a une heure.","tgt":"Rồi ạ, em làm xong từ một tiếng trước rồi."},{"fr":"Une fois le travail fini, je passe acheter du lait.","tgt":"Làm xong, em ghé mua sữa."},{"fr":"Désolé, il n'y a plus de lait frais.","tgt":"Xin lỗi, hết sữa tươi rồi."},{"fr":"Le parking est complet, il n'y a plus de place.","tgt":"Bãi xe hết chỗ rồi."},{"fr":"Mon téléphone n'a plus de batterie.","tgt":"Điện thoại của tôi hết pin rồi."},{"fr":"J'ai dépensé tout mon argent ce mois-ci.","tgt":"Tháng này tôi tiêu hết tiền rồi."},{"fr":"Tu as fini de manger ? On peut y aller.","tgt":"Anh ăn xong chưa? Mình đi thôi."},{"fr":"Attends, je finis mon café d'abord.","tgt":"Chờ chút, để em uống hết cà phê đã."},{"fr":"Voilà, tout est terminé, rentrons à la maison.","tgt":"Xong hết rồi, mình về nhà thôi."}],"tip":{"title":"« Xong » et « hết » : avoir fini, il n'y en a plus","example":"Désolé, il n'y a plus de lait frais. — Xin lỗi, <b>hết</b> sữa tươi rồi.","body":"Pour dire qu'on a terminé une action, le vietnamien ajoute « xong », fini, juste après le verbe : « ăn xong », manger fini, signifie j'ai fini de manger. Pour demander si c'est fait, on ajoute « chưa » à la fin : « xong chưa ? », c'est fini ? Le mot « hết », lui, veut dire épuisé, il n'en reste plus : « hết sữa rồi », plus de lait, ou « hết pin », plus de batterie. Placé après un verbe, « hết » veut dire jusqu'au bout : « uống hết », tout boire. Le petit « rồi », déjà, accompagne presque toujours ces deux mots en fin de phrase. Pour retenir : « xong » parle de la tâche, « hết » parle de la réserve.","lit":"pardon · [épuisé] · lait · frais · [déjà]","say":{"Xong":"Xong","hết":"hết","xong":"xong","ăn xong":"ăn xong","chưa":"chưa","xong chưa ?":"xong chưa ?","hết sữa rồi":"hết sữa rồi","hết pin":"hết pin","uống hết":"uống hết","rồi":"rồi"}}},{"title":"Le tour du lac Xuân Hương","phrases":[{"fr":"Chaque matin, je fais le tour du lac Xuân Hương à pied.","tgt":"Sáng nào tôi cũng đi bộ quanh hồ Xuân Hương."},{"fr":"Le tour complet fait environ sept kilomètres.","tgt":"Đi hết một vòng khoảng bảy cây số."},{"fr":"À six heures, la brume couvre encore l'eau.","tgt":"Lúc sáu giờ, sương mù vẫn còn phủ mặt hồ."},{"fr":"Beaucoup de personnes âgées font de la gymnastique au bord du lac.","tgt":"Nhiều cụ già tập thể dục bên hồ."},{"fr":"Des jeunes louent des pédalos en forme de cygne.","tgt":"Các bạn trẻ thuê thuyền đạp hình thiên nga."},{"fr":"Je m'arrête souvent pour boire un lait de soja chaud.","tgt":"Tôi hay dừng lại uống một cốc sữa đậu nành nóng."},{"fr":"Le vendeur me reconnaît maintenant.","tgt":"Bây giờ chú bán hàng đã nhận ra tôi rồi."},{"fr":"Il me demande toujours si j'ai bien dormi.","tgt":"Chú ấy lúc nào cũng hỏi tôi ngủ có ngon không."},{"fr":"Cette promenade me met de bonne humeur pour toute la journée.","tgt":"Đi dạo thế này giúp tôi vui cả ngày."},{"fr":"Tu veux venir avec moi demain matin ?","tgt":"Sáng mai em có muốn đi cùng anh không?"}]},{"title":"La fraîcheur du matin","phrases":[{"fr":"Ce matin, il fait seulement douze degrés.","tgt":"Sáng nay trời chỉ có mười hai độ."},{"fr":"Je n'ai aucune envie de sortir de la couette.","tgt":"Tôi chẳng muốn chui ra khỏi chăn chút nào."},{"fr":"Une tasse de café chaud, et ça va tout de suite mieux.","tgt":"Một cốc cà phê nóng là thấy đỡ hơn ngay."},{"fr":"À Đà Lạt, on préfère le café chaud au café glacé.","tgt":"Ở Đà Lạt, người ta thích uống cà phê nóng hơn cà phê đá."},{"fr":"Les vitres sont couvertes de buée.","tgt":"Cửa kính phủ đầy hơi nước."},{"fr":"N'oublie pas ton écharpe, il y a du vent.","tgt":"Nhớ quàng khăn nhé, trời có gió đấy."},{"fr":"Au coin de la rue, on vend des patates douces grillées.","tgt":"Ở góc phố có người bán khoai lang nướng."},{"fr":"Rien qu'à l'odeur, j'ai déjà faim.","tgt":"Ngửi mùi là tôi thấy đói ngay."},{"fr":"Vers dix heures, le soleil réchauffe enfin la ville.","tgt":"Khoảng mười giờ, nắng mới làm ấm thành phố."},{"fr":"J'aime ce climat, il me rappelle l'automne en France.","tgt":"Tôi thích khí hậu này, nó làm tôi nhớ mùa thu ở Pháp."}]},{"title":"Les courses de la semaine","phrases":[{"fr":"Il faut faire les courses, le frigo est vide.","tgt":"Phải đi chợ thôi, tủ lạnh trống trơn rồi."},{"fr":"Faisons une liste avant de partir.","tgt":"Mình viết danh sách trước khi đi nhé."},{"fr":"Il nous faut du riz, des œufs et de la sauce de poisson.","tgt":"Mình cần gạo, trứng và nước mắm."},{"fr":"Les légumes sont moins chers au marché qu'au supermarché.","tgt":"Rau ở chợ rẻ hơn ở siêu thị."},{"fr":"Mais le supermarché est plus près de chez nous.","tgt":"Nhưng siêu thị gần nhà mình hơn."},{"fr":"Prends aussi un chou et quelques carottes de Đà Lạt.","tgt":"Lấy thêm một cái bắp cải và ít cà rốt Đà Lạt nhé."},{"fr":"Les avocats sont mûrs, on en prend trois ?","tgt":"Bơ chín rồi, mình lấy ba quả nhé?"},{"fr":"Pense à emporter un sac en tissu.","tgt":"Nhớ mang theo túi vải nhé."},{"fr":"Ça fait trois cent cinquante mille dongs en tout.","tgt":"Tất cả là ba trăm năm mươi nghìn đồng."},{"fr":"Tu peux porter le sac de riz ? Il est lourd.","tgt":"Anh xách bao gạo giúp em nhé, nặng lắm."}]},{"title":"Le scooter en panne","phrases":[{"fr":"Ce matin, mon scooter refuse de démarrer.","tgt":"Sáng nay xe máy của tôi không nổ máy được."},{"fr":"Il y a un réparateur au bout de la rue.","tgt":"Cuối phố có một tiệm sửa xe."},{"fr":"Bonjour, monsieur, pouvez-vous regarder mon scooter ?","tgt":"Chào chú, chú xem giúp cháu cái xe được không ạ?"},{"fr":"La batterie est sûrement trop vieille.","tgt":"Chắc ắc quy cũ quá rồi."},{"fr":"Combien de temps faut-il pour la changer ?","tgt":"Thay mất bao lâu ạ?"},{"fr":"Une demi-heure à peine, tu peux attendre ici.","tgt":"Chỉ nửa tiếng thôi, cháu ngồi đây đợi nhé."},{"fr":"Ça coûtera combien, à peu près ?","tgt":"Khoảng bao nhiêu tiền ạ?"},{"fr":"Quatre cent mille, batterie neuve comprise.","tgt":"Bốn trăm nghìn, cả tiền ắc quy mới."},{"fr":"Les freins sont un peu usés aussi.","tgt":"Phanh cũng hơi mòn rồi."},{"fr":"Pense à faire réviser ton scooter avant la saison des pluies.","tgt":"Cháu nhớ bảo dưỡng xe trước mùa mưa nhé."}]},{"title":"Un rhume de saison","phrases":[{"fr":"J'ai mal à la gorge depuis deux jours.","tgt":"Tôi bị đau họng hai hôm nay rồi."},{"fr":"Je tousse beaucoup la nuit.","tgt":"Đêm tôi ho nhiều lắm."},{"fr":"C'est la saison, tout le monde est enrhumé.","tgt":"Đang mùa mà, ai cũng bị cảm."},{"fr":"Tu as de la fièvre ?","tgt":"Em có sốt không?"},{"fr":"Un peu, trente-huit degrés ce matin.","tgt":"Có một chút, sáng nay ba mươi tám độ."},{"fr":"Va à la pharmacie près du marché.","tgt":"Em ra hiệu thuốc gần chợ đi."},{"fr":"Le pharmacien m'a donné des pastilles et du sirop.","tgt":"Dược sĩ đưa cho em thuốc ngậm và siro."},{"fr":"Bois beaucoup d'eau chaude au gingembre.","tgt":"Uống nhiều nước gừng nóng vào."},{"fr":"Repose-toi, reste à la maison demain.","tgt":"Em nghỉ ngơi đi, mai cứ ở nhà cho khỏe."},{"fr":"Merci, je vais me coucher tôt ce soir.","tgt":"Cảm ơn anh, tối nay em sẽ đi ngủ sớm."}]},{"title":"Une journée comme les autres","phrases":[{"fr":"Je me lève à six heures tous les jours.","tgt":"Ngày nào tôi cũng dậy lúc sáu giờ."},{"fr":"Hier, je suis allé travailler à vélo.","tgt":"Hôm qua tôi đi làm bằng xe đạp."},{"fr":"Demain, je vais au marché avec ma voisine.","tgt":"Mai tôi đi chợ với chị hàng xóm."},{"fr":"Qu'est-ce que tu fais ce week-end ?","tgt":"Cuối tuần này em làm gì?"},{"fr":"Samedi, je vais cueillir des fraises dans une ferme.","tgt":"Thứ bảy em đi hái dâu ở một trang trại."},{"fr":"L'année dernière, j'habitais encore à Hanoï.","tgt":"Năm ngoái tôi còn sống ở Hà Nội."},{"fr":"Maintenant, je travaille dans un hôtel près du lac.","tgt":"Bây giờ tôi làm ở một khách sạn gần hồ."},{"fr":"Tu as déjà mangé ?","tgt":"Anh ăn cơm chưa?"},{"fr":"Oui, j'ai mangé un bol de vermicelles tout à l'heure.","tgt":"Rồi, lúc nãy anh ăn một bát bún rồi."},{"fr":"Sois tranquille, j'appelle le propriétaire ce soir.","tgt":"Yên tâm, tối nay anh gọi cho chủ nhà."}],"tip":{"title":"« Đã », « đang », « sẽ » : quand on peut s'en passer","example":"Hier, je suis allé travailler à vélo. — <b>Hôm qua</b> tôi đi làm bằng xe đạp.","body":"Vous connaissez « đã », l'accompli, « đang », l'action en cours, et « sẽ », le futur. Bonne nouvelle : à l'oral, on les laisse très souvent tomber dès que le moment est déjà clair. Si la phrase contient « hôm qua », hier, « mai », demain, ou « bây giờ », maintenant, le verbe reste nu : « hôm qua tôi đi làm », hier, je, aller, travailler, suffit pour dire je suis allé travailler. De même, « mai tôi đi chợ » veut dire demain je vais au marché, et « anh ăn cơm chưa ? » demande tu as mangé, sans aucun marqueur. On garde ces petits mots surtout pour insister ou lever un doute. Retenez : le mot de temps fait le travail, le verbe se repose.","lit":"hier · je · aller · travailler · par · vélo","say":{"Đã":"Đã","đang":"đang","sẽ":"sẽ","đã":"đã","hôm qua":"hôm qua","mai":"mai","bây giờ":"bây giờ","hôm qua tôi đi làm":"hôm qua tôi đi làm","mai tôi đi chợ":"mai tôi đi chợ","anh ăn cơm chưa ?":"anh ăn cơm chưa ?"}}},{"title":"La pluie de l'après-midi","phrases":[{"fr":"Pendant la saison des pluies, il pleut presque tous les après-midi.","tgt":"Mùa mưa, chiều nào cũng mưa."},{"fr":"Le ciel était bleu, et soudain l'averse est tombée.","tgt":"Trời đang xanh, tự nhiên đổ mưa."},{"fr":"Tu as un parapluie ?","tgt":"Anh có ô không?"},{"fr":"Non, je l'ai oublié à la maison.","tgt":"Không, anh để quên ở nhà rồi."},{"fr":"Mettons-nous à l'abri sous cet auvent.","tgt":"Mình vào trú dưới mái hiên này đi."},{"fr":"Ici, les averses ne durent jamais longtemps.","tgt":"Mưa ở đây không bao giờ kéo dài lâu."},{"fr":"Dans vingt minutes, le soleil sera revenu.","tgt":"Hai mươi phút nữa là nắng lại thôi."},{"fr":"Les motards enfilent vite leur poncho.","tgt":"Người đi xe máy vội mặc áo mưa."},{"fr":"Les rues en pente deviennent glissantes.","tgt":"Mấy con đường dốc trở nên trơn."},{"fr":"Rentrons doucement, rien ne presse.","tgt":"Mình về từ từ thôi, có gì đâu mà vội."}]},{"title":"Les voisins","phrases":[{"fr":"Mes voisins d'en face cultivent des fleurs sous serre.","tgt":"Hàng xóm đối diện nhà tôi trồng hoa trong nhà kính."},{"fr":"Ils font pousser des roses et des hortensias.","tgt":"Họ trồng hoa hồng và hoa cẩm tú cầu."},{"fr":"Le grand-père me fait toujours un signe de la main.","tgt":"Ông cụ lúc nào cũng vẫy tay chào tôi."},{"fr":"Leur fils m'aide parfois à réparer des choses.","tgt":"Con trai họ thỉnh thoảng giúp tôi sửa đồ."},{"fr":"Hier, ils m'ont invité à dîner chez eux.","tgt":"Hôm qua họ mời tôi sang nhà ăn tối."},{"fr":"Je leur ai apporté un gâteau à la française.","tgt":"Tôi mang sang một cái bánh kiểu Pháp."},{"fr":"Le chien des voisins aboie un peu trop la nuit.","tgt":"Con chó nhà hàng xóm sủa hơi nhiều vào ban đêm."},{"fr":"Je n'ose pas le leur dire, ils sont si gentils.","tgt":"Tôi không dám nói, họ tốt bụng quá."},{"fr":"Tu devrais leur en parler gentiment.","tgt":"Anh nên nói nhẹ nhàng với họ."},{"fr":"Ici, entre voisins, on s'entraide beaucoup.","tgt":"Ở đây, hàng xóm giúp đỡ nhau nhiều lắm."}]},{"title":"Le marché aux fleurs","phrases":[{"fr":"On surnomme Đà Lạt la ville des fleurs.","tgt":"Đà Lạt được gọi là thành phố hoa."},{"fr":"Le marché aux fleurs ouvre très tôt le matin.","tgt":"Chợ hoa mở cửa từ rất sớm."},{"fr":"Je cherche un bouquet pour l'anniversaire de ma collègue.","tgt":"Tôi tìm một bó hoa tặng sinh nhật chị đồng nghiệp."},{"fr":"Elle préfère les fleurs jaunes ou roses ?","tgt":"Chị ấy thích hoa màu vàng hay màu hồng?"},{"fr":"Je ne sais pas, je vais prendre un bouquet de toutes les couleurs.","tgt":"Tôi không biết, chắc tôi lấy bó nhiều màu."},{"fr":"Ces petites fleurs violettes sont des immortelles.","tgt":"Mấy bông hoa tím nhỏ này là hoa bất tử."},{"fr":"Elles gardent leur couleur pendant des mois.","tgt":"Hoa này giữ được màu mấy tháng liền."},{"fr":"Pouvez-vous l'emballer dans du papier brun ?","tgt":"Chị gói giúp em bằng giấy nâu được không?"},{"fr":"Ce bouquet fait cent vingt mille dongs.","tgt":"Bó này một trăm hai mươi nghìn."},{"fr":"Elle sera sûrement ravie.","tgt":"Chắc chị ấy sẽ vui lắm."}]},{"title":"Une coupure d'eau","phrases":[{"fr":"Depuis ce matin, plus une goutte ne sort du robinet.","tgt":"Từ sáng đến giờ vòi nước không chảy."},{"fr":"Chez les voisins non plus, il n'y a pas d'eau.","tgt":"Nhà hàng xóm cũng bị mất nước."},{"fr":"Tout le quartier est privé d'eau jusqu'à ce soir.","tgt":"Cả khu bị cắt nước đến tối."},{"fr":"Ils réparent une conduite sous la route.","tgt":"Họ đang sửa đường ống dưới đường."},{"fr":"Heureusement, j'ai rempli des bouteilles hier soir.","tgt":"May mà tối qua tôi đã đổ đầy mấy chai nước."},{"fr":"Je ne peux même pas faire la vaisselle.","tgt":"Tôi còn không rửa bát được."},{"fr":"Allons manger dehors ce soir, ce sera plus simple.","tgt":"Tối nay mình ra ngoài ăn cho tiện."},{"fr":"Ils auraient dû prévenir les habitants plus tôt.","tgt":"Lẽ ra họ phải báo cho người dân sớm hơn."},{"fr":"Il y avait pourtant un avis sur le panneau du quartier.","tgt":"Có thông báo trên bảng tin khu phố rồi mà."},{"fr":"Ah bon ? Je ne l'avais pas vu du tout.","tgt":"Thế à? Tôi không để ý thấy."}]},{"title":"Le linge qui ne sèche pas","phrases":[{"fr":"Avec cette humidité, le linge met trois jours à sécher.","tgt":"Trời ẩm thế này, quần áo phơi ba ngày mới khô."},{"fr":"Mes chemises sentent un peu l'humidité.","tgt":"Áo sơ mi của tôi hơi có mùi ẩm mốc."},{"fr":"Tu devrais aller à la laverie au bout de la rue.","tgt":"Em nên mang ra tiệm giặt ở đầu phố."},{"fr":"Ils ont des sèche-linge, c'est très pratique.","tgt":"Ở đó có máy sấy, tiện lắm."},{"fr":"On paie au kilo, environ quinze mille dongs.","tgt":"Tính theo cân, khoảng mười lăm nghìn đồng."},{"fr":"Je dépose mon sac le matin et je le reprends le soir.","tgt":"Sáng tôi gửi túi đồ, tối tôi lấy về."},{"fr":"Tout est bien plié et sent bon la lessive.","tgt":"Quần áo được gấp gọn và thơm mùi xà phòng."},{"fr":"Mais j'aime bien aussi faire sécher au soleil.","tgt":"Nhưng tôi cũng thích phơi nắng."},{"fr":"Au moindre rayon de soleil, je sors tout sur le balcon.","tgt":"Hễ có nắng là tôi mang hết ra ban công phơi."},{"fr":"À Đà Lạt, tout le monde connaît ce petit souci.","tgt":"Ở Đà Lạt, chuyện này ai cũng gặp."}]},{"title":"La soupe du soir","phrases":[{"fr":"Le soir, rien ne vaut une soupe bien chaude.","tgt":"Buổi tối, không gì bằng một bát canh nóng."},{"fr":"Ce soir, je prépare une soupe de potiron au porc haché.","tgt":"Tối nay tôi nấu canh bí đỏ thịt băm."},{"fr":"Il me faut de l'échalote, du poivre et de la coriandre.","tgt":"Tôi cần hành khô, hạt tiêu và rau mùi."},{"fr":"D'abord, je fais revenir l'échalote dans un peu d'huile.","tgt":"Trước tiên, tôi phi hành với ít dầu."},{"fr":"Ensuite, j'ajoute la viande, puis l'eau.","tgt":"Sau đó tôi cho thịt vào, rồi đổ nước."},{"fr":"On laisse mijoter un quart d'heure à feu doux.","tgt":"Đun nhỏ lửa khoảng mười lăm phút."},{"fr":"Goûte, il manque un peu de sauce de poisson ?","tgt":"Nếm thử xem, có cần thêm nước mắm không?"},{"fr":"C'est parfait comme ça, ne rajoute rien.","tgt":"Vừa miệng rồi, không cần thêm gì đâu."},{"fr":"Toute la famille se réunit autour du repas.","tgt":"Cả nhà quây quần ăn cơm với nhau."},{"fr":"Après une longue journée, c'est mon moment préféré.","tgt":"Sau một ngày dài, đây là lúc tôi thích nhất."}]},{"title":"Les règles de la pension","phrases":[{"fr":"Bienvenue dans la pension, voici quelques petites règles.","tgt":"Chào mừng em đến nhà trọ, đây là mấy quy định nhỏ."},{"fr":"Il est interdit de fumer dans les chambres.","tgt":"Không được hút thuốc trong phòng."},{"fr":"Ne laisse pas ton scooter devant le portail.","tgt":"Đừng để xe máy trước cổng nhé."},{"fr":"Après vingt-deux heures, il est interdit de faire du bruit.","tgt":"Sau mười giờ tối thì không được làm ồn."},{"fr":"Ne vous inquiétez pas, je suis quelqu'un de très calme.","tgt":"Chị đừng lo, em là người rất trầm tính."},{"fr":"On n'a pas le droit d'avoir d'animaux ici.","tgt":"Ở đây không được nuôi thú cưng."},{"fr":"N'oublie pas d'éteindre le chauffe-eau.","tgt":"Đừng quên tắt bình nóng lạnh nhé."},{"fr":"Est-ce que j'ai le droit d'utiliser la cuisine le soir ?","tgt":"Buổi tối em có được dùng bếp không ạ?"},{"fr":"Bien sûr, mais ne laisse pas la vaisselle sale jusqu'au lendemain.","tgt":"Được chứ, nhưng đừng để bát bẩn qua đêm."},{"fr":"Et surtout, ne sois pas timide, demande-moi si besoin.","tgt":"Và nhất là đừng ngại, cần gì cứ hỏi chị."}],"tip":{"title":"« Đừng » et « không được » : l'interdiction","example":"Il est interdit de fumer dans les chambres. — <b>Không được</b> hút thuốc trong phòng.","body":"Pour demander à quelqu'un de ne pas faire quelque chose, on place « đừng », ne pas, juste devant le verbe : « đừng lo », ne t'inquiète pas, ou « đừng quên », n'oublie pas. C'est une demande ou un conseil, et on l'adoucit volontiers avec « nhé » en fin de phrase : « đừng quên nhé ». Pour une vraie règle, on dit plutôt « không được », mot à mot pas permis : « không được hút thuốc », pas, permis, fumer, c'est-à-dire il est interdit de fumer. La différence ressemble à celle qui sépare « ne fais pas ça » de « c'est interdit » en français. Astuce : « đừng » s'adresse à une personne, « không được » énonce la règle pour tout le monde.","lit":"[ne pas] · [permis] · fumer · dans · chambre","say":{"Đừng":"Đừng","không được":"không được","đừng":"đừng","đừng lo":"đừng lo","đừng quên":"đừng quên","nhé":"nhé","đừng quên nhé":"đừng quên nhé","không được hút thuốc":"không được hút thuốc"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait vivre le quotidien de Đà Lạt.","tgt":"Học phần này đưa chúng ta vào nhịp sống hằng ngày ở Đà Lạt."},{"fr":"On sait maintenant annoncer une bonne ou une mauvaise nouvelle en vietnamien.","tgt":"Giờ chúng ta biết báo một tin vui hay tin buồn bằng tiếng Việt."},{"fr":"On sait dire ce qui est fini et ce qui manque.","tgt":"Chúng ta biết nói việc gì đã xong và cái gì đã hết."},{"fr":"Le vietnamien sonne déjà un peu plus naturel à l'oreille.","tgt":"Tiếng Việt nghe đã tự nhiên hơn một chút."},{"fr":"On ose même parler au marché sans préparer ses phrases.","tgt":"Chúng ta còn dám nói chuyện ở chợ mà không cần chuẩn bị trước."},{"fr":"Les tons posent encore quelques difficultés, c'est normal.","tgt":"Thanh điệu vẫn còn hơi khó, chuyện bình thường thôi."},{"fr":"Le prochain module nous fera voyager à travers le Viêt Nam.","tgt":"Học phần sau sẽ đưa chúng ta đi khắp Việt Nam."},{"fr":"Bravo, vous avez été régulier et patient.","tgt":"Bạn đã rất chăm chỉ và kiên nhẫn, giỏi lắm!"},{"fr":"Accordez-vous une petite pause avec un café chaud.","tgt":"Hãy nghỉ một chút với một cốc cà phê nóng nhé."},{"fr":"À très bientôt pour la suite de l'aventure.","tgt":"Hẹn sớm gặp lại ở phần tiếp theo."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le train de nuit depuis Hanoï","phrases":[{"fr":"Ce soir, on prend le train de nuit pour Lào Cai.","tgt":"Tối nay, chúng ta đi tàu đêm lên Lào Cai."},{"fr":"La gare de Hanoï est pleine de voyageurs.","tgt":"Ga Hà Nội rất đông hành khách."},{"fr":"Notre train part à neuf heures et demie.","tgt":"Tàu của chúng ta khởi hành lúc chín giờ rưỡi."},{"fr":"Vous avez réservé une cabine à quatre couchettes ?","tgt":"Anh đã đặt khoang bốn giường chưa?"},{"fr":"Oui, et les billets sont déjà sur mon téléphone.","tgt":"Đặt rồi, vé đã có sẵn trong điện thoại của tôi."},{"fr":"Il faut acheter de l'eau et quelque chose à grignoter.","tgt":"Phải mua nước và chút gì đó để ăn vặt."},{"fr":"Le contrôleur vérifie les billets sur le quai.","tgt":"Nhân viên soát vé kiểm tra vé ở sân ga."},{"fr":"Notre wagon est tout au bout du train.","tgt":"Toa của chúng ta ở tận cuối đoàn tàu."},{"fr":"Le voyage dure environ huit heures.","tgt":"Chuyến đi mất khoảng tám tiếng."},{"fr":"On arrivera tôt demain matin.","tgt":"Sáng sớm mai chúng ta sẽ đến nơi."}]},{"title":"Une nuit en couchette","phrases":[{"fr":"Ma couchette est en haut, la tienne est en bas.","tgt":"Giường của tôi ở tầng trên, của bạn ở tầng dưới."},{"fr":"Tu peux m'aider à ranger ma valise ?","tgt":"Bạn giúp tôi cất va li được không?"},{"fr":"Les draps et les oreillers sont fournis.","tgt":"Có sẵn ga trải giường và gối."},{"fr":"Le train balance un peu, mais c'est agréable.","tgt":"Tàu hơi lắc, nhưng cũng dễ chịu."},{"fr":"Nos voisins de cabine sont une famille de Hanoï.","tgt":"Hàng xóm cùng khoang là một gia đình người Hà Nội."},{"fr":"Le grand-père nous offre du thé vert.","tgt":"Ông cụ mời chúng tôi uống trà xanh."},{"fr":"Je n'arrive pas à dormir avec ce bruit.","tgt":"Ồn thế này tôi không ngủ được."},{"fr":"Tu as des bouchons d'oreilles en plus ?","tgt":"Bạn có thừa nút bịt tai không?"},{"fr":"Éteins la lumière, s'il te plaît.","tgt":"Bạn tắt đèn giúp tôi nhé."},{"fr":"Bonne nuit, à demain matin !","tgt":"Chúc ngủ ngon, sáng mai gặp lại nhé!"}]},{"title":"De Lào Cai à Sa Pa","phrases":[{"fr":"On descend du train à Lào Cai.","tgt":"Chúng ta xuống tàu ở Lào Cai."},{"fr":"Ensuite, on monte à Sa Pa en minibus.","tgt":"Sau đó, chúng ta đi xe buýt nhỏ lên Sa Pa."},{"fr":"Sortez de la gare et tournez à gauche.","tgt":"Anh ra khỏi ga rồi rẽ trái."},{"fr":"Le chauffeur nous attend devant l'entrée.","tgt":"Bác tài đang đợi chúng ta trước cổng ga."},{"fr":"Monte dans le bus, je mets les sacs dans le coffre.","tgt":"Bạn lên xe đi, tôi cho ba lô vào cốp."},{"fr":"La route monte dans la montagne pendant une heure.","tgt":"Đường đi lên núi mất khoảng một tiếng."},{"fr":"Le brouillard descend sur la vallée.","tgt":"Sương mù đang buông xuống thung lũng."},{"fr":"On entre dans la ville de Sa Pa vers sept heures.","tgt":"Khoảng bảy giờ, chúng ta vào đến thị trấn Sa Pa."},{"fr":"Descends ici, l'hôtel est juste à côté.","tgt":"Bạn xuống đây đi, khách sạn ở ngay bên cạnh."},{"fr":"Entrez, et posez vos sacs ici.","tgt":"Mời anh chị vào, cứ để túi ở đây."}],"tip":{"title":"« Lên », « xuống », « ra », « vào » : monter, descendre, sortir, entrer","example":"Ensuite, on monte à Sa Pa en minibus. — Sau đó, chúng ta đi xe buýt nhỏ <b>lên</b> Sa Pa.","body":"Le vietnamien indique la direction avec quatre petits mots très courts : « lên », monter, « xuống », descendre, « ra », sortir, et « vào », entrer. On peut les employer seuls comme verbes, par exemple « xuống tàu », descendre du train, ou les placer juste après un verbe de mouvement, comme « đi lên », aller en montant. Notre exemple se décompose ainsi : après cela, nous, aller, bus, petit, monter, Sa Pa ; on va en minibus en montant vers Sa Pa. Les Vietnamiens s'en servent aussi pour la géographie : on « monte » vers les montagnes du Nord et on « sort » vers la mer, comme dans « ra biển », aller à la mer. Retenez enfin « ra khỏi », sortir de, et « mời vào », entrez donc, très utile pour accueillir quelqu'un. Astuce : imaginez un ascenseur pour « lên » et « xuống », et une porte pour « ra » et « vào ».","lit":"après · cela · nous · aller · bus · petit · monter · Sa Pa","say":{"Lên":"Lên","xuống":"xuống","ra":"ra","vào":"vào","lên":"lên","xuống tàu":"xuống tàu","đi lên":"đi lên","ra biển":"ra biển","ra khỏi":"ra khỏi","mời vào":"mời vào"}}},{"title":"Le marché de Sa Pa","phrases":[{"fr":"Le marché de Sa Pa est très animé le matin.","tgt":"Chợ Sa Pa buổi sáng rất nhộn nhịp."},{"fr":"Les femmes hmong vendent des tissus brodés à la main.","tgt":"Các chị người Hmông bán vải thêu tay."},{"fr":"Ce sac est fait en chanvre teint à l'indigo.","tgt":"Chiếc túi này làm bằng vải lanh nhuộm chàm."},{"fr":"Combien coûte cette écharpe, madame ?","tgt":"Chiếc khăn này bao nhiêu tiền hả chị?"},{"fr":"Cent cinquante mille dongs.","tgt":"Một trăm năm mươi nghìn đồng."},{"fr":"C'est un peu cher, vous pouvez baisser le prix ?","tgt":"Hơi đắt, chị bớt cho em một chút được không?"},{"fr":"J'en prends deux, vous me faites un prix ?","tgt":"Em lấy hai chiếc, chị tính rẻ cho em nhé?"},{"fr":"Il fait froid ici, je vais acheter une veste chaude.","tgt":"Ở đây lạnh quá, tôi sẽ mua một chiếc áo khoác ấm."},{"fr":"On goûte le maïs grillé au bord de la route ?","tgt":"Mình ăn thử ngô nướng ven đường không?"},{"fr":"Ces brochettes sentent vraiment bon.","tgt":"Mấy xiên thịt nướng này thơm quá."}]},{"title":"Préparer la randonnée","phrases":[{"fr":"On va bientôt partir pour la randonnée.","tgt":"Chúng ta sắp lên đường đi bộ rồi."},{"fr":"Le guide est sur le point d'arriver.","tgt":"Hướng dẫn viên sắp đến rồi."},{"fr":"Mets tes chaussures de marche, on part bientôt.","tgt":"Bạn đi giày leo núi vào đi, sắp đi rồi."},{"fr":"Tu as pris ton imperméable ?","tgt":"Bạn đã mang áo mưa chưa?"},{"fr":"Il va bientôt pleuvoir, regarde ces nuages.","tgt":"Trời sắp mưa rồi, nhìn những đám mây kia kìa."},{"fr":"Mon téléphone est presque à plat.","tgt":"Điện thoại của tôi sắp hết pin."},{"fr":"Remplis les gourdes avant de partir.","tgt":"Đổ đầy bình nước trước khi đi nhé."},{"fr":"L'étape d'aujourd'hui fait environ douze kilomètres.","tgt":"Chặng hôm nay dài khoảng mười hai cây số."},{"fr":"On achète du pain et des fruits pour midi.","tgt":"Mình mua bánh mì và hoa quả để ăn trưa."},{"fr":"Ça y est, on est prêts à partir !","tgt":"Xong rồi, chúng ta sẵn sàng lên đường!"}],"tip":{"title":"« Sắp » : être sur le point de","example":"Il va bientôt pleuvoir, regarde ces nuages. — Trời <b>sắp</b> mưa rồi, nhìn những đám mây kia kìa.","body":"« Sắp » se place juste avant le verbe et annonce qu'une action va arriver très bientôt, comme « être sur le point de » en français. On l'entend presque toujours avec « rồi » en fin de phrase, qui ajoute l'idée de « ça y est, c'est imminent ». Dans « trời sắp mưa rồi », on a mot à mot : ciel, bientôt, pleuvoir, déjà ; autrement dit, il va pleuvoir d'un instant à l'autre. De même, on dit « tàu sắp chạy », le train va partir, et « tôi sắp đến », j'arrive bientôt. Comparez avec « sẽ », le futur simple, qui ne dit rien du délai : « sắp » est plus pressant. Astuce : pensez à « sắp » comme à une horloge qui fait tic-tac juste avant l'action.","lit":"ciel · [sur le point de] · pleuvoir · [déjà] · regarder · [pluriel] · [classificateur] · nuage · là-bas · [insistance]","say":{"Sắp":"Sắp","rồi":"rồi","trời sắp mưa rồi":"trời sắp mưa rồi","tàu sắp chạy":"tàu sắp chạy","tôi sắp đến":"tôi sắp đến","sẽ":"sẽ","sắp":"sắp"}}},{"title":"Dans les rizières en terrasses","phrases":[{"fr":"Les rizières en terrasses descendent jusqu'au ruisseau.","tgt":"Ruộng bậc thang trải dài xuống tận bờ suối."},{"fr":"En septembre, le riz devient tout doré.","tgt":"Vào tháng chín, lúa chín vàng óng."},{"fr":"Le sentier est glissant après la pluie.","tgt":"Sau cơn mưa, đường mòn rất trơn."},{"fr":"Attention, ici il faut marcher lentement.","tgt":"Cẩn thận nhé, đoạn này phải đi chậm thôi."},{"fr":"On traverse un petit pont en bambou.","tgt":"Chúng ta đi qua một cây cầu tre nhỏ."},{"fr":"Des enfants jouent avec des buffles au bord du champ.","tgt":"Mấy đứa trẻ đang chơi với trâu bên bờ ruộng."},{"fr":"Je suis fatigué, on fait une pause ?","tgt":"Tôi mệt rồi, mình nghỉ một lát nhé?"},{"fr":"D'ici, la vue est vraiment magnifique.","tgt":"Từ đây nhìn xuống, cảnh đẹp tuyệt vời."},{"fr":"Prends-moi en photo devant les rizières.","tgt":"Chụp cho tôi một tấm ảnh trước ruộng bậc thang nhé."},{"fr":"On arrive au village dans une heure.","tgt":"Một tiếng nữa là chúng ta tới bản."}]},{"title":"Avec une guide du village","phrases":[{"fr":"Notre guide s'appelle Mai, elle a vingt ans.","tgt":"Hướng dẫn viên của chúng ta tên là Mai, em ấy hai mươi tuổi."},{"fr":"Elle parle très bien le français et le vietnamien.","tgt":"Em ấy nói tiếng Pháp và tiếng Việt rất giỏi."},{"fr":"Elle est née dans un village près d'ici.","tgt":"Em ấy sinh ra ở một bản gần đây."},{"fr":"Tu fais ce métier depuis longtemps ?","tgt":"Em làm nghề này lâu chưa?"},{"fr":"Depuis trois ans, et j'adore ça.","tgt":"Được ba năm rồi ạ, em rất thích công việc này."},{"fr":"Comment dit-on merci en hmong ?","tgt":"Tiếng Hmông nói cảm ơn thế nào hả em?"},{"fr":"Les femmes d'ici cultivent le riz et le maïs.","tgt":"Phụ nữ ở đây trồng lúa và ngô."},{"fr":"Elles tissent aussi leurs propres vêtements.","tgt":"Họ còn tự dệt quần áo cho mình."},{"fr":"Ta grand-mère habite encore au village ?","tgt":"Bà của em vẫn sống ở bản à?"},{"fr":"Merci de nous faire découvrir ta région.","tgt":"Cảm ơn em đã cho chúng tôi khám phá quê hương của em."}]},{"title":"La nuit chez l'habitant","phrases":[{"fr":"Ce soir, on dort chez une famille du village.","tgt":"Tối nay chúng ta ngủ ở nhà một gia đình trong bản."},{"fr":"Si vous avez froid, il y a des couvertures en plus.","tgt":"Nếu anh chị lạnh thì có thêm chăn đây."},{"fr":"Si tu veux te doucher, la salle de bain est derrière la maison.","tgt":"Nếu bạn muốn tắm thì phòng tắm ở phía sau nhà."},{"fr":"Les matelas sont posés par terre, sous le toit.","tgt":"Đệm được trải trên sàn, ngay dưới mái nhà."},{"fr":"Si on se lève tôt, on verra le lever du soleil.","tgt":"Nếu dậy sớm thì chúng ta sẽ được ngắm bình minh."},{"fr":"Le coq chante dès cinq heures du matin.","tgt":"Gà gáy từ năm giờ sáng."},{"fr":"Si ça vous dérange, je peux fermer la fenêtre.","tgt":"Nếu anh thấy phiền thì tôi đóng cửa sổ nhé."},{"fr":"La maison est en bois, avec un grand feu au milieu.","tgt":"Ngôi nhà làm bằng gỗ, có bếp lửa lớn ở giữa."},{"fr":"S'il pleut demain, on restera ici un jour de plus.","tgt":"Nếu mai trời mưa thì chúng ta ở lại đây thêm một ngày."},{"fr":"Merci de nous accueillir chez vous.","tgt":"Cảm ơn bác đã cho chúng cháu ở nhờ."}],"tip":{"title":"« Nếu… thì… » : si… alors…","example":"S'il pleut demain, on restera ici un jour de plus. — <b>Nếu</b> mai trời mưa <b>thì</b> chúng ta ở lại đây thêm một ngày.","body":"Pour exprimer une condition, le vietnamien encadre la phrase avec deux mots : « nếu », si, au début, et « thì », alors, juste avant la conséquence. En français, on dit rarement « alors » après un « si », mais en vietnamien ce « thì » est très naturel à l'oral : il marque une petite pause, comme une charnière. Notre exemple se décompose ainsi : si, demain, ciel, pleuvoir, alors, nous, rester, ici, en plus, un, jour. Le verbe ne change pas, il n'y a ni futur ni conditionnel à conjuguer. Autres exemples : « nếu lạnh thì mặc áo », si tu as froid, mets un pull, et « nếu mệt thì nghỉ », si tu es fatigué, repose-toi. Astuce : dites « nếu… thì… » comme une balançoire, une montée puis une descente.","lit":"si · demain · ciel · pleuvoir · alors · nous · rester · ici · en plus · un · jour","say":{"Nếu… thì…":"Nếu… thì…","nếu":"nếu","thì":"thì","nếu lạnh thì mặc áo":"nếu lạnh thì mặc áo","nếu mệt thì nghỉ":"nếu mệt thì nghỉ","nếu… thì…":"nếu… thì…"}}},{"title":"Le dîner en famille","phrases":[{"fr":"La maîtresse de maison cuisine sur un feu de bois.","tgt":"Bác gái nấu cơm trên bếp củi."},{"fr":"Je peux vous aider à couper les légumes ?","tgt":"Cháu giúp bác thái rau nhé?"},{"fr":"Ce soir, il y a du porc grillé et des pousses de bambou.","tgt":"Tối nay có thịt lợn nướng và măng."},{"fr":"Le riz gluant est cuit à la vapeur dans un panier en bambou.","tgt":"Xôi được đồ trong một cái chõ tre."},{"fr":"Le grand-père sert l'alcool de maïs dans de petits verres.","tgt":"Ông rót rượu ngô vào những chén nhỏ."},{"fr":"Juste un petit verre pour moi, merci.","tgt":"Cho cháu một chén nhỏ thôi ạ."},{"fr":"Santé à toute la famille !","tgt":"Chúc sức khỏe cả nhà!"},{"fr":"Mange encore, il en reste beaucoup.","tgt":"Ăn thêm đi cháu, còn nhiều lắm."},{"fr":"Je n'en peux plus, c'était délicieux.","tgt":"Cháu no lắm rồi, ngon quá ạ."},{"fr":"Après le repas, tout le monde se réunit autour du feu.","tgt":"Sau bữa ăn, cả nhà quây quần bên bếp lửa."}]},{"title":"La pluie en montagne","phrases":[{"fr":"Il pleut à verse depuis ce matin.","tgt":"Trời mưa như trút nước từ sáng."},{"fr":"Le sentier est devenu une rivière de boue.","tgt":"Đường mòn biến thành một dòng bùn."},{"fr":"Le guide dit qu'il vaut mieux ne pas partir.","tgt":"Hướng dẫn viên bảo tốt nhất là không nên đi."},{"fr":"On annule la randonnée d'aujourd'hui ?","tgt":"Mình hủy chuyến đi bộ hôm nay nhé?"},{"fr":"Mes chaussures sont complètement trempées.","tgt":"Giày của tôi ướt sũng hết rồi."},{"fr":"Tu peux les faire sécher près du feu.","tgt":"Bạn có thể hong giày bên bếp lửa cho khô."},{"fr":"On joue aux cartes en attendant ?","tgt":"Trong lúc chờ, mình chơi bài nhé?"},{"fr":"Vers midi, le ciel commence à s'éclaircir.","tgt":"Gần trưa, trời bắt đầu hửng nắng."},{"fr":"On peut repartir cet après-midi.","tgt":"Chiều nay chúng ta có thể đi tiếp."},{"fr":"Heureusement, on a gardé un jour de marge.","tgt":"May mà chúng ta còn dư một ngày dự phòng."}]},{"title":"En car vers la baie d'Hạ Long","phrases":[{"fr":"On rentre à Hanoï, puis on part vers la mer.","tgt":"Chúng ta về Hà Nội, rồi đi ra biển."},{"fr":"Le car pour Hạ Long part à huit heures.","tgt":"Xe khách đi Hạ Long chạy lúc tám giờ."},{"fr":"Le trajet prend environ deux heures et demie.","tgt":"Đi mất khoảng hai tiếng rưỡi."},{"fr":"On peut venir nous chercher à l'hôtel ?","tgt":"Xe có đón chúng tôi ở khách sạn không?"},{"fr":"Oui, la navette passe dans le vieux quartier.","tgt":"Có, xe trung chuyển đón khách ở khu phố cổ."},{"fr":"L'autoroute est neuve et très rapide.","tgt":"Đường cao tốc mới và đi rất nhanh."},{"fr":"Le car fait une pause à mi-chemin.","tgt":"Đi được nửa đường thì xe dừng nghỉ."},{"fr":"J'ai un peu le mal des transports.","tgt":"Tôi hơi say xe."},{"fr":"Tu veux un bonbon au gingembre ?","tgt":"Bạn ăn kẹo gừng không?"},{"fr":"On voit déjà les premiers rochers au loin !","tgt":"Đã thấy những núi đá đầu tiên ở đằng xa rồi!"}]},{"title":"À bord du bateau de croisière","phrases":[{"fr":"Ce bateau est aussi grand qu'un hôtel.","tgt":"Con tàu này to bằng cả một khách sạn."},{"fr":"Notre cabine est la plus belle du bateau.","tgt":"Phòng của chúng ta đẹp nhất trên tàu."},{"fr":"La salle de bain est aussi grande que la chambre.","tgt":"Phòng tắm rộng bằng phòng ngủ."},{"fr":"On monte sur le pont supérieur pour voir la baie.","tgt":"Mình lên boong trên cùng để ngắm vịnh."},{"fr":"C'est le plus beau paysage que j'aie jamais vu.","tgt":"Đây là cảnh đẹp nhất mà tôi từng thấy."},{"fr":"Ce rocher est aussi haut qu'un immeuble de dix étages.","tgt":"Hòn đảo đá này cao bằng một tòa nhà mười tầng."},{"fr":"Le capitaine est le plus âgé de l'équipage.","tgt":"Thuyền trưởng là người lớn tuổi nhất trên tàu."},{"fr":"Quel est le meilleur moment pour se baigner ?","tgt":"Lúc nào đi bơi là tốt nhất?"},{"fr":"Le déjeuner est servi dans la salle à manger.","tgt":"Bữa trưa được dọn ra ở phòng ăn."},{"fr":"Ce sont les crevettes les plus fraîches que j'aie jamais mangées.","tgt":"Đây là món tôm tươi nhất mà tôi từng ăn."}],"tip":{"title":"« Bằng » et « nhất » : aussi… que, et le plus","example":"La salle de bain est aussi grande que la chambre. — Phòng tắm rộng <b>bằng</b> phòng ngủ.","body":"Pour comparer deux choses à égalité, on dit l'adjectif, puis « bằng », qui veut dire égal, et enfin la chose comparée. Dans « phòng tắm rộng bằng phòng ngủ », on a mot à mot : pièce pour se laver, spacieuse, égale, pièce pour dormir ; autrement dit, la salle de bain est aussi grande que la chambre. Pour le superlatif, c'est encore plus simple : on ajoute « nhất », le plus, juste après l'adjectif, comme dans « đẹp nhất », le plus beau, ou « tốt nhất », le meilleur. Attention à l'ordre : en français « le plus » vient avant l'adjectif, en vietnamien « nhất » vient après. Pour dire « pas aussi… que », on met « không » devant l'adjectif : « không to bằng », pas aussi grand que. Astuce : prononcez « nhất » comme un petit coup sec, une médaille d'or qu'on pose sur la table.","lit":"pièce · se laver · spacieux · [égal à] · pièce · dormir","say":{"Bằng":"Bằng","nhất":"nhất","bằng":"bằng","phòng tắm rộng bằng phòng ngủ":"phòng tắm rộng bằng phòng ngủ","đẹp nhất":"đẹp nhất","tốt nhất":"tốt nhất","không":"không","không to bằng":"không to bằng"}}},{"title":"La croisière entre les rochers","phrases":[{"fr":"Le bateau glisse lentement entre les îlots.","tgt":"Con tàu chầm chậm lướt giữa các đảo đá."},{"fr":"On dirait des dragons qui sortent de l'eau.","tgt":"Trông như những con rồng đang trồi lên khỏi mặt nước."},{"fr":"Ce rocher ressemble à un coq et une poule face à face.","tgt":"Hòn đá này trông giống một con gà trống và một con gà mái đứng đối diện nhau."},{"fr":"Il y a des milliers d'îles dans la baie.","tgt":"Trong vịnh có hàng nghìn hòn đảo."},{"fr":"Le guide raconte la légende de la baie.","tgt":"Hướng dẫn viên kể truyền thuyết về vịnh."},{"fr":"On passe devant un village de pêcheurs flottant.","tgt":"Chúng ta đi qua một làng chài nổi."},{"fr":"Les maisons flottent sur des radeaux.","tgt":"Những ngôi nhà nổi trên bè."},{"fr":"Les enfants vont à l'école en barque.","tgt":"Trẻ con đi học bằng thuyền nhỏ."},{"fr":"Le soleil se reflète sur l'eau calme.","tgt":"Ánh nắng phản chiếu trên mặt nước phẳng lặng."},{"fr":"Je pourrais rester ici des heures sans m'ennuyer.","tgt":"Tôi có thể ngồi đây hàng giờ mà không thấy chán."}]},{"title":"Le kayak dans la baie","phrases":[{"fr":"Cet après-midi, on fait du kayak.","tgt":"Chiều nay chúng ta đi chèo thuyền kayak."},{"fr":"Mets ton gilet de sauvetage avant de descendre dans le kayak.","tgt":"Mặc áo phao vào trước khi xuống thuyền nhé."},{"fr":"On rame à deux dans le même kayak.","tgt":"Hai người chèo chung một chiếc thuyền."},{"fr":"Rame plus fort à gauche !","tgt":"Chèo mạnh hơn bên trái đi!"},{"fr":"On passe sous une arche de pierre.","tgt":"Chúng ta chèo luồn qua dưới một vòm đá."},{"fr":"De l'autre côté, il y a un petit lagon caché.","tgt":"Phía bên kia có một cái hồ nhỏ rất kín đáo."},{"fr":"Regarde, des singes sur les rochers !","tgt":"Nhìn kìa, có khỉ trên vách đá!"},{"fr":"Ne t'approche pas trop, ils peuvent voler nos affaires.","tgt":"Đừng lại gần quá, chúng có thể giật đồ đấy."},{"fr":"Mes bras sont épuisés.","tgt":"Tay tôi mỏi rã rời rồi."},{"fr":"On rentre au bateau avant le coucher du soleil.","tgt":"Chúng ta về tàu trước khi mặt trời lặn."}]},{"title":"Dans une grotte de la baie","phrases":[{"fr":"Aujourd'hui, on visite une immense grotte.","tgt":"Hôm nay chúng ta tham quan một hang động rất lớn."},{"fr":"Il faut monter une centaine de marches.","tgt":"Phải leo khoảng một trăm bậc thang."},{"fr":"À l'intérieur, il fait frais et humide.","tgt":"Bên trong mát và ẩm."},{"fr":"Les stalactites sont éclairées de toutes les couleurs.","tgt":"Thạch nhũ được chiếu đèn đủ màu sắc."},{"fr":"Celle-ci ressemble à un éléphant, non ?","tgt":"Khối thạch nhũ này trông giống con voi nhỉ?"},{"fr":"Attention à ta tête, le plafond est bas ici.","tgt":"Cẩn thận đầu nhé, trần hang ở đây thấp."},{"fr":"Le sol est mouillé, tiens-toi à la rampe.","tgt":"Nền đất ướt đấy, bạn vịn vào lan can nhé."},{"fr":"On dit qu'un pêcheur a découvert cette grotte par hasard.","tgt":"Người ta kể rằng một ngư dân tình cờ tìm ra hang này."},{"fr":"Il y a beaucoup de monde, restons ensemble.","tgt":"Đông người quá, mình đi sát nhau nhé."},{"fr":"En sortant, la lumière du jour m'éblouit.","tgt":"Ra khỏi hang, ánh sáng ban ngày làm tôi chói mắt."}]},{"title":"Un imprévu : la tempête","phrases":[{"fr":"Une tempête approche, toutes les sorties en mer sont annulées.","tgt":"Sắp có bão, tất cả các chuyến ra khơi đều bị hủy."},{"fr":"Bien qu'il fasse beau ici, la mer est trop agitée.","tgt":"Tuy ở đây trời đẹp nhưng biển động quá."},{"fr":"Bien que ce soit dommage, c'est plus prudent.","tgt":"Tuy tiếc nhưng như vậy an toàn hơn."},{"fr":"On nous rembourse une partie du billet.","tgt":"Chúng tôi được hoàn lại một phần tiền vé."},{"fr":"Bien que le bateau reste au port, on peut dormir à bord.","tgt":"Tuy tàu nằm ở cảng nhưng chúng ta vẫn được ngủ trên tàu."},{"fr":"Il faut changer notre programme pour demain.","tgt":"Phải đổi lịch trình ngày mai."},{"fr":"Bien qu'on soit fatigués, on va visiter le marché de nuit.","tgt":"Tuy mệt nhưng chúng ta vẫn đi chợ đêm."},{"fr":"Le vent souffle très fort cette nuit.","tgt":"Đêm nay gió thổi rất mạnh."},{"fr":"Bien que la croisière soit plus courte que prévu, on a vu les plus beaux endroits.","tgt":"Tuy chuyến đi ngắn hơn dự kiến nhưng chúng ta đã xem được những chỗ đẹp nhất."},{"fr":"Ce genre d'imprévu fait partie du voyage.","tgt":"Những chuyện bất ngờ như thế này cũng là một phần của chuyến đi."}],"tip":{"title":"« Tuy… nhưng… » : bien que, mais","example":"Bien qu'il fasse beau ici, la mer est trop agitée. — <b>Tuy</b> ở đây trời đẹp <b>nhưng</b> biển động quá.","body":"Pour opposer deux idées, le vietnamien utilise une paire de mots : « tuy », bien que, au début, et « nhưng », mais, au milieu. En français, on ne dit jamais « bien que… mais… », c'est une faute ; en vietnamien, au contraire, les deux mots vont ensemble, exactement comme « nếu » et « thì ». Notre exemple se décompose ainsi : bien que, ici, ciel, beau, mais, mer, agitée, trop. On ajoute souvent « vẫn », quand même, dans la deuxième partie : « tuy mệt nhưng tôi vẫn đi », bien que fatigué, j'y vais quand même. Et il n'y a pas de subjonctif à apprendre, le verbe reste tel quel. Astuce : retenez la paire comme un duo inséparable, « tuy » ouvre la porte et « nhưng » la referme.","lit":"bien que · ici · ciel · beau · mais · mer · agité · trop","say":{"Tuy… nhưng…":"Tuy… nhưng…","tuy":"tuy","nhưng":"nhưng","nếu":"nếu","thì":"thì","vẫn":"vẫn","tuy mệt nhưng tôi vẫn đi":"tuy mệt nhưng tôi vẫn đi"}}},{"title":"Un téléphone perdu","phrases":[{"fr":"Je ne trouve plus mon téléphone !","tgt":"Tôi không tìm thấy điện thoại đâu cả!"},{"fr":"Tu l'avais encore au restaurant ?","tgt":"Lúc ở nhà hàng bạn vẫn còn cầm nó chứ?"},{"fr":"Je crois que je l'ai laissé dans le taxi.","tgt":"Tôi nghĩ là tôi để quên nó trên taxi."},{"fr":"Appelle mon numéro, on l'entendra peut-être sonner.","tgt":"Bạn gọi vào số của tôi đi, biết đâu lại nghe thấy chuông."},{"fr":"Ça sonne, mais personne ne répond.","tgt":"Chuông đổ nhưng không ai nghe máy."},{"fr":"On demande à la réception de l'hôtel ?","tgt":"Mình hỏi lễ tân khách sạn nhé?"},{"fr":"La réceptionniste appelle la compagnie de taxis.","tgt":"Cô lễ tân gọi cho hãng taxi."},{"fr":"Le chauffeur l'a trouvé sous le siège arrière.","tgt":"Bác tài đã tìm thấy nó dưới ghế sau."},{"fr":"Il nous le rapporte dans vingt minutes.","tgt":"Hai mươi phút nữa bác ấy sẽ mang đến cho chúng ta."},{"fr":"Quel soulagement ! Je vais lui laisser un bon pourboire.","tgt":"Nhẹ cả người! Tôi sẽ gửi bác ấy ít tiền bồi dưỡng."}]},{"title":"Le dernier soir sur le port","phrases":[{"fr":"Ce soir, on mange des fruits de mer sur le port.","tgt":"Tối nay chúng ta ăn hải sản ở cảng."},{"fr":"On choisit soi-même les poissons dans l'aquarium.","tgt":"Khách tự chọn cá trong bể."},{"fr":"Je voudrais un kilo de crevettes, s'il vous plaît.","tgt":"Cho tôi một cân tôm."},{"fr":"Vous les préférez grillées ou à la vapeur ?","tgt":"Anh chị muốn nướng hay hấp?"},{"fr":"À la vapeur, avec de la citronnelle.","tgt":"Hấp sả nhé."},{"fr":"Le pâté de calmar est la spécialité de Hạ Long.","tgt":"Chả mực là đặc sản của Hạ Long."},{"fr":"Attention, c'est très pimenté.","tgt":"Cẩn thận, cay lắm đấy."},{"fr":"On partage tous les plats au milieu de la table.","tgt":"Mọi người ăn chung, các món để ở giữa bàn."},{"fr":"On peut avoir l'addition ?","tgt":"Em ơi, tính tiền cho bàn này nhé."},{"fr":"C'était le meilleur repas du voyage.","tgt":"Đây là bữa ăn ngon nhất của cả chuyến đi."}]},{"title":"Les derniers souvenirs à rapporter","phrases":[{"fr":"Demain matin, on rentre à Hanoï.","tgt":"Sáng mai chúng ta về Hà Nội."},{"fr":"Il faut encore acheter des souvenirs pour la famille.","tgt":"Còn phải mua quà cho gia đình nữa."},{"fr":"Ces perles viennent d'une ferme de la baie.","tgt":"Những viên ngọc trai này đến từ một trại nuôi trong vịnh."},{"fr":"Ma mère adore les bijoux en perles.","tgt":"Mẹ tôi rất thích trang sức ngọc trai."},{"fr":"Je vais aussi rapporter du miel de montagne de Sa Pa.","tgt":"Tôi cũng sẽ mang về ít mật ong rừng Sa Pa."},{"fr":"Mon sac est trop plein, il ne ferme plus.","tgt":"Ba lô của tôi đầy quá, không kéo khóa được nữa."},{"fr":"Tu peux garder ça dans ta valise ?","tgt":"Bạn để hộ tôi cái này trong va li được không?"},{"fr":"On vérifie qu'on n'a rien oublié dans la chambre.","tgt":"Mình kiểm tra xem có quên gì trong phòng không."},{"fr":"Le car ne part qu'à midi, on a encore le temps.","tgt":"Mười hai giờ xe mới chạy, vẫn còn thời gian."},{"fr":"Je n'ai pas envie que ce voyage se termine.","tgt":"Tôi không muốn chuyến đi này kết thúc chút nào."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"En une semaine, on a vu la montagne et la mer.","tgt":"Trong một tuần, chúng ta đã thấy cả núi lẫn biển."},{"fr":"Le train de nuit était une vraie aventure.","tgt":"Chuyến tàu đêm thật sự là một cuộc phiêu lưu."},{"fr":"Je me souviendrai longtemps de cette famille de Sa Pa.","tgt":"Tôi sẽ nhớ mãi gia đình ở Sa Pa."},{"fr":"Maintenant, je sais dire monter, descendre, sortir et entrer en vietnamien.","tgt":"Giờ tôi đã biết nói lên, xuống, ra, vào bằng tiếng Việt."},{"fr":"J'arrive à comparer et à poser des conditions en vietnamien.","tgt":"Tôi đã biết so sánh và nói câu điều kiện bằng tiếng Việt."},{"fr":"Les gens me comprennent mieux quand je parle lentement.","tgt":"Khi tôi nói chậm, mọi người hiểu tôi hơn."},{"fr":"Les tons sont toujours difficiles, mais je progresse.","tgt":"Thanh điệu vẫn còn khó, nhưng tôi đang tiến bộ."},{"fr":"Le vietnamien est plus logique que je ne le pensais.","tgt":"Tiếng Việt logic hơn tôi tưởng."},{"fr":"Au prochain voyage, je parlerai encore mieux.","tgt":"Chuyến đi sau, tôi sẽ nói giỏi hơn nữa."},{"fr":"Bravo, on a terminé le module sur les voyages !","tgt":"Giỏi lắm, chúng ta đã học xong chủ đề du lịch!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouver un ami à Hội An","phrases":[{"fr":"Ça fait si longtemps qu'on ne s'est pas croisés !","tgt":"Lâu lắm rồi mình mới gặp lại nhau!"},{"fr":"Tu es arrivé à Hội An quand ?","tgt":"Bạn đến Hội An khi nào thế?"},{"fr":"Je suis arrivé avant-hier, en bus depuis Đà Nẵng.","tgt":"Tôi đến hôm kia, đi xe buýt từ Đà Nẵng."},{"fr":"Je te trouve vraiment en forme.","tgt":"Tôi thấy bạn trông khỏe lắm."},{"fr":"Toi aussi, tu n'as pas changé du tout.","tgt":"Bạn cũng vậy, chẳng thay đổi gì cả."},{"fr":"Qu'est-ce que tu deviens ces temps-ci ?","tgt":"Dạo này bạn thế nào?"},{"fr":"Je travaille toujours dans la même agence de voyage.","tgt":"Tôi vẫn làm ở công ty du lịch cũ."},{"fr":"On va boire un café pour discuter ?","tgt":"Mình đi uống cà phê nói chuyện nhé?"},{"fr":"Je connais un café tranquille au bord de la rivière.","tgt":"Tôi biết một quán yên tĩnh ở bờ sông."},{"fr":"Super, j'ai plein de choses à te raconter.","tgt":"Tuyệt, tôi có nhiều chuyện muốn kể cho bạn lắm."}]},{"title":"Entre amis, on se tutoie","phrases":[{"fr":"Minh, attends-moi !","tgt":"Minh ơi, đợi tớ với!"},{"fr":"Tu files où comme ça ?","tgt":"Cậu đi đâu đấy?"},{"fr":"Je vais au marché, tu viens avec moi ?","tgt":"Tớ ra chợ, cậu đi cùng không?"},{"fr":"Lan, tu as déjà faim ?","tgt":"Lan ơi, cậu đói chưa?"},{"fr":"Moi, je meurs de faim !","tgt":"Tớ đói meo rồi!"},{"fr":"Ce soir, c'est moi qui t'invite.","tgt":"Tối nay tớ mời cậu nhé."},{"fr":"Tu es vraiment sympa, merci !","tgt":"Cậu tốt thật đấy, cảm ơn nhé!"},{"fr":"Maman, je sors avec mes amis !","tgt":"Mẹ ơi, con đi chơi với bạn nhé!"},{"fr":"Hoa, ça fait une heure que je t'attends !","tgt":"Hoa ơi, tớ đợi cậu cả tiếng rồi đấy!"},{"fr":"On se retrouve demain au même endroit ?","tgt":"Mai tớ với cậu gặp nhau ở chỗ cũ nhé?"}],"tip":{"title":"Le registre familier entre amis : « ơi », « cậu », « tớ »","example":"Hoa, ça fait une heure que je t'attends ! — Hoa <b>ơi</b>, <b>tớ</b> đợi <b>cậu</b> cả tiếng rồi đấy!","body":"Entre copains, on ne dit presque jamais « tôi » : cela sonne froid, un peu comme vouvoyer un ami d'enfance. Entre amis du même âge, surtout dans le Nord, on dit « tớ » pour moi et « cậu » pour toi, par exemple « tớ đói », j'ai faim, ou « cậu đi đâu », tu vas où. Pour appeler quelqu'un, on ajoute « ơi » juste après son nom, en le faisant un peu traîner, comme un « hé » chantant : « Lan ơi », ou « Mẹ ơi », maman ! Dans l'exemple, mot à mot : Hoa, « ơi », moi, attendre, toi, toute une heure, déjà. Attention, ce registre est réservé aux proches : avec une personne plus âgée, on revient aux mots de parenté comme « anh » ou « chị ». Pour retenir, dites-vous que « tớ » et « cậu » vont toujours ensemble, comme les deux faces d'une même amitié.","lit":"Hoa · [appel] · moi (entre amis) · attendre · toi (entre amis) · tout · heure · [accompli] · [insistance]","say":{"ơi":"ơi","cậu":"cậu","tớ":"tớ","tôi":"tôi","tớ đói":"tớ đói","cậu đi đâu":"cậu đi đâu","Lan ơi":"Lan ơi","Mẹ ơi":"Mẹ ơi","anh":"anh","chị":"chị"}}},{"title":"Flâner dans la vieille ville","phrases":[{"fr":"La vieille ville est plus belle le soir que le matin.","tgt":"Phố cổ buổi tối đẹp hơn buổi sáng."},{"fr":"Les maisons jaunes sont vraiment ravissantes.","tgt":"Những ngôi nhà màu vàng trông xinh thật."},{"fr":"Les voitures n'ont pas le droit d'entrer dans cette rue.","tgt":"Ô tô không được vào phố này."},{"fr":"On peut tout voir à pied.","tgt":"Đi bộ là xem được hết."},{"fr":"Il y a beaucoup plus de touristes qu'avant.","tgt":"Bây giờ khách du lịch đông hơn trước nhiều."},{"fr":"Je préfère me promener tôt, quand c'est encore calme.","tgt":"Tôi thích đi dạo sớm, lúc còn yên tĩnh."},{"fr":"Cette maison ancienne a plus de deux cents ans.","tgt":"Ngôi nhà cổ này đã hơn hai trăm năm tuổi."},{"fr":"On a le droit de prendre des photos à l'intérieur ?","tgt":"Ở bên trong có được chụp ảnh không?"},{"fr":"Le propriétaire nous a raconté l'histoire de sa famille.","tgt":"Ông chủ nhà kể cho chúng tôi nghe chuyện gia đình ông."},{"fr":"Si tu es fatigué, on s'arrête boire quelque chose.","tgt":"Nếu bạn mệt thì mình dừng lại uống gì đó nhé."}]},{"title":"Les lanternes de Hội An","phrases":[{"fr":"Le soir, toute la ville s'illumine de lanternes.","tgt":"Buổi tối, cả phố sáng rực đèn lồng."},{"fr":"Ces lanternes en soie sont faites à la main.","tgt":"Những chiếc đèn lồng lụa này được làm bằng tay."},{"fr":"Laquelle tu préfères, la rouge ou la bleue ?","tgt":"Bạn thích cái nào hơn, cái đỏ hay cái xanh?"},{"fr":"Je voudrais en rapporter une à ma mère.","tgt":"Tôi muốn mua một cái về tặng mẹ."},{"fr":"Est-ce qu'on peut la plier pour la mettre dans la valise ?","tgt":"Cái này có gấp lại để cho vào va li được không?"},{"fr":"Le vendeur m'a montré comment on les fabrique.","tgt":"Người bán chỉ cho tôi cách làm đèn lồng."},{"fr":"On peut aussi poser une petite lanterne sur la rivière.","tgt":"Mình cũng có thể thả một chiếc đèn nhỏ xuống sông."},{"fr":"Il faut faire un vœu au moment de la lâcher.","tgt":"Lúc thả đèn thì phải ước một điều."},{"fr":"Les photos de nuit sont vraiment magnifiques.","tgt":"Ảnh chụp ban đêm đẹp tuyệt vời."},{"fr":"Cette soirée aux lanternes, je ne l'oublierai jamais.","tgt":"Buổi tối thả đèn này, tôi sẽ không bao giờ quên."}]},{"title":"Faire des suppositions","phrases":[{"fr":"Il va sûrement pleuvoir cet après-midi.","tgt":"Chiều nay chắc trời sẽ mưa."},{"fr":"Nam est en retard, il a sûrement encore trop dormi.","tgt":"Nam muộn rồi, chắc lại ngủ quên."},{"fr":"Peut-être qu'il a oublié notre rendez-vous.","tgt":"Có lẽ anh ấy quên mất buổi hẹn của mình rồi."},{"fr":"Ce restaurant est sûrement complet ce soir.","tgt":"Tối nay quán này chắc kín chỗ rồi."},{"fr":"On devrait peut-être réserver une table à l'avance.","tgt":"Có lẽ mình nên đặt bàn trước."},{"fr":"Tu as sûrement raison.","tgt":"Chắc bạn nói đúng đấy."},{"fr":"Ce tissu coûte sûrement très cher.","tgt":"Vải này chắc đắt lắm."},{"fr":"Peut-être, mais la qualité est excellente.","tgt":"Có lẽ vậy, nhưng chất lượng rất tốt."},{"fr":"Elle viendra peut-être avec son mari.","tgt":"Có lẽ chị ấy sẽ đi cùng chồng."},{"fr":"Après un si long trajet, tu es sûrement épuisé.","tgt":"Đi đường xa thế, chắc bạn mệt lắm."}],"tip":{"title":"« Chắc » et « có lẽ » : sûrement et peut-être","example":"Nam est en retard, il a sûrement encore trop dormi. — Nam muộn rồi, <b>chắc</b> lại ngủ quên.","body":"Pour faire une supposition, le vietnamien utilise deux petits mots placés en tête de phrase ou juste avant le verbe. « Chắc » veut dire sûrement : on est presque certain, comme dans « chắc mưa », il va sûrement pleuvoir. « Có lẽ » veut dire peut-être, c'est plus prudent : « có lẽ anh ấy quên », peut-être qu'il a oublié. Dans l'exemple, mot à mot : Nam, en retard, déjà, sûrement, encore, dormir, oublier, autrement dit il ne s'est pas réveillé. Pour répondre « peut-être bien », dites simplement « có lẽ vậy ». Astuce : « chắc » est court et sec comme une certitude, alors que « có lẽ » a deux syllabes, comme une petite hésitation.","lit":"Nam · en retard · [accompli] · sûrement · encore · dormir · oublier","say":{"Chắc":"Chắc","có lẽ":"có lẽ","chắc mưa":"chắc mưa","Có lẽ":"Có lẽ","có lẽ anh ấy quên":"có lẽ anh ấy quên","có lẽ vậy":"có lẽ vậy","chắc":"chắc"}}},{"title":"Chez le tailleur","phrases":[{"fr":"Hội An est célèbre pour ses tailleurs.","tgt":"Hội An nổi tiếng với các tiệm may."},{"fr":"Je voudrais me faire faire une chemise en lin.","tgt":"Tôi muốn may một chiếc áo sơ mi vải lanh."},{"fr":"Vous pouvez prendre mes mesures ?","tgt":"Chị đo người cho tôi được không?"},{"fr":"Il faut combien de temps pour la coudre ?","tgt":"Bao lâu thì may xong hả chị?"},{"fr":"Revenez demain après-midi pour l'essayage.","tgt":"Chiều mai anh quay lại thử áo nhé."},{"fr":"Les manches sont un peu trop longues.","tgt":"Tay áo hơi dài một chút."},{"fr":"Vous pourriez la resserrer à la taille ?","tgt":"Chị bóp eo lại một chút được không?"},{"fr":"Cette couleur vous va très bien.","tgt":"Màu này hợp với anh lắm."},{"fr":"Le prix comprend deux essayages.","tgt":"Giá này đã gồm hai lần thử."},{"fr":"C'est bien moins cher qu'en France.","tgt":"Rẻ hơn ở Pháp nhiều."}]},{"title":"Goûter le cao lầu","phrases":[{"fr":"Tu as déjà goûté le cao lầu ?","tgt":"Bạn ăn cao lầu bao giờ chưa?"},{"fr":"C'est la spécialité la plus connue de Hội An.","tgt":"Đây là món đặc sản nổi tiếng nhất của Hội An."},{"fr":"Les nouilles sont plus épaisses que celles du phở.","tgt":"Sợi mì to hơn sợi phở."},{"fr":"On le mange avec du porc et des herbes fraîches.","tgt":"Món này ăn với thịt lợn và rau sống."},{"fr":"Il n'y a presque pas de bouillon.","tgt":"Món này gần như không có nước dùng."},{"fr":"Les petits morceaux croustillants sur le dessus, c'est ce que je préfère.","tgt":"Tôi thích nhất mấy miếng giòn ở trên."},{"fr":"C'est un peu sucré, mais pas trop épicé.","tgt":"Vị hơi ngọt, nhưng không cay lắm."},{"fr":"Ajoute un peu de piment si tu aimes ça.","tgt":"Thích cay thì cho thêm chút ớt."},{"fr":"C'est encore meilleur que ce que j'imaginais.","tgt":"Ngon hơn tôi tưởng nhiều."},{"fr":"On en reprend un bol ?","tgt":"Mình gọi thêm một bát nữa nhé?"}]},{"title":"Donner son avis","phrases":[{"fr":"Qu'est-ce que tu penses de ce café ?","tgt":"Bạn thấy quán cà phê này thế nào?"},{"fr":"À mon avis, il est un peu trop bruyant.","tgt":"Theo tôi thì quán hơi ồn quá."},{"fr":"Je trouve que la musique est trop forte.","tgt":"Tôi thấy nhạc to quá."},{"fr":"Moi, au contraire, j'aime bien l'ambiance.","tgt":"Ngược lại, tôi lại thích không khí ở đây."},{"fr":"Là-dessus, je ne suis pas complètement d'accord avec toi.","tgt":"Chuyện này thì tôi không hoàn toàn đồng ý với bạn."},{"fr":"Après tout, chacun ses goûts, non ?","tgt":"Dù sao thì mỗi người một sở thích, đúng không?"},{"fr":"Le service est rapide, mais le café est moyen.","tgt":"Phục vụ nhanh, nhưng cà phê bình thường."},{"fr":"Franchement, je ne reviendrai pas ici.","tgt":"Nói thật, tôi sẽ không quay lại đây nữa."},{"fr":"Tu exagères un peu, ce n'est pas si mal.","tgt":"Bạn nói hơi quá rồi, đâu đến nỗi tệ thế."},{"fr":"Bon, la prochaine fois, c'est toi qui choisis.","tgt":"Thôi, lần sau bạn chọn quán nhé."}]},{"title":"Raconter son week-end","phrases":[{"fr":"Tu as fait quoi ce week-end ?","tgt":"Cuối tuần qua bạn làm gì?"},{"fr":"Samedi, j'ai loué un vélo pour aller à la plage.","tgt":"Thứ bảy, tôi thuê xe đạp ra biển."},{"fr":"La plage d'An Bàng n'est qu'à quelques kilomètres.","tgt":"Biển An Bàng chỉ cách đây vài cây số."},{"fr":"L'eau était chaude et il n'y avait pas grand monde.","tgt":"Nước ấm và không đông người lắm."},{"fr":"Ensuite, on a mangé des fruits de mer grillés.","tgt":"Sau đó, chúng tôi ăn hải sản nướng."},{"fr":"Dimanche, je suis resté à la maison pour me reposer.","tgt":"Chủ nhật, tôi ở nhà nghỉ ngơi."},{"fr":"J'ai lu un peu, puis j'ai fait la sieste.","tgt":"Tôi đọc sách một chút rồi ngủ trưa."},{"fr":"Le soir, mes voisins m'ont invité à dîner.","tgt":"Buổi tối, hàng xóm mời tôi sang ăn cơm."},{"fr":"C'était un week-end simple, mais très agréable.","tgt":"Một cuối tuần đơn giản, nhưng rất dễ chịu."},{"fr":"Et toi, raconte-moi le tien !","tgt":"Còn bạn, kể cho tôi nghe đi!"}]},{"title":"Partager une bonne nouvelle","phrases":[{"fr":"J'ai une bonne nouvelle pour toi !","tgt":"Tôi có tin vui muốn báo với bạn!"},{"fr":"Vas-y, je t'écoute.","tgt":"Nói đi, tôi đang nghe đây."},{"fr":"Ma petite sœur se marie ce printemps.","tgt":"Mùa xuân này em gái tôi lấy chồng."},{"fr":"Félicitations, c'est formidable !","tgt":"Chúc mừng nhé, tuyệt quá!"},{"fr":"Le mariage aura lieu à Hội An.","tgt":"Đám cưới sẽ tổ chức ở Hội An."},{"fr":"Toute ma famille va venir de France.","tgt":"Cả nhà tôi sẽ từ Pháp sang."},{"fr":"Et bien sûr, toi aussi, tu es invité !","tgt":"Và tất nhiên là bạn cũng được mời!"},{"fr":"Je suis tellement content pour elle.","tgt":"Tôi mừng cho em ấy quá."},{"fr":"Ils se sont rencontrés ici l'an dernier.","tgt":"Hai người quen nhau ở đây từ năm ngoái."},{"fr":"Quelle belle histoire d'amour !","tgt":"Chuyện tình đẹp quá!"}]},{"title":"Une soirée au bord de la rivière","phrases":[{"fr":"Ce soir, on se retrouve au bord de la rivière Thu Bồn.","tgt":"Tối nay mình gặp nhau ở bờ sông Thu Bồn nhé."},{"fr":"Il fait plus frais près de l'eau.","tgt":"Gần sông mát hơn."},{"fr":"Quelqu'un a apporté une guitare.","tgt":"Có người mang theo đàn ghi-ta."},{"fr":"Tu connais cette chanson ?","tgt":"Bạn có biết bài hát này không?"},{"fr":"Allez, on chante tous ensemble !","tgt":"Mọi người cùng hát nào!"},{"fr":"Les petites barques glissent doucement devant nous.","tgt":"Những chiếc thuyền nhỏ lướt nhẹ qua trước mặt mình."},{"fr":"Passe-moi les cacahuètes grillées, s'il te plaît.","tgt":"Đưa giúp tôi đĩa lạc rang với."},{"fr":"On s'amusait tellement qu'on n'a pas vu l'heure passer.","tgt":"Vui quá nên chẳng ai để ý giờ giấc."},{"fr":"Il est déjà minuit, il faut rentrer.","tgt":"Đã nửa đêm rồi, phải về thôi."},{"fr":"On remet ça la semaine prochaine ?","tgt":"Tuần sau mình lại tụ tập nữa nhé?"}]},{"title":"Les nouvelles du quartier","phrases":[{"fr":"J'ai entendu dire que la boulangerie du coin allait fermer.","tgt":"Nghe nói tiệm bánh mì đầu ngõ sắp đóng cửa."},{"fr":"Ah bon ? Qui t'a dit ça ?","tgt":"Thế à? Ai bảo bạn thế?"},{"fr":"Il paraît que le patron part s'installer à Saïgon.","tgt":"Nghe nói ông chủ sắp chuyển vào Sài Gòn sống."},{"fr":"J'ai entendu dire qu'un nouveau café allait ouvrir près du marché.","tgt":"Nghe nói sắp có quán cà phê mới mở gần chợ."},{"fr":"On dit que leur café à la noix de coco est délicieux.","tgt":"Nghe nói cà phê dừa ở đó ngon lắm."},{"fr":"Tu as entendu parler du festival de musique ?","tgt":"Bạn đã nghe nói về lễ hội âm nhạc chưa?"},{"fr":"Il paraît que cette année, il aura lieu sur la plage.","tgt":"Nghe nói năm nay tổ chức trên bãi biển."},{"fr":"Je ne sais pas si c'est vrai.","tgt":"Tôi không biết có đúng không."},{"fr":"C'est ma voisine qui me l'a dit, elle sait tout.","tgt":"Tôi nghe bà hàng xóm kể, bà ấy cái gì cũng biết."},{"fr":"Il vaut mieux vérifier avant d'y croire.","tgt":"Phải kiểm tra lại rồi hãy tin."}],"tip":{"title":"« Nghe nói » : j'ai entendu dire que","example":"J'ai entendu dire que la boulangerie du coin allait fermer. — <b>Nghe nói</b> tiệm bánh mì đầu ngõ sắp đóng cửa.","body":"« Nghe nói » se compose de « nghe », entendre, et « nói », dire : c'est exactement notre « j'ai entendu dire ». On le place en tête de phrase, souvent sans sujet, et il sert aussi pour « il paraît que » ou « on dit que ». Dans l'exemple, mot à mot : entendre dire, boutique de pain, au bout de la ruelle, bientôt, fermer la porte. On peut préciser la source, avec « tôi nghe nói », moi j'ai entendu dire, ou « tôi nghe bà hàng xóm kể », je l'ai entendu raconter par la voisine. Pour demander si quelqu'un est au courant, on dit « bạn đã nghe nói chưa », tu en as entendu parler ? Astuce : c'est le mot idéal pour partager une nouvelle sans en prendre la responsabilité.","lit":"entendre · dire · boutique · pain · tête · ruelle · [futur proche] · fermer · porte","say":{"Nghe nói":"Nghe nói","nghe":"nghe","nói":"nói","tôi nghe nói":"tôi nghe nói","tôi nghe bà hàng xóm kể":"tôi nghe bà hàng xóm kể","bạn đã nghe nói chưa":"bạn đã nghe nói chưa"}}},{"title":"Préparer la fête de la mi-automne","phrases":[{"fr":"La fête de la mi-automne approche.","tgt":"Sắp đến Tết Trung thu rồi."},{"fr":"C'est surtout la fête des enfants.","tgt":"Đây chủ yếu là ngày hội của trẻ em."},{"fr":"Les enfants défilent dans les rues avec des lanternes.","tgt":"Trẻ em rước đèn đi khắp phố."},{"fr":"On achète des gâteaux de lune pour toute la famille.","tgt":"Mình mua bánh trung thu cho cả nhà."},{"fr":"Tu préfères ceux aux haricots mungo ou ceux au sésame noir ?","tgt":"Bạn thích bánh nhân đậu xanh hay nhân vừng đen?"},{"fr":"Les gâteaux de lune sont souvent offerts aux amis.","tgt":"Bánh trung thu thường được tặng cho bạn bè."},{"fr":"Il y aura une danse du lion ce soir.","tgt":"Tối nay sẽ có múa lân."},{"fr":"On entend les tambours de loin.","tgt":"Từ xa đã nghe thấy tiếng trống."},{"fr":"Cette nuit, la lune est particulièrement ronde et brillante.","tgt":"Đêm nay trăng tròn và sáng lạ thường."},{"fr":"Allons nous asseoir dans la cour pour la regarder ensemble.","tgt":"Mình ra sân ngồi ngắm trăng cùng nhau nhé."}]},{"title":"Faire deux choses à la fois","phrases":[{"fr":"On dîne en regardant la rivière ?","tgt":"Mình vừa ăn tối vừa ngắm sông nhé?"},{"fr":"Il parle en mangeant, c'est drôle.","tgt":"Anh ấy vừa ăn vừa nói, buồn cười lắm."},{"fr":"Ce restaurant est à la fois bon et pas cher.","tgt":"Quán này vừa ngon vừa rẻ."},{"fr":"Elle chante en jouant de la guitare.","tgt":"Cô ấy vừa đàn vừa hát."},{"fr":"Je marche en écoutant de la musique.","tgt":"Tôi vừa đi bộ vừa nghe nhạc."},{"fr":"Ne téléphone pas en conduisant ton scooter !","tgt":"Đừng vừa lái xe máy vừa gọi điện thoại!"},{"fr":"Cette chemise est à la fois élégante et confortable.","tgt":"Chiếc áo này vừa đẹp vừa thoải mái."},{"fr":"Je suis à la fois fatigué et heureux.","tgt":"Tôi vừa mệt vừa vui."},{"fr":"Les gens d'ici sont à la fois accueillants et drôles.","tgt":"Người ở đây vừa hiếu khách vừa vui tính."},{"fr":"Je viens juste d'arriver, attends-moi une minute.","tgt":"Tôi vừa mới đến, đợi tôi một phút nhé."}],"tip":{"title":"« Vừa… vừa… » : faire deux choses à la fois","example":"Ce restaurant est à la fois bon et pas cher. — Quán này <b>vừa</b> ngon <b>vừa</b> rẻ.","body":"« Vừa… vừa… » se place devant deux verbes ou deux adjectifs pour dire que deux choses se passent en même temps. Avec des verbes, c'est notre « en faisant » : « vừa ăn vừa nói », manger et parler à la fois. Avec des adjectifs, c'est « à la fois… et… » : dans l'exemple, mot à mot, restaurant, ce, à la fois bon, à la fois bon marché. On l'entend partout pour vanter une adresse, et « vừa ngon vừa rẻ », bon et pas cher, est presque une formule toute faite. Attention, un seul « vừa » devant un verbe veut dire tout autre chose : venir juste de, comme dans « tôi vừa mới đến », je viens d'arriver. Astuce : imaginez un balancier, un « vừa » de chaque côté.","lit":"restaurant · ce · à la fois · bon · à la fois · bon marché","say":{"Vừa… vừa…":"Vừa… vừa…","vừa ăn vừa nói":"vừa ăn vừa nói","vừa ngon vừa rẻ":"vừa ngon vừa rẻ","vừa":"vừa","tôi vừa mới đến":"tôi vừa mới đến"}}},{"title":"Un souvenir d'enfance","phrases":[{"fr":"Quand j'étais petit, je passais tous mes étés chez mes grands-parents.","tgt":"Hồi nhỏ, mùa hè nào tôi cũng về nhà ông bà."},{"fr":"Ils habitaient dans un village près de Hội An.","tgt":"Ông bà sống ở một làng gần Hội An."},{"fr":"Ma grand-mère faisait le meilleur riz gluant du monde.","tgt":"Bà tôi nấu xôi ngon nhất trên đời."},{"fr":"Avec mon cousin, on allait souvent pêcher dans la rivière.","tgt":"Tôi với em họ hay đi câu cá ở sông."},{"fr":"On n'avait pas de télévision, mais on ne s'ennuyait jamais.","tgt":"Hồi đó không có ti vi, nhưng chẳng bao giờ thấy chán."},{"fr":"Le soir, mon grand-père nous racontait des histoires.","tgt":"Buổi tối, ông kể chuyện cho chúng tôi nghe."},{"fr":"Je me souviens encore de l'odeur des rizières.","tgt":"Tôi vẫn còn nhớ mùi đồng lúa."},{"fr":"Ce village a beaucoup changé depuis.","tgt":"Từ đó đến nay, làng đã thay đổi nhiều."},{"fr":"J'espère y retourner un jour.","tgt":"Tôi mong một ngày nào đó được quay lại đó."},{"fr":"Repenser à tout ça me rend un peu nostalgique.","tgt":"Nhớ lại những chuyện đó, tôi thấy hơi bồi hồi."}]},{"title":"Parler de ses projets","phrases":[{"fr":"Tu as quels projets pour l'an prochain ?","tgt":"Năm sau bạn định làm gì?"},{"fr":"Je voudrais ouvrir un petit café à Hội An.","tgt":"Tôi muốn mở một quán cà phê nhỏ ở Hội An."},{"fr":"C'est un rêve que j'ai depuis longtemps.","tgt":"Đó là ước mơ của tôi từ lâu rồi."},{"fr":"Si je trouve un bon local, je me lance.","tgt":"Nếu tìm được chỗ tốt thì tôi sẽ bắt đầu luôn."},{"fr":"Il faudra d'abord mettre un peu d'argent de côté.","tgt":"Trước hết phải tiết kiệm một ít tiền đã."},{"fr":"Mon amie Thảo va m'aider pour la décoration.","tgt":"Bạn tôi là Thảo sẽ giúp tôi trang trí."},{"fr":"Tu as déjà trouvé un nom ?","tgt":"Bạn đã chọn được tên chưa?"},{"fr":"Pas encore, j'hésite entre plusieurs idées.","tgt":"Chưa, tôi còn đang phân vân giữa mấy ý."},{"fr":"En tout cas, je serai ton premier client !","tgt":"Dù sao thì tôi sẽ là khách đầu tiên của bạn!"},{"fr":"Je te souhaite de réussir ce projet.","tgt":"Chúc bạn thành công với dự định này."}]},{"title":"Inviter et décliner","phrases":[{"fr":"Tu as un moment samedi soir ?","tgt":"Tối thứ bảy bạn có rảnh không?"},{"fr":"Je fête mon anniversaire chez moi.","tgt":"Tôi tổ chức sinh nhật ở nhà."},{"fr":"J'aimerais beaucoup que tu viennes.","tgt":"Tôi rất mong bạn đến."},{"fr":"Dommage, j'ai déjà un rendez-vous ce soir-là.","tgt":"Tiếc quá, tối hôm đó tôi có hẹn rồi."},{"fr":"Tant pis, ce sera pour une autre fois.","tgt":"Tiếc thật, để dịp khác vậy."},{"fr":"Et dimanche midi, ça t'irait ?","tgt":"Thế trưa chủ nhật thì sao?"},{"fr":"Oui, dimanche, je suis libre.","tgt":"Được, chủ nhật thì tôi rảnh."},{"fr":"Tu veux que j'apporte quelque chose ?","tgt":"Bạn có muốn tôi mang gì đến không?"},{"fr":"Non, viens simplement les mains vides !","tgt":"Không cần đâu, cứ đến tay không là được!"},{"fr":"Merci pour l'invitation, à dimanche alors.","tgt":"Cảm ơn đã mời nhé, hẹn chủ nhật gặp lại."}]},{"title":"Chez les parents d'un ami","phrases":[{"fr":"Bonjour madame, je suis un ami de Tuấn.","tgt":"Cháu chào bác ạ, cháu là bạn của Tuấn."},{"fr":"Entre, mon petit, fais comme chez toi.","tgt":"Vào nhà đi cháu, cứ tự nhiên nhé."},{"fr":"Je vous remercie beaucoup, madame.","tgt":"Cháu cảm ơn bác nhiều ạ."},{"fr":"Tu as déjà mangé, mon petit ?","tgt":"Cháu ăn cơm chưa?"},{"fr":"Oui, j'ai déjà mangé.","tgt":"Dạ, cháu ăn rồi ạ."},{"fr":"Tu restes encore longtemps à Hội An ?","tgt":"Cháu còn ở Hội An lâu không?"},{"fr":"Oui, encore deux semaines, madame.","tgt":"Vâng, cháu ở thêm hai tuần nữa ạ."},{"fr":"Prends une tasse de thé.","tgt":"Uống chén trà đi cháu."},{"fr":"Je vous en prie, servez-vous d'abord.","tgt":"Dạ, mời bác uống trước ạ."},{"fr":"Je vais devoir y aller, au revoir à vous deux.","tgt":"Cháu xin phép về ạ, cháu chào hai bác ạ."}],"tip":{"title":"Les formules de politesse : « ạ », « dạ », « vâng »","example":"Oui, j'ai déjà mangé. — <b>Dạ</b>, cháu ăn rồi <b>ạ</b>.","body":"Avec une personne plus âgée, le vietnamien ajoute de petits mots de respect qui ne se traduisent pas, mais qui changent tout. « Ạ », placé tout à la fin de la phrase, la rend polie : « cảm ơn bác ạ », merci à vous. « Dạ » est un oui respectueux, et on le dit aussi pour répondre quand un aîné vous appelle, un peu comme « oui, je vous écoute ». « Vâng » veut dire oui, d'accord, sur un ton poli ; entre amis, on dit plutôt « ừ », plus relâché. Dans l'exemple, mot à mot : oui poli, moi le neveu, manger, déjà, marque de respect. Astuce : avec les aînés, commencez par « dạ » et finissez par « ạ », votre phrase sera ainsi encadrée de politesse.","lit":"[oui poli] · moi (neveu) · manger · [accompli] · [politesse]","say":{"ạ":"ạ","dạ":"dạ","vâng":"vâng","Ạ":"Ạ","cảm ơn bác ạ":"cảm ơn bác ạ","Dạ":"Dạ","Vâng":"Vâng","ừ":"ừ"}}},{"title":"Se dire au revoir","phrases":[{"fr":"Le temps est passé si vite ici.","tgt":"Thời gian ở đây trôi nhanh quá."},{"fr":"Je pars demain matin pour Huế.","tgt":"Sáng mai tôi đi Huế."},{"fr":"Tu vas beaucoup me manquer.","tgt":"Tôi sẽ nhớ bạn lắm."},{"fr":"Moi aussi, j'étais vraiment content de te revoir.","tgt":"Tôi cũng vậy, gặp lại bạn vui thật."},{"fr":"Promets-moi de revenir bientôt.","tgt":"Hứa với tôi là sẽ sớm quay lại nhé."},{"fr":"On restera en contact par message.","tgt":"Mình sẽ giữ liên lạc qua tin nhắn."},{"fr":"Envoie-moi les photos de la soirée.","tgt":"Gửi cho tôi ảnh buổi tối hôm đó nhé."},{"fr":"Si tu viens en France, tu dormiras chez moi.","tgt":"Nếu bạn sang Pháp thì cứ ở nhà tôi."},{"fr":"Bon voyage, et prends soin de toi.","tgt":"Chúc bạn lên đường bình an, giữ gìn sức khỏe nhé."},{"fr":"Allez, à une prochaine fois !","tgt":"Thôi, hẹn lần sau gặp lại nhé!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à bavarder entre amis en vietnamien.","tgt":"Phần này đã giúp chúng ta biết trò chuyện với bạn bè bằng tiếng Việt."},{"fr":"On sait maintenant donner son avis et raconter une histoire.","tgt":"Bây giờ chúng ta đã biết nêu ý kiến và kể chuyện."},{"fr":"On sait passer du ton familier au ton poli.","tgt":"Chúng ta biết chuyển từ cách nói thân mật sang cách nói lễ phép."},{"fr":"« Cậu » et « tớ » pour les amis, « ạ » pour les aînés.","tgt":"\"Cậu\" và \"tớ\" với bạn bè, \"ạ\" với người lớn tuổi."},{"fr":"Hội An restera un beau souvenir de ce voyage.","tgt":"Hội An sẽ là một kỷ niệm đẹp của chuyến đi này."},{"fr":"Voilà, le deuxième niveau de vietnamien est terminé.","tgt":"Thế là chúng ta đã xong cấp độ hai tiếng Việt."},{"fr":"Au prochain niveau, on découvrira le registre soutenu.","tgt":"Ở cấp độ tới, chúng ta sẽ học cách nói trang trọng."},{"fr":"On apprendra aussi quelques expressions vietnamiennes imagées.","tgt":"Chúng ta cũng sẽ học một số thành ngữ tiếng Việt."},{"fr":"Bravo, vous avez été très persévérants !","tgt":"Các bạn đã rất kiên trì, giỏi lắm!"},{"fr":"À bientôt pour le troisième niveau.","tgt":"Hẹn gặp lại ở cấp độ ba nhé."}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée au Viêt Nam, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Premier jour dans un bureau de Saïgon","phrases":[{"fr":"Ce projet est dirigé par une collègue très expérimentée.","tgt":"Dự án này do một chị đồng nghiệp rất giàu kinh nghiệm phụ trách."},{"fr":"Le retard de ce matin est dû aux embouteillages.","tgt":"Sự chậm trễ sáng nay là do tắc đường."},{"fr":"Ce bureau a été décoré par toute l'équipe.","tgt":"Văn phòng này do cả nhóm cùng trang trí."},{"fr":"Mon badge sera préparé par le service du personnel.","tgt":"Thẻ ra vào của tôi sẽ do phòng nhân sự chuẩn bị."},{"fr":"Je suis arrivé en retard parce qu'une grosse averse est tombée d'un coup.","tgt":"Tôi đến muộn bởi vì trời bỗng đổ mưa to."},{"fr":"Qui est chargé de me former au logiciel interne ?","tgt":"Việc hướng dẫn phần mềm nội bộ do ai phụ trách ạ?"},{"fr":"Tout le monde a été captivé par son exposé.","tgt":"Ai cũng bị cuốn hút bởi bài thuyết trình của chị ấy."},{"fr":"Cette décision a été prise par le directeur en personne.","tgt":"Quyết định này do chính giám đốc đưa ra."},{"fr":"Je me sens un peu perdu, car tout est nouveau pour moi.","tgt":"Tôi thấy hơi bỡ ngỡ, bởi vì mọi thứ đều mới mẻ với tôi."},{"fr":"Heureusement, l'ambiance de l'équipe est très chaleureuse.","tgt":"May mà không khí trong nhóm rất thân thiện."}],"tip":{"title":"« Do » et « bởi » : par qui, à cause de quoi","example":"Cette décision a été prise par le directeur en personne. — Quyết định này <b>do</b> chính giám đốc đưa ra.","body":"Pour dire qui est responsable d'une action, le vietnamien place « do » juste avant la personne, puis le verbe : « quyết định này do giám đốc đưa ra », mot à mot « décision ce, par directeur, prendre ». C'est un peu comme notre « c'est le directeur qui a pris cette décision » : on insiste sur le responsable. Le même petit mot sert aussi pour la cause, avec « là do », c'est dû à : « là do tắc đường », c'est à cause des bouchons. « Bởi » a un sens proche, mais à l'oral on l'entend surtout dans « bởi vì », parce que, ou après un verbe passif comme « bị cuốn hút bởi », être captivé par. Pour retenir : « do » désigne celui qui s'en charge, « bởi vì » donne la raison.","lit":"décision · ce · par · en personne · directeur · prendre (litt. avancer)","say":{"Do":"Do","bởi":"bởi","do":"do","quyết định này do giám đốc đưa ra":"quyết định này do giám đốc đưa ra","là do":"là do","là do tắc đường":"là do tắc đường","Bởi":"Bởi","bởi vì":"bởi vì","bị cuốn hút bởi":"bị cuốn hút bởi"}}},{"title":"Les collègues de l'équipe","phrases":[{"fr":"Anh Minh est notre chef d'équipe, il a la quarantaine.","tgt":"Anh Minh là trưởng nhóm của chúng tôi, khoảng bốn mươi tuổi."},{"fr":"Au bureau, j'appelle les collègues plus âgés « grand frère » ou « grande sœur ».","tgt":"Ở văn phòng, tôi gọi các đồng nghiệp lớn tuổi hơn là anh hoặc chị."},{"fr":"La nouvelle stagiaire est plus jeune que moi, alors je l'appelle « em ».","tgt":"Bạn thực tập sinh mới trẻ hơn tôi, nên tôi gọi là em."},{"fr":"Chị Lan connaît absolument tout le monde dans l'entreprise.","tgt":"Chị Lan quen biết hết mọi người trong công ty."},{"fr":"Mon voisin de bureau m'aide souvent avec les tableaux de chiffres.","tgt":"Anh ngồi bàn bên cạnh hay giúp tôi làm bảng tính."},{"fr":"Elle est sérieuse au travail mais très drôle pendant les pauses.","tgt":"Chị ấy làm việc nghiêm túc nhưng giờ nghỉ thì rất vui tính."},{"fr":"Cela fait déjà trois mois que nous travaillons ensemble.","tgt":"Chúng tôi làm việc cùng nhau được ba tháng rồi."},{"fr":"Il ne faut jamais hausser le ton devant un collègue.","tgt":"Không bao giờ nên to tiếng với đồng nghiệp."},{"fr":"Un arbre seul ne fait pas une colline, mais trois arbres réunis forment une haute montagne.","tgt":"Một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao."},{"fr":"J'ai déjà l'impression de faire vraiment partie de l'équipe.","tgt":"Tôi đã cảm thấy mình thật sự là một thành viên của nhóm."}]},{"title":"La réunion du lundi matin","phrases":[{"fr":"Le chef nous oblige à être là à huit heures pile.","tgt":"Sếp bắt chúng tôi phải có mặt lúc tám giờ đúng."},{"fr":"Laissez-moi présenter les chiffres de ce mois-ci.","tgt":"Để tôi trình bày số liệu của tháng này."},{"fr":"Ne me fais pas attendre, la réunion a déjà commencé.","tgt":"Đừng bắt tôi phải chờ, cuộc họp bắt đầu rồi."},{"fr":"Laissons-la terminer avant de poser nos questions.","tgt":"Hãy để chị ấy nói hết rồi hẵng đặt câu hỏi."},{"fr":"Le directeur nous a fait refaire tout le rapport.","tgt":"Giám đốc bắt chúng tôi làm lại toàn bộ báo cáo."},{"fr":"Ne le laisse pas s'occuper seul de ce dossier.","tgt":"Đừng để anh ấy một mình lo hồ sơ này."},{"fr":"On m'a fait prendre le compte rendu pendant deux heures.","tgt":"Họ bắt tôi ghi biên bản suốt hai tiếng."},{"fr":"Laisse-moi encore réfléchir un petit peu.","tgt":"Để tôi suy nghĩ thêm một chút."},{"fr":"La réunion a duré bien plus longtemps que prévu.","tgt":"Cuộc họp kéo dài hơn dự kiến nhiều."},{"fr":"Personne n'aime les réunions qui traînent en longueur.","tgt":"Chẳng ai thích những cuộc họp dài lê thê."}],"tip":{"title":"Faire faire : « bắt » et « để »","example":"Le directeur nous a fait refaire tout le rapport. — Giám đốc <b>bắt</b> chúng tôi làm lại toàn bộ báo cáo.","body":"Le vietnamien n'a pas de « faire faire » tout prêt : il choisit un verbe selon qu'on impose ou qu'on permet. « Bắt », qui veut dire aussi attraper, sert quand on oblige quelqu'un : « giám đốc bắt chúng tôi làm lại báo cáo », mot à mot « directeur forcer nous faire de nouveau rapport ». « Để », au contraire, veut dire laisser : « để tôi trình bày », laissez-moi présenter, ou « đừng để anh ấy một mình », ne le laisse pas seul. La construction est toujours la même : le verbe, la personne, puis l'action, sans aucune préposition. Pour retenir, pensez qu'on attrape quelqu'un avec « bắt » pour le forcer, et qu'on le laisse filer avec « để ».","lit":"directeur · forcer · nous · faire · de nouveau · tout · rapport","say":{"bắt":"bắt","để":"để","Bắt":"Bắt","giám đốc bắt chúng tôi làm lại báo cáo":"giám đốc bắt chúng tôi làm lại báo cáo","Để":"Để","để tôi trình bày":"để tôi trình bày","đừng để anh ấy một mình":"đừng để anh ấy một mình"}}},{"title":"La pause cơm tấm","phrases":[{"fr":"À midi, on descend manger un cơm tấm au bout de la rue.","tgt":"Buổi trưa, chúng tôi xuống ăn cơm tấm ở đầu phố."},{"fr":"Le riz brisé est servi avec une côte de porc grillée et un œuf au plat.","tgt":"Cơm tấm được ăn kèm sườn nướng và trứng ốp la."},{"fr":"Je demande toujours un peu plus de sauce aigre-douce.","tgt":"Tôi lúc nào cũng xin thêm chút nước mắm chua ngọt."},{"fr":"La vendeuse se souvient déjà de ce que je prends d'habitude.","tgt":"Cô bán hàng đã nhớ tôi hay gọi món gì."},{"fr":"Une assiette coûte à peu près quarante mille dongs.","tgt":"Một đĩa cơm khoảng bốn mươi nghìn đồng."},{"fr":"On mange vite, assis sur de petits tabourets en plastique.","tgt":"Chúng tôi ăn nhanh, ngồi trên những chiếc ghế nhựa thấp."},{"fr":"Après le repas, beaucoup font une courte sieste à leur bureau.","tgt":"Ăn xong, nhiều người chợp mắt một lát ngay tại bàn làm việc."},{"fr":"Un café glacé m'aide à rester éveillé tout l'après-midi.","tgt":"Một cốc cà phê đá giúp tôi tỉnh táo suốt buổi chiều."},{"fr":"C'est pendant la pause qu'on apprend les vraies nouvelles du bureau.","tgt":"Chính trong giờ nghỉ trưa mới nghe được đủ thứ chuyện ở cơ quan."},{"fr":"Ce petit rituel de midi me manquerait énormément.","tgt":"Nếu không có giờ nghỉ trưa này chắc tôi nhớ lắm."}]},{"title":"Les embouteillages de scooters","phrases":[{"fr":"Il suffit d'une petite pluie pour que toute la ville soit bloquée.","tgt":"Chỉ cần một cơn mưa nhỏ là cả thành phố tắc nghẽn."},{"fr":"La route n'est dégagée que si l'on part avant sept heures.","tgt":"Chỉ khi xuất phát trước bảy giờ thì đường mới thông thoáng."},{"fr":"Il suffit de rater un feu pour perdre dix minutes.","tgt":"Chỉ cần lỡ một cái đèn đỏ là mất mười phút."},{"fr":"Je ne prends le scooter que s'il ne pleut pas.","tgt":"Chỉ khi trời không mưa tôi mới đi xe máy."},{"fr":"Aux heures de pointe, les scooters montent carrément sur les trottoirs.","tgt":"Giờ cao điểm, xe máy leo cả lên vỉa hè."},{"fr":"Il suffit de porter un masque pour être moins gêné par la poussière.","tgt":"Chỉ cần đeo khẩu trang là đỡ bụi hơn nhiều."},{"fr":"On ne comprend vraiment cette ville qu'après l'avoir traversée en scooter.","tgt":"Chỉ khi đã đi xe máy khắp thành phố, người ta mới thực sự hiểu nơi này."},{"fr":"Le casque est obligatoire, même pour un tout petit trajet.","tgt":"Đội mũ bảo hiểm là bắt buộc, kể cả khi đi một đoạn rất ngắn."},{"fr":"Il faut garder son calme et klaxonner doucement.","tgt":"Phải giữ bình tĩnh và bấm còi nhẹ nhàng thôi."},{"fr":"Petit à petit, je me suis habitué à ce joyeux chaos.","tgt":"Dần dần, tôi cũng quen với cảnh hỗn loạn vui vẻ này."}],"tip":{"title":"« Chỉ cần… là… » et « chỉ khi… mới… » : il suffit que, seulement si","example":"Il suffit d'une petite pluie pour que toute la ville soit bloquée. — <b>Chỉ cần</b> một cơn mưa nhỏ <b>là</b> cả thành phố tắc nghẽn.","body":"Ces deux paires fonctionnent comme des pinces qui encadrent la phrase. « Chỉ cần », il suffit de, pose la petite condition, et « là » introduit la conséquence presque automatique : « chỉ cần một cơn mưa là cả thành phố tắc », mot à mot « seulement besoin une pluie, alors toute la ville bouchée ». « Chỉ khi… mới… » dit au contraire que c'est la seule condition possible, comme notre « ce n'est que si… que… » : « chỉ khi trời không mưa tôi mới đi xe máy », je ne prends le scooter que s'il ne pleut pas. À l'oral, on appuie un peu sur « là » et sur « mới », qui portent le sens. Pour retenir : « là » ouvre grand la porte, « mới » ne l'ouvre qu'à une seule condition.","lit":"seulement · avoir besoin · un · [classificateur] (cơn) · pluie · petit · alors · toute · ville · bouchée","say":{"Chỉ cần… là…":"Chỉ cần… là…","chỉ khi… mới…":"chỉ khi… mới…","Chỉ cần":"Chỉ cần","là":"là","chỉ cần một cơn mưa là cả thành phố tắc":"chỉ cần một cơn mưa là cả thành phố tắc","Chỉ khi… mới…":"Chỉ khi… mới…","chỉ khi trời không mưa tôi mới đi xe máy":"chỉ khi trời không mưa tôi mới đi xe máy","mới":"mới"}}},{"title":"Chercher un appartement","phrases":[{"fr":"Je cherche un petit appartement pas trop loin de mon travail.","tgt":"Tôi đang tìm một căn hộ nhỏ không quá xa chỗ làm."},{"fr":"Les loyers ont beaucoup grimpé dans le centre-ville.","tgt":"Giá thuê nhà ở trung tâm đã tăng lên nhiều."},{"fr":"Cet appartement a un balcon qui donne sur la rivière.","tgt":"Căn hộ này có ban công nhìn ra sông."},{"fr":"Est-ce que l'eau et l'électricité sont comprises dans le loyer ?","tgt":"Tiền thuê đã bao gồm điện nước chưa ạ?"},{"fr":"Il faut verser deux mois de caution à l'avance.","tgt":"Phải đặt cọc trước hai tháng tiền nhà."},{"fr":"L'agent immobilier m'a fait visiter cinq logements en une matinée.","tgt":"Người môi giới dẫn tôi đi xem năm chỗ trong một buổi sáng."},{"fr":"Ce quartier est animé le jour mais tranquille la nuit.","tgt":"Khu này ban ngày nhộn nhịp nhưng ban đêm yên tĩnh."},{"fr":"Je préfère vivre au fond d'une ruelle, loin du bruit.","tgt":"Tôi thích ở trong ngõ hơn, tránh xa tiếng ồn."},{"fr":"Est-ce que je pourrais revenir le visiter ce week-end ?","tgt":"Cuối tuần này tôi có thể đến xem lại được không?"},{"fr":"On dit qu'il faut d'abord un toit stable pour bien réussir dans son travail.","tgt":"Người ta nói an cư rồi mới lạc nghiệp."}]},{"title":"Le bail et la propriétaire","phrases":[{"fr":"La propriétaire habite au rez-de-chaussée de l'immeuble.","tgt":"Bà chủ nhà sống ở tầng một."},{"fr":"Nous avons signé un contrat de location d'un an.","tgt":"Chúng tôi đã ký hợp đồng thuê nhà một năm."},{"fr":"Je dois déclarer mon lieu de résidence au commissariat du quartier.","tgt":"Tôi phải khai báo tạm trú với công an phường."},{"fr":"Le loyer se règle au début de chaque mois.","tgt":"Tiền nhà trả vào đầu mỗi tháng."},{"fr":"Le portail de la maison est fermé à vingt-trois heures.","tgt":"Cổng nhà đóng lúc mười một giờ đêm."},{"fr":"Si quelque chose est cassé, je dois prévenir tout de suite.","tgt":"Nếu có gì hỏng, tôi phải báo ngay."},{"fr":"La propriétaire m'a apporté une assiette de fruits.","tgt":"Bà chủ nhà mang sang cho tôi một đĩa hoa quả."},{"fr":"Elle me rappelle gentiment de ne pas faire de bruit tard le soir.","tgt":"Bà nhắc khéo tôi đừng làm ồn khi đã khuya."},{"fr":"Je m'entends très bien avec mes voisins de palier.","tgt":"Tôi rất hợp với hàng xóm cùng tầng."},{"fr":"Mieux vaut un voisin proche qu'un frère éloigné.","tgt":"Bán anh em xa, mua láng giềng gần."}]},{"title":"Les démarches du quotidien","phrases":[{"fr":"Même pour ouvrir un compte en banque, il faut une montagne de papiers.","tgt":"Ngay cả mở tài khoản ngân hàng cũng cần rất nhiều giấy tờ."},{"fr":"Même l'employé du guichet ne savait pas quel formulaire remplir.","tgt":"Ngay cả nhân viên quầy cũng không biết phải điền mẫu đơn nào."},{"fr":"Même le dimanche, certains bureaux restent ouverts.","tgt":"Ngay cả vào chủ nhật, một số nơi cũng vẫn mở cửa."},{"fr":"Je dois faire renouveler mon permis de travail.","tgt":"Tôi phải đi gia hạn giấy phép lao động."},{"fr":"On m'a demandé une copie certifiée de mon passeport.","tgt":"Họ yêu cầu tôi nộp bản sao công chứng hộ chiếu."},{"fr":"Même mes collègues vietnamiens trouvent cette démarche compliquée.","tgt":"Ngay cả đồng nghiệp người Việt cũng thấy thủ tục này rắc rối."},{"fr":"Le mieux, c'est d'arriver tôt pour prendre un numéro.","tgt":"Tốt nhất là đến sớm để lấy số."},{"fr":"Même avec un dossier complet, il faut parfois revenir deux fois.","tgt":"Ngay cả khi hồ sơ đầy đủ, đôi khi cũng phải quay lại hai lần."},{"fr":"Payer ses factures avec son téléphone est devenu très simple.","tgt":"Thanh toán hoá đơn bằng điện thoại giờ rất đơn giản."},{"fr":"Avec un peu de patience, tout finit par s'arranger.","tgt":"Kiên nhẫn một chút thì việc gì rồi cũng xong."}],"tip":{"title":"« Ngay cả… cũng… » : même","example":"Même mes collègues vietnamiens trouvent cette démarche compliquée. — <b>Ngay cả</b> đồng nghiệp người Việt <b>cũng</b> thấy thủ tục này rắc rối.","body":"Pour dire « même », le vietnamien utilise encore une paire : « ngay cả » se place devant l'élément surprenant, et « cũng », aussi, se met juste avant le verbe. « Ngay cả đồng nghiệp người Việt cũng thấy rắc rối », mot à mot « même collègue vietnamien aussi trouver compliqué ». En français, un seul mot suffit, mais en vietnamien, oublier « cũng » sonne vraiment bancal. On peut mettre presque tout après « ngay cả » : une personne, un moment comme « ngay cả chủ nhật », même le dimanche, ou une situation avec « ngay cả khi », même quand. Astuce : pensez « même lui, aussi » ; la paire se dit d'un seul souffle.","lit":"même · collègue · personne · Viêt · aussi · trouver · démarche · ce · compliqué","say":{"Ngay cả… cũng…":"Ngay cả… cũng…","ngay cả":"ngay cả","cũng":"cũng","Ngay cả đồng nghiệp người Việt cũng thấy rắc rối":"Ngay cả đồng nghiệp người Việt cũng thấy rắc rối","ngay cả chủ nhật":"ngay cả chủ nhật","ngay cả khi":"ngay cả khi"}}},{"title":"Une panne à la maison","phrases":[{"fr":"La climatisation est tombée en panne en pleine saison chaude.","tgt":"Điều hoà bị hỏng đúng giữa mùa nóng."},{"fr":"J'ai appelé un réparateur que ma voisine m'avait recommandé.","tgt":"Tôi đã gọi một thợ sửa do chị hàng xóm giới thiệu."},{"fr":"Il a promis de passer dans l'après-midi.","tgt":"Anh ấy hứa chiều nay sẽ qua."},{"fr":"Le disjoncteur saute dès qu'on allume la bouilloire.","tgt":"Hễ bật ấm đun nước là cầu dao lại nhảy."},{"fr":"Il faut changer une pièce, mais elle n'est pas en stock.","tgt":"Phải thay một linh kiện, nhưng hiện chưa có hàng."},{"fr":"La réparation m'a coûté cinq cent mille dongs.","tgt":"Sửa hết năm trăm nghìn đồng."},{"fr":"Il y a une fuite d'eau sous l'évier de la cuisine.","tgt":"Có chỗ rò nước dưới bồn rửa trong bếp."},{"fr":"Sans ventilateur, impossible de fermer l'œil de la nuit.","tgt":"Không có quạt thì đêm không tài nào ngủ được."},{"fr":"La propriétaire a accepté de payer la moitié des frais.","tgt":"Bà chủ nhà đồng ý trả một nửa chi phí."},{"fr":"Maintenant, tout marche de nouveau parfaitement.","tgt":"Giờ thì mọi thứ lại chạy ngon lành."}]},{"title":"Les courses après le travail","phrases":[{"fr":"En rentrant, je m'arrête au supermarché près de chez moi.","tgt":"Trên đường về, tôi ghé siêu thị gần nhà."},{"fr":"Le soir, les légumes sont souvent vendus moins cher.","tgt":"Buổi tối rau thường được bán rẻ hơn."},{"fr":"J'achète du riz, des œufs et un peu de porc.","tgt":"Tôi mua gạo, trứng và một ít thịt lợn."},{"fr":"Au marché, on peut encore marchander un peu.","tgt":"Ở chợ vẫn có thể mặc cả một chút."},{"fr":"Cette marchande me rajoute toujours quelques herbes aromatiques.","tgt":"Cô bán hàng này lúc nào cũng cho tôi thêm ít rau thơm."},{"fr":"J'essaie de ne pas prendre trop de sacs en plastique.","tgt":"Tôi cố gắng không dùng quá nhiều túi ni lông."},{"fr":"Les fruits de saison sont à la fois les meilleurs et les moins chers.","tgt":"Hoa quả theo mùa vừa ngon nhất vừa rẻ nhất."},{"fr":"C'est la saison des mangoustans, ma période préférée.","tgt":"Đang mùa măng cụt, đây là thời điểm tôi thích nhất."},{"fr":"En semaine, je cuisine rarement, je suis trop fatigué.","tgt":"Ngày thường tôi ít khi nấu ăn vì quá mệt."},{"fr":"Le dimanche, je prépare des plats pour plusieurs jours.","tgt":"Chủ nhật, tôi nấu sẵn đồ ăn cho mấy ngày."}]},{"title":"Les heures supplémentaires","phrases":[{"fr":"Cette semaine, je quitte rarement le bureau avant vingt heures.","tgt":"Tuần này hiếm khi tôi rời văn phòng trước tám giờ tối."},{"fr":"Le client attend le dossier pour vendredi matin.","tgt":"Khách hàng cần hồ sơ trước sáng thứ sáu."},{"fr":"Nous devons rattraper le retard du mois dernier.","tgt":"Chúng tôi phải bù lại phần chậm trễ của tháng trước."},{"fr":"Mon chef m'a demandé de rester une heure de plus.","tgt":"Sếp nhờ tôi ở lại thêm một tiếng nữa."},{"fr":"Les heures supplémentaires sont payées une fois et demie.","tgt":"Giờ làm thêm được trả gấp rưỡi."},{"fr":"Je suis épuisé, mais le projet avance bien.","tgt":"Tôi kiệt sức rồi, nhưng dự án đang tiến triển tốt."},{"fr":"On a commandé des nouilles pour toute l'équipe ce soir.","tgt":"Tối nay chúng tôi đặt mì cho cả nhóm."},{"fr":"Il ne faudrait pas que ça devienne une habitude.","tgt":"Không nên để chuyện này thành thói quen."},{"fr":"À force de limer le fer, on finit par en faire une aiguille.","tgt":"Có công mài sắt, có ngày nên kim."},{"fr":"Une fois le dossier rendu, je prendrai deux jours de congé.","tgt":"Nộp hồ sơ xong, tôi sẽ nghỉ phép hai ngày."}]},{"title":"Écrire à un client important","phrases":[{"fr":"Je dois écrire un courriel très formel à un nouveau client.","tgt":"Tôi phải viết một thư điện tử thật trang trọng cho khách hàng mới."},{"fr":"À l'attention de Monsieur Nam, directeur de la société.","tgt":"Kính gửi ông Nam, Giám đốc công ty."},{"fr":"Nous remercions sincèrement notre aimable clientèle de sa confiance.","tgt":"Chúng tôi xin chân thành cảm ơn sự tin tưởng của quý khách."},{"fr":"Nous avons l'honneur de vous adresser notre proposition.","tgt":"Chúng tôi trân trọng gửi tới quý công ty bản đề xuất của mình."},{"fr":"Veuillez trouver ci-joint le contrat signé.","tgt":"Xin gửi kèm theo đây bản hợp đồng đã ký."},{"fr":"Nous restons à votre entière disposition pour toute question.","tgt":"Chúng tôi luôn sẵn sàng giải đáp mọi thắc mắc của quý khách."},{"fr":"Mesdames et messieurs, la réunion va commencer.","tgt":"Kính thưa quý vị, cuộc họp xin được bắt đầu."},{"fr":"Nous vous prions de bien vouloir excuser ce retard de livraison.","tgt":"Rất mong quý khách thông cảm vì sự chậm trễ trong việc giao hàng."},{"fr":"Oui, je vous écoute, en quoi puis-je vous être utile ?","tgt":"Dạ, tôi xin nghe, tôi có thể giúp gì cho quý khách ạ?"},{"fr":"Je vous prie d'agréer mes salutations respectueuses.","tgt":"Trân trọng kính chào."}],"tip":{"title":"Le langage du bureau : « kính gửi », « quý khách », les formules formelles","example":"Nous remercions sincèrement notre aimable clientèle de sa confiance. — Chúng tôi xin chân thành cảm ơn sự tin tưởng của <b>quý khách</b>.","body":"Au travail, le vietnamien change de registre grâce à quelques petits mots de respect. « Kính », respectueusement, ouvre les lettres et les discours : « kính gửi », adressé avec respect, équivaut à notre « à l'attention de », et « kính thưa quý vị » à « mesdames et messieurs ». « Quý », précieux, se colle devant les personnes : « quý khách », l'honorable client, ou « quý công ty », votre honorable société, et remplace ainsi le simple « vous ». Pour parler de soi, on se fait au contraire tout petit avec « xin » : « chúng tôi xin cảm ơn », nous nous permettons de remercier. Au téléphone, commencez par « dạ », oui poliment, et terminez par « ạ ». Astuce : on élève l'autre avec « quý », on s'abaisse soi-même avec « xin ».","lit":"nous · [humble] (xin) · sincèrement · remercier · confiance · de · [honorable] (quý) · client","say":{"kính gửi":"kính gửi","quý khách":"quý khách","Kính":"Kính","kính thưa quý vị":"kính thưa quý vị","Quý":"Quý","quý công ty":"quý công ty","xin":"xin","chúng tôi xin cảm ơn":"chúng tôi xin cảm ơn","dạ":"dạ","ạ":"ạ","quý":"quý"}}},{"title":"Le télétravail un jour de pluie","phrases":[{"fr":"Les jours de très forte pluie, je travaille de chez moi.","tgt":"Hôm nào mưa to quá, tôi làm việc ở nhà."},{"fr":"La rue devant chez moi est complètement inondée.","tgt":"Con đường trước nhà tôi ngập hết rồi."},{"fr":"La connexion internet est très lente cet après-midi.","tgt":"Chiều nay mạng chậm quá."},{"fr":"Nous faisons la réunion en visioconférence.","tgt":"Chúng tôi họp trực tuyến."},{"fr":"Mon chat n'arrête pas de passer devant la caméra.","tgt":"Con mèo nhà tôi cứ đi qua đi lại trước camera."},{"fr":"Travailler en pyjama, c'est agréable, mais on devient vite paresseux.","tgt":"Làm việc trong bộ đồ ngủ thì dễ chịu, nhưng dễ sinh lười."},{"fr":"Je fais une petite pause toutes les deux heures.","tgt":"Cứ hai tiếng tôi lại nghỉ một lát."},{"fr":"Mes collègues me manquent un peu, je l'avoue.","tgt":"Phải nói thật là tôi hơi nhớ đồng nghiệp."},{"fr":"Ici, la pluie arrive vite, mais elle s'arrête tout aussi vite.","tgt":"Mưa ở đây đến nhanh mà tạnh cũng nhanh."},{"fr":"Demain, je retournerai au bureau si les rues sont sèches.","tgt":"Mai nếu đường khô ráo thì tôi sẽ quay lại văn phòng."}]},{"title":"Organiser sa semaine","phrases":[{"fr":"Je note tout dans un carnet pour ne rien oublier.","tgt":"Tôi ghi hết vào sổ để khỏi quên."},{"fr":"Le lundi, je fais le point sur mes priorités.","tgt":"Thứ hai, tôi xem lại những việc cần ưu tiên."},{"fr":"Le mercredi soir, je vais à la salle de sport.","tgt":"Tối thứ tư tôi đi tập ở phòng tập thể dục."},{"fr":"Je garde le jeudi soir pour étudier le vietnamien.","tgt":"Tôi dành tối thứ năm để học tiếng Việt."},{"fr":"Une aide ménagère vient nettoyer l'appartement une fois par semaine.","tgt":"Mỗi tuần một lần có người giúp việc đến dọn nhà."},{"fr":"J'apporte mon linge à la laverie au bout de la ruelle.","tgt":"Tôi mang quần áo ra tiệm giặt là đầu ngõ."},{"fr":"Il faut savoir refuser certaines invitations.","tgt":"Phải biết từ chối một số lời mời."},{"fr":"Je me réserve toujours une soirée rien que pour moi.","tgt":"Tôi luôn giữ một buổi tối cho riêng mình."},{"fr":"Le travail d'aujourd'hui ne doit pas attendre demain.","tgt":"Việc hôm nay chớ để ngày mai."},{"fr":"Une semaine bien organisée, c'est beaucoup moins de stress.","tgt":"Một tuần sắp xếp hợp lý thì đỡ căng thẳng hơn hẳn."}]},{"title":"Un dîner d'équipe","phrases":[{"fr":"Pour fêter le nouveau contrat, toute l'équipe sort dîner ce soir.","tgt":"Để mừng hợp đồng mới, tối nay cả nhóm đi ăn."},{"fr":"Nous avons réservé une table dans un restaurant de fruits de mer.","tgt":"Chúng tôi đã đặt bàn ở một quán hải sản."},{"fr":"Le chef lève son verre en l'honneur de toute l'équipe.","tgt":"Sếp nâng ly chúc mừng cả nhóm."},{"fr":"Tout le monde trinque en comptant jusqu'à trois.","tgt":"Mọi người cùng nâng ly, đếm một, hai, ba, dô!"},{"fr":"Il est poli de servir les autres avant de se servir soi-même.","tgt":"Gắp thức ăn cho người khác trước là phép lịch sự."},{"fr":"Je ne bois pas d'alcool, alors je prends un jus de coco.","tgt":"Tôi không uống rượu bia nên gọi nước dừa."},{"fr":"Les plus jeunes invitent les aînés à commencer le repas.","tgt":"Người trẻ mời người lớn tuổi ăn trước."},{"fr":"Le karaoké après le dîner est presque une tradition.","tgt":"Đi hát karaoke sau bữa tối gần như là một truyền thống."},{"fr":"Chacun a chanté au moins une chanson.","tgt":"Ai cũng hát ít nhất một bài."},{"fr":"Ces soirées rapprochent vraiment les collègues.","tgt":"Những buổi như thế này thật sự gắn kết đồng nghiệp."}]},{"title":"Se faire livrer à manger","phrases":[{"fr":"Le soir, je commande souvent à manger sur mon téléphone.","tgt":"Buổi tối tôi hay đặt đồ ăn qua điện thoại."},{"fr":"Le livreur arrive en moins de vingt minutes.","tgt":"Chưa đầy hai mươi phút là người giao hàng đã tới."},{"fr":"Il m'appelle quand il est devant l'immeuble.","tgt":"Anh ấy gọi cho tôi khi đến trước toà nhà."},{"fr":"Je descends chercher la commande, car il n'a pas le droit de monter.","tgt":"Tôi xuống lấy đồ vì anh ấy không được lên."},{"fr":"J'ai oublié de préciser « sans coriandre ».","tgt":"Tôi quên dặn là không cho rau mùi."},{"fr":"La soupe est arrivée encore toute chaude.","tgt":"Bát canh đến nơi vẫn còn nóng hổi."},{"fr":"Je laisse toujours un petit pourboire au livreur.","tgt":"Tôi luôn để lại chút tiền boa cho người giao hàng."},{"fr":"Se faire livrer, c'est pratique, mais ça revient plus cher.","tgt":"Đặt đồ ăn thì tiện, nhưng tốn tiền hơn."},{"fr":"Quand il pleut, les livraisons prennent beaucoup plus de temps.","tgt":"Trời mưa thì giao hàng lâu hơn nhiều."},{"fr":"Ce week-end, j'essaierai de cuisiner moi-même.","tgt":"Cuối tuần này tôi sẽ thử tự nấu."}]},{"title":"Un dimanche pour souffler","phrases":[{"fr":"Le dimanche matin, je fais la grasse matinée.","tgt":"Sáng chủ nhật tôi ngủ nướng."},{"fr":"Ensuite, je vais boire un café au lait glacé en terrasse.","tgt":"Sau đó tôi ra quán ngồi uống cà phê sữa đá."},{"fr":"J'aime regarder la ville se réveiller lentement.","tgt":"Tôi thích ngắm thành phố chậm rãi thức giấc."},{"fr":"L'après-midi, je me promène dans un parc ombragé.","tgt":"Buổi chiều tôi đi dạo trong một công viên rợp bóng cây."},{"fr":"Des personnes âgées y font de la gymnastique ensemble.","tgt":"Ở đó các cụ cùng nhau tập thể dục."},{"fr":"En fin de journée, j'appelle ma famille en France.","tgt":"Cuối ngày tôi gọi điện về Pháp cho gia đình."},{"fr":"Il faut bien faire attention au décalage horaire.","tgt":"Phải để ý chênh lệch múi giờ."},{"fr":"Ce jour-là, je ne réponds à aucun message du travail.","tgt":"Hôm đó tôi không trả lời tin nhắn công việc nào cả."},{"fr":"Le soir, je prépare mes affaires pour lundi.","tgt":"Buổi tối tôi chuẩn bị đồ cho ngày thứ hai."},{"fr":"Un vrai repos est essentiel pour tenir toute la semaine.","tgt":"Nghỉ ngơi thực sự là điều cần thiết để trụ được cả tuần."}]},{"title":"Garder l'équilibre dans une grande ville","phrases":[{"fr":"Vivre à Saïgon est passionnant, mais épuisant.","tgt":"Sống ở Sài Gòn thú vị nhưng rất mệt."},{"fr":"Le bruit ne s'arrête presque jamais, même la nuit.","tgt":"Tiếng ồn hầu như không bao giờ dứt, kể cả ban đêm."},{"fr":"Je me lève tôt pour courir avant la chaleur.","tgt":"Tôi dậy sớm để chạy bộ trước khi trời nóng."},{"fr":"Savoir ralentir, c'est très important.","tgt":"Biết sống chậm lại là điều rất quan trọng."},{"fr":"Parfois, je pars le week-end dans le delta du Mékong.","tgt":"Thỉnh thoảng cuối tuần tôi đi đồng bằng sông Cửu Long."},{"fr":"Là-bas, le rythme de vie est beaucoup plus lent.","tgt":"Ở đó nhịp sống chậm hơn nhiều."},{"fr":"Mon médecin m'a conseillé de dormir davantage.","tgt":"Bác sĩ khuyên tôi nên ngủ nhiều hơn."},{"fr":"Comme on dit ici, la santé vaut de l'or.","tgt":"Người ta vẫn nói, sức khoẻ là vàng."},{"fr":"Je n'emporte plus mon ordinateur portable le week-end.","tgt":"Cuối tuần tôi không mang máy tính xách tay theo nữa."},{"fr":"Trouver son équilibre demande du temps.","tgt":"Tìm được sự cân bằng cần có thời gian."}]},{"title":"Le départ d'une collègue","phrases":[{"fr":"Chị Hoa quitte l'entreprise à la fin du mois.","tgt":"Cuối tháng này chị Hoa nghỉ việc ở công ty."},{"fr":"Elle a trouvé un poste à Hanoï, près de sa famille.","tgt":"Chị ấy tìm được việc ở Hà Nội, gần gia đình."},{"fr":"Nous nous sommes cotisés pour lui offrir un cadeau.","tgt":"Cả nhóm góp tiền mua quà tặng chị ấy."},{"fr":"Elle m'a énormément appris pendant ma première année.","tgt":"Chị ấy đã dạy tôi rất nhiều trong năm đầu tiên."},{"fr":"Son bureau va paraître bien vide sans elle.","tgt":"Thiếu chị ấy, bàn làm việc chắc sẽ trống trải lắm."},{"fr":"Le chef a fait un petit discours très émouvant.","tgt":"Sếp có một bài phát biểu ngắn rất xúc động."},{"fr":"Nous nous promettons de garder le contact.","tgt":"Chúng tôi hứa sẽ giữ liên lạc với nhau."},{"fr":"Si je passe par Hanoï, je l'appellerai sans faute.","tgt":"Nếu có dịp ra Hà Nội, nhất định tôi sẽ gọi cho chị ấy."},{"fr":"Quand on boit l'eau, on se souvient de la source.","tgt":"Uống nước nhớ nguồn."},{"fr":"Je lui souhaite plein de réussite dans sa nouvelle vie.","tgt":"Chúc chị ấy thành công trên chặng đường mới."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module m'a appris à parler de mon travail en vietnamien.","tgt":"Phần học này đã giúp tôi nói về công việc bằng tiếng Việt."},{"fr":"Je sais maintenant dire qui est responsable de quoi.","tgt":"Giờ tôi đã biết nói ai chịu trách nhiệm việc gì."},{"fr":"Les formules polies du bureau me viennent plus naturellement.","tgt":"Những cách nói lịch sự nơi công sở giờ đến với tôi tự nhiên hơn."},{"fr":"Je peux expliquer un problème de logement sans paniquer.","tgt":"Tôi có thể trình bày chuyện nhà cửa mà không hoảng."},{"fr":"Il me reste à travailler la prononciation des tons.","tgt":"Tôi vẫn cần luyện thêm cách phát âm các thanh điệu."},{"fr":"Mes collègues remarquent que je fais des progrès.","tgt":"Đồng nghiệp nhận thấy tôi đang tiến bộ."},{"fr":"Même au téléphone, j'ose maintenant parler vietnamien.","tgt":"Ngay cả khi nói chuyện điện thoại, giờ tôi cũng dám nói tiếng Việt."},{"fr":"Il suffit de pratiquer un peu chaque jour pour progresser.","tgt":"Chỉ cần luyện tập mỗi ngày một chút là sẽ tiến bộ."},{"fr":"Apprendre et pratiquer doivent toujours aller de pair.","tgt":"Học phải đi đôi với hành."},{"fr":"Je me sens prêt pour le module suivant.","tgt":"Tôi thấy mình đã sẵn sàng cho phần tiếp theo."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Cần Thơ","phrases":[{"fr":"Nous sommes arrivés à Cần Thơ assez tard hier soir, après une longue journée de route.","tgt":"Tối qua chúng tôi đến Cần Thơ khá muộn, sau một ngày dài trên đường."},{"fr":"Cần Thơ est considérée comme la capitale du delta du Mékong.","tgt":"Cần Thơ được coi là thủ phủ của đồng bằng sông Cửu Long."},{"fr":"Le quai Ninh Kiều s'anime dès la tombée de la nuit.","tgt":"Bến Ninh Kiều trở nên nhộn nhịp ngay khi trời tối."},{"fr":"Ici, la vie semble s'écouler au rythme du fleuve.","tgt":"Ở đây, cuộc sống dường như trôi theo nhịp của dòng sông."},{"fr":"L'air est bien plus humide et plus chaud qu'à Hanoï.","tgt":"Không khí ở đây ẩm và nóng hơn ở Hà Nội nhiều."},{"fr":"Les gens du Sud parlent avec un accent très différent.","tgt":"Người miền Nam nói giọng rất khác."},{"fr":"Au début, j'avais beaucoup de mal à comprendre le chauffeur de taxi.","tgt":"Lúc đầu, tôi khá vất vả mới hiểu được bác tài xế taxi."},{"fr":"Notre hôtel donne directement sur le fleuve Hậu.","tgt":"Khách sạn của chúng tôi nhìn thẳng ra sông Hậu."},{"fr":"Les habitants nous ont accueillis avec une chaleur remarquable.","tgt":"Người dân ở đây đón tiếp chúng tôi rất nồng hậu."},{"fr":"Demain, nous nous lèverons avant l'aube pour aller voir le marché flottant.","tgt":"Ngày mai chúng tôi sẽ dậy trước bình minh để đi xem chợ nổi."}]},{"title":"Le marché flottant de Cái Răng à l'aube","phrases":[{"fr":"Le marché flottant que nous visitons ce matin s'appelle Cái Răng.","tgt":"Chợ nổi mà chúng tôi đi thăm sáng nay tên là Cái Răng."},{"fr":"Les barques que nous avons vues à l'aube étaient pleines de fruits.","tgt":"Những chiếc thuyền mà chúng tôi thấy lúc bình minh chở đầy hoa quả."},{"fr":"Chaque bateau accroche ce qu'il vend en haut d'une longue perche.","tgt":"Mỗi chiếc thuyền treo hàng mình bán lên một cây sào cao."},{"fr":"La pastèque que cette dame m'a vendue était incroyablement sucrée.","tgt":"Quả dưa hấu mà bà ấy bán cho tôi ngọt vô cùng."},{"fr":"Le café qu'on boit sur l'eau a un goût vraiment à part.","tgt":"Cốc cà phê mà mình uống trên sông có hương vị rất riêng."},{"fr":"Le batelier que nous avons engagé connaît chaque marchand du marché.","tgt":"Anh lái thuyền mà chúng tôi thuê quen biết từng người bán hàng trong chợ."},{"fr":"Ici, on achète et on vend directement de barque à barque.","tgt":"Ở đây người ta mua bán trực tiếp từ thuyền này sang thuyền kia."},{"fr":"Le marché bat son plein dès cinq heures du matin.","tgt":"Chợ họp đông nhất từ khoảng năm giờ sáng."},{"fr":"Les photos que j'ai prises ce matin sont mes préférées de tout le voyage.","tgt":"Những bức ảnh mà tôi chụp sáng nay là những bức tôi thích nhất trong cả chuyến đi."},{"fr":"Il faut venir tôt, car tout se termine vers neuf heures.","tgt":"Phải đến sớm, vì khoảng chín giờ là chợ tan."}],"tip":{"title":"Les relatives avec « mà » : le nom d'abord, la précision ensuite","example":"La pastèque que cette dame m'a vendue était incroyablement sucrée. — Quả dưa hấu <b>mà</b> bà ấy bán cho tôi ngọt vô cùng.","body":"En vietnamien, comme en français, on pose d'abord le nom, puis on ajoute la précision derrière lui, reliée par le petit mot « mà », qui joue le rôle de notre « que ». Dans l'exemple, on dit littéralement : la pastèque, « mà », cette dame vendre à moi, sucrée à l'infini. Rien ne s'accorde et le verbe ne change jamais : on enchaîne simplement les idées dans l'ordre naturel. Écoutez par exemple « người mà tôi gặp », la personne que j'ai rencontrée, ou « món mà anh thích », le plat que tu aimes. À l'oral, « mà » se dit avec un ton descendant, assez bref, et dans une conversation détendue on peut même le laisser tomber. Pour retenir, pensez à une petite chaîne : le nom, puis « mà », puis toute l'histoire.","lit":"[classificateur] (quả) · pastèque · que (mà) · dame · cette · vendre · à · moi · sucré · infiniment","say":{"mà":"mà","người mà tôi gặp":"người mà tôi gặp","món mà anh thích":"món mà anh thích"}}},{"title":"Les vergers du delta","phrases":[{"fr":"Après le marché, nous avons visité un verger à Phong Điền.","tgt":"Sau buổi chợ, chúng tôi đi thăm một vườn cây ăn quả ở Phong Điền."},{"fr":"Le propriétaire nous a fait goûter des ramboutans tout juste cueillis.","tgt":"Bác chủ vườn mời chúng tôi ăn thử chôm chôm vừa mới hái."},{"fr":"Ici, on peut cueillir les fruits directement sur l'arbre.","tgt":"Ở đây có thể hái quả ngay trên cây."},{"fr":"Les durians de cette saison sont particulièrement parfumés.","tgt":"Sầu riêng mùa này đặc biệt thơm."},{"fr":"Les arbres sont plantés entre de petits fossés remplis d'eau.","tgt":"Cây được trồng xen giữa những con mương nhỏ đầy nước."},{"fr":"Les alluvions du fleuve rendent cette terre extrêmement fertile.","tgt":"Phù sa của dòng sông làm cho vùng đất này vô cùng màu mỡ."},{"fr":"Nous avons déjeuné à l'ombre des longaniers.","tgt":"Chúng tôi ăn trưa dưới bóng mát của những cây nhãn."},{"fr":"Par une chaleur pareille, rien ne vaut une noix de coco fraîche.","tgt":"Trời nóng thế này, uống nước dừa tươi là tuyệt nhất."},{"fr":"Le propriétaire nous a montré comment on greffe un arbre fruitier.","tgt":"Bác chủ vườn chỉ cho chúng tôi cách ghép cây ăn quả."},{"fr":"Nous sommes repartis avec un panier rempli de mangues.","tgt":"Chúng tôi ra về với một giỏ đầy xoài."}]},{"title":"En barque sur les canaux","phrases":[{"fr":"Nous avons loué une petite barque pour explorer les canaux.","tgt":"Chúng tôi thuê một chiếc thuyền nhỏ để khám phá các con kênh."},{"fr":"Il faut se baisser pour passer sous les ponts de singe.","tgt":"Phải cúi người xuống để đi qua những cây cầu khỉ."},{"fr":"La rameuse se lève très tôt pour emmener les touristes.","tgt":"Chị chèo thuyền dậy từ rất sớm để chở khách du lịch."},{"fr":"On parle à voix basse pour ne pas effrayer les oiseaux.","tgt":"Chúng tôi nói nhỏ để không làm lũ chim hoảng sợ."},{"fr":"Les habitants utilisent les canaux pour transporter leurs marchandises.","tgt":"Người dân dùng kênh rạch để chở hàng hóa."},{"fr":"J'ai mis un chapeau conique pour me protéger du soleil.","tgt":"Tôi đội nón lá để che nắng."},{"fr":"De chaque côté, les palmiers d'eau forment un véritable tunnel vert.","tgt":"Hai bên bờ, dừa nước tạo thành cả một đường hầm xanh."},{"fr":"Pour atteindre le village, il faut encore ramer une bonne heure.","tgt":"Để đến được làng, phải chèo thêm một tiếng nữa."},{"fr":"La barque est si étroite qu'il faut rester bien immobile.","tgt":"Thuyền hẹp đến mức phải ngồi thật yên."},{"fr":"Je garde mon téléphone dans un sac étanche pour qu'il ne soit pas mouillé.","tgt":"Tôi để điện thoại trong túi chống nước để nó khỏi bị ướt."}],"tip":{"title":"« Để » : pour, afin de","example":"J'ai mis un chapeau conique pour me protéger du soleil. — Tôi đội nón lá <b>để</b> che nắng.","body":"Pour dire le but d'une action, le vietnamien place simplement « để » juste avant le second verbe, exactement comme notre « pour ». Dans l'exemple, on dit mot à mot : je porter chapeau conique, « để », abriter soleil. Le verbe qui suit ne change jamais, et on peut aussi ouvrir la phrase avec lui, comme dans « để đến được làng », pour arriver au village. Pour dire « pour ne pas », on ajoute « không » ou « khỏi », comme dans « để khỏi bị ướt », pour ne pas être mouillé. Attention, « để » veut aussi dire poser ou laisser, comme dans « để điện thoại », poser son téléphone : c'est le contexte qui tranche. Il se prononce avec un ton qui plonge puis remonte, comme une petite question surprise.","lit":"je · porter sur la tête · chapeau conique · pour (để) · abriter · soleil","say":{"Để":"Để","để":"để","để đến được làng":"để đến được làng","không":"không","khỏi":"khỏi","để khỏi bị ướt":"để khỏi bị ướt","để điện thoại":"để điện thoại"}}},{"title":"Une nuit chez l'habitant","phrases":[{"fr":"Ce soir, nous dormons chez une famille au bord du canal.","tgt":"Tối nay chúng tôi ngủ lại nhà một gia đình bên bờ kênh."},{"fr":"La maison est construite sur pilotis, juste au-dessus de l'eau.","tgt":"Ngôi nhà được dựng trên cọc, ngay trên mặt nước."},{"fr":"Notre hôtesse nous a appris à préparer des crêpes croustillantes.","tgt":"Cô chủ nhà dạy chúng tôi làm bánh xèo."},{"fr":"Toute la famille dîne ensemble, assise sur une grande natte.","tgt":"Cả nhà ngồi ăn tối cùng nhau trên một chiếc chiếu lớn."},{"fr":"Le grand-père nous a raconté la vie d'autrefois dans le delta.","tgt":"Ông cụ kể cho chúng tôi nghe về cuộc sống ngày xưa ở miền Tây."},{"fr":"On s'endort sous la moustiquaire, au son de l'eau qui clapote.","tgt":"Chúng tôi ngủ trong màn, nghe tiếng nước vỗ mà thiếp đi."},{"fr":"Le chant des coqs nous a réveillés bien avant six heures.","tgt":"Tiếng gà gáy đánh thức chúng tôi từ trước sáu giờ."},{"fr":"Comme dit le proverbe, quand on entre dans une maison, on en suit les coutumes.","tgt":"Như tục ngữ có câu: nhập gia tùy tục."},{"fr":"Nos hôtes refusaient obstinément qu'on les aide à faire la vaisselle.","tgt":"Chủ nhà nhất định không cho chúng tôi giúp rửa bát."},{"fr":"En partant, nous leur avons laissé un petit cadeau venu de France.","tgt":"Lúc đi, chúng tôi để lại cho họ một món quà nhỏ từ Pháp."}]},{"title":"Les longues routes en bus","phrases":[{"fr":"Le trajet en bus jusqu'à Rạch Giá dure environ quatre heures.","tgt":"Chuyến xe khách đi Rạch Giá mất khoảng bốn tiếng."},{"fr":"J'ai réservé une couchette à l'avant du bus.","tgt":"Tôi đã đặt một giường nằm ở phía đầu xe."},{"fr":"Il faut retirer ses chaussures avant de monter à bord.","tgt":"Phải cởi giày trước khi lên xe."},{"fr":"Le chauffeur klaxonne pratiquement sans arrêt.","tgt":"Bác tài bấm còi gần như liên tục."},{"fr":"Le bus s'arrête souvent au bord de la route pour prendre des passagers.","tgt":"Xe hay dừng dọc đường để đón khách."},{"fr":"Nous avons fait une pause dans une grande aire de repos.","tgt":"Chúng tôi nghỉ chân ở một trạm dừng lớn."},{"fr":"La climatisation était réglée beaucoup trop froid.","tgt":"Điều hòa bật lạnh quá."},{"fr":"Heureusement, j'avais emporté un pull et une écharpe.","tgt":"May mà tôi có mang theo áo len và khăn quàng."},{"fr":"Mon voisin de couchette m'a offert un peu de son riz gluant.","tgt":"Người nằm cạnh mời tôi một ít xôi."},{"fr":"Ces longs trajets permettent de voir le vrai visage du pays.","tgt":"Những chuyến đi dài như thế giúp mình thấy được bộ mặt thật của đất nước."}]},{"title":"À vélo sur les digues","phrases":[{"fr":"Avec cette chaleur, je n'arrive plus à pédaler.","tgt":"Trời nóng thế này, tôi đạp không nổi nữa."},{"fr":"Tu arrives à lire le panneau là-bas ?","tgt":"Anh có đọc được tấm biển đằng kia không?"},{"fr":"Ce sac est trop lourd, je n'arrive pas à le porter tout seul.","tgt":"Cái túi này nặng quá, một mình tôi xách không nổi."},{"fr":"On a réussi à trouver le chemin sans aucune carte.","tgt":"Chúng tôi đã tìm được đường mà không cần bản đồ."},{"fr":"Je n'arriverai jamais à finir tout ça, c'est beaucoup trop.","tgt":"Nhiều quá, tôi ăn không nổi đâu."},{"fr":"Quand on parle lentement, j'arrive à comprendre le vietnamien.","tgt":"Nếu nói chậm thì tôi nghe được tiếng Việt."},{"fr":"Ce pont est trop étroit, on ne peut pas passer avec les vélos.","tgt":"Cầu này hẹp quá, dắt xe đạp qua không được."},{"fr":"Après trente kilomètres, je ne tenais plus debout.","tgt":"Sau ba mươi cây số, tôi đứng không nổi nữa."},{"fr":"Finalement, nous avons réussi à atteindre le village avant la nuit.","tgt":"Cuối cùng chúng tôi cũng đến được làng trước khi trời tối."},{"fr":"Avec un peu d'entraînement, on arrive à tout.","tgt":"Chịu khó tập luyện thì việc gì cũng làm được."}],"tip":{"title":"« Được » et « nổi » après le verbe : arriver à faire","example":"Ce sac est trop lourd, je n'arrive pas à le porter tout seul. — Cái túi này nặng quá, một mình tôi xách không <b>nổi</b>.","body":"Pour dire qu'on arrive à faire quelque chose, le vietnamien ne met pas de verbe « pouvoir » devant : il colle un petit mot après le verbe. « Được » exprime la réussite ou la possibilité en général, comme dans « nghe được », arriver à comprendre en écoutant, ou « tìm được đường », réussir à trouver le chemin. « Nổi » insiste sur la force ou l'endurance, et s'emploie surtout à la forme négative : « ăn không nổi », je n'arrive pas à manger tout ça, ou « đứng không nổi », je ne tiens plus debout. Dans l'exemple, on dit mot à mot : seul je porter non force, c'est-à-dire que le sac dépasse mes forces. Pour la négation, on glisse « không » entre le verbe et le petit mot, ou bien juste avant le verbe. Astuce : « được », c'est réussir, et « nổi », c'est tenir le coup.","lit":"[classificateur] (cái) · sac · ce · lourd · trop · seul · je · porter · [négation] (không) · avoir la force (nổi)","say":{"Được":"Được","nổi":"nổi","nghe được":"nghe được","tìm được đường":"tìm được đường","Nổi":"Nổi","ăn không nổi":"ăn không nổi","đứng không nổi":"đứng không nổi","không":"không","được":"được"}}},{"title":"Marchander sans vexer","phrases":[{"fr":"Au marché de Cần Thơ, il faut toujours marchander un peu.","tgt":"Ở chợ Cần Thơ, lúc nào cũng phải mặc cả một chút."},{"fr":"Madame, combien coûte ce chapeau conique ?","tgt":"Chị ơi, cái nón lá này bao nhiêu tiền?"},{"fr":"Cent mille dongs, c'est un peu cher pour moi.","tgt":"Một trăm nghìn đồng thì hơi đắt với tôi."},{"fr":"Vous pouvez baisser le prix si j'en prends deux ?","tgt":"Nếu tôi lấy hai cái thì chị bớt cho tôi được không?"},{"fr":"Je vous en donne soixante-dix mille, je ne peux pas aller plus haut.","tgt":"Bảy mươi nghìn thôi chị nhé, tôi không trả hơn được đâu."},{"fr":"La vendeuse a fait semblant d'être vexée, puis elle a éclaté de rire.","tgt":"Chị bán hàng giả vờ phật ý, rồi bật cười."},{"fr":"Ici, on aime dire que ce qui est trop bon marché est rarement de bonne qualité.","tgt":"Ở đây người ta hay nói: của rẻ là của ôi."},{"fr":"Il ne faut jamais marchander de façon agressive.","tgt":"Đừng bao giờ mặc cả quá gay gắt."},{"fr":"Un sourire fait souvent baisser le prix plus vite qu'un argument.","tgt":"Một nụ cười thường làm giá xuống nhanh hơn mọi lý lẽ."},{"fr":"Finalement, nous nous sommes mis d'accord sur quatre-vingt mille dongs.","tgt":"Cuối cùng hai bên thống nhất giá tám mươi nghìn đồng."}]},{"title":"Les saveurs du delta","phrases":[{"fr":"La cuisine du delta est nettement plus sucrée que celle du Nord.","tgt":"Món ăn miền Tây ngọt hơn hẳn món ăn miền Bắc."},{"fr":"On nous a servi un poisson frit entier, posé debout sur le plat.","tgt":"Người ta dọn cho chúng tôi món cá tai tượng chiên xù, dựng đứng trên đĩa."},{"fr":"On roule chaque morceau dans une galette de riz avec des herbes.","tgt":"Mỗi miếng được cuốn với bánh tráng và rau thơm."},{"fr":"La fondue au poisson fermenté a une odeur très puissante.","tgt":"Lẩu mắm có mùi rất nồng."},{"fr":"Pourtant, une fois qu'on y a goûté, on ne peut plus s'arrêter.","tgt":"Nhưng đã ăn thử rồi thì không dừng lại được."},{"fr":"Le delta produit une grande partie du riz du pays.","tgt":"Đồng bằng sông Cửu Long sản xuất phần lớn lúa gạo của cả nước."},{"fr":"Chaque repas s'accompagne d'une montagne d'herbes fraîches.","tgt":"Bữa ăn nào cũng có cả một rổ rau sống."},{"fr":"Le jus de canne à sucre se vend à tous les coins de rue.","tgt":"Nước mía được bán ở khắp các góc phố."},{"fr":"J'ai demandé la recette au cuisinier, qui a souri sans répondre.","tgt":"Tôi hỏi đầu bếp công thức, anh ấy chỉ mỉm cười mà không trả lời."},{"fr":"Cette cuisine généreuse reflète bien le caractère des gens d'ici.","tgt":"Cách nấu ăn đậm đà, phóng khoáng ấy phản ánh đúng tính cách người miền Tây."}]},{"title":"Un atelier de galettes de riz","phrases":[{"fr":"Nous avons visité un atelier familial de galettes de riz.","tgt":"Chúng tôi đến thăm một cơ sở làm bánh tráng của một gia đình."},{"fr":"Toute la famille fait ce métier depuis trois générations.","tgt":"Cả gia đình làm nghề này đã ba đời."},{"fr":"La pâte de riz est étalée en couche très fine sur un tissu tendu.","tgt":"Bột gạo được tráng thật mỏng trên một tấm vải căng."},{"fr":"Les galettes sèchent ensuite au soleil sur des claies en bambou.","tgt":"Sau đó bánh được phơi nắng trên những tấm phên tre."},{"fr":"La grand-mère travaille à une vitesse impressionnante.","tgt":"Bà cụ làm nhanh đến kinh ngạc."},{"fr":"J'ai essayé moi-même, mais ma galette s'est déchirée.","tgt":"Tôi cũng thử làm, nhưng cái bánh của tôi bị rách."},{"fr":"Il faut des années de pratique pour maîtriser ce geste.","tgt":"Phải mất nhiều năm mới thạo được động tác này."},{"fr":"Comme on dit, à force de limer le fer, on finit par obtenir une aiguille.","tgt":"Như người ta nói: có công mài sắt, có ngày nên kim."},{"fr":"Ces artisans vendent leurs galettes dans toute la région.","tgt":"Những người thợ này bán bánh đi khắp vùng."},{"fr":"J'admire profondément la patience de ces gens.","tgt":"Tôi thật sự khâm phục sự kiên nhẫn của họ."}]},{"title":"Cap sur l'île de Phú Quốc","phrases":[{"fr":"Pour rejoindre Phú Quốc, nous avons pris le bateau rapide depuis Rạch Giá.","tgt":"Để ra Phú Quốc, chúng tôi đi tàu cao tốc từ Rạch Giá."},{"fr":"La traversée dure un peu plus de deux heures.","tgt":"Chuyến tàu mất hơn hai tiếng một chút."},{"fr":"La mer était agitée et plusieurs passagers avaient le mal de mer.","tgt":"Biển động, nhiều hành khách bị say sóng."},{"fr":"Phú Quốc est la plus grande île du pays.","tgt":"Phú Quốc là hòn đảo lớn nhất Việt Nam."},{"fr":"Dès qu'on descend du bateau, on sent l'odeur de la sauce de poisson.","tgt":"Vừa xuống tàu đã ngửi thấy mùi nước mắm."},{"fr":"L'île est réputée pour son poivre et sa sauce de poisson.","tgt":"Đảo này nổi tiếng về hồ tiêu và nước mắm."},{"fr":"Notre bungalow se trouve à deux pas de la plage.","tgt":"Căn nhà gỗ của chúng tôi chỉ cách bãi biển vài bước chân."},{"fr":"L'eau est d'un bleu turquoise presque irréel.","tgt":"Nước biển xanh ngọc đến mức gần như không thật."},{"fr":"Après l'agitation du delta, ce calme fait un bien fou.","tgt":"Sau những ngày nhộn nhịp ở miền Tây, sự yên tĩnh này thật dễ chịu."},{"fr":"Nous avons décidé de rester ici une semaine entière.","tgt":"Chúng tôi quyết định ở lại đây trọn một tuần."}]},{"title":"Les bons conseils avant d'explorer l'île","phrases":[{"fr":"Tu devrais mettre de la crème solaire, le soleil tape très fort.","tgt":"Anh nên bôi kem chống nắng, nắng gắt lắm."},{"fr":"Il vaudrait mieux partir tôt pour éviter la chaleur.","tgt":"Nên đi sớm để tránh nóng."},{"fr":"On ne devrait pas se baigner quand le drapeau rouge est levé.","tgt":"Không nên tắm biển khi có cờ đỏ."},{"fr":"D'après vous, quelle plage devrais-je aller voir ?","tgt":"Theo anh, tôi nên đi bãi biển nào?"},{"fr":"Vous devriez goûter les oursins grillés au marché de nuit.","tgt":"Anh nên ăn thử món nhím biển nướng ở chợ đêm."},{"fr":"Le mieux, c'est de réserver le bateau la veille.","tgt":"Tốt nhất là nên đặt thuyền từ hôm trước."},{"fr":"Tu ne devrais pas laisser ton sac sans surveillance sur la plage.","tgt":"Anh không nên để túi trên bãi biển mà không ai trông."},{"fr":"Pour faire le tour de l'île, mieux vaut louer un scooter que prendre un taxi.","tgt":"Muốn đi khắp đảo thì nên thuê xe máy hơn là đi taxi."},{"fr":"Je pense qu'on devrait rentrer avant l'orage.","tgt":"Tôi nghĩ chúng ta nên về trước khi cơn giông đến."},{"fr":"Si tu en as l'occasion, tu devrais voir le coucher du soleil sur la côte ouest.","tgt":"Có dịp thì anh nên ngắm hoàng hôn ở bờ tây của đảo."}],"tip":{"title":"« Nên » : il vaudrait mieux, ça devrait","example":"Il vaudrait mieux partir tôt pour éviter la chaleur. — <b>Nên</b> đi sớm để tránh nóng.","body":"Pour donner un conseil, le vietnamien place « nên » juste devant le verbe, et le verbe ne bouge pas : « anh nên bôi kem », tu devrais mettre de la crème. Dans l'exemple, on dit mot à mot : conseiller partir tôt pour éviter chaleur, sans même de sujet, car le conseil vaut pour tout le monde. Au négatif, « không nên » veut dire il vaut mieux ne pas, comme dans « không nên tắm biển », mieux vaut ne pas se baigner. Pour demander conseil, on retourne la phrase : « tôi nên đi đâu ? », où devrais-je aller ? Retenez bien la différence avec « phải », qui est une vraie obligation, alors que « nên » reste une suggestion aimable. Et « tốt nhất là nên », c'est le mieux à faire. Il se prononce sur un ton plat et tranquille, comme un conseil donné sans pression.","lit":"devoir, conseil (nên) · partir · tôt · pour · éviter · chaleur","say":{"Nên":"Nên","nên":"nên","anh nên bôi kem":"anh nên bôi kem","không nên":"không nên","không nên tắm biển":"không nên tắm biển","tôi nên đi đâu ?":"tôi nên đi đâu ?","phải":"phải","tốt nhất là nên":"tốt nhất là nên"}}},{"title":"Une journée en mer","phrases":[{"fr":"Nous avons embarqué sur un bateau de pêche pour visiter les îles du sud.","tgt":"Chúng tôi lên một chiếc thuyền đánh cá để đi thăm các hòn đảo phía nam."},{"fr":"Le capitaine connaît par cœur chaque récif de l'archipel.","tgt":"Bác thuyền trưởng thuộc lòng từng rạn san hô trong quần đảo."},{"fr":"Nous avons observé les coraux avec un masque et un tuba.","tgt":"Chúng tôi đeo kính lặn và ống thở để ngắm san hô."},{"fr":"Des poissons de toutes les couleurs nageaient autour de nous.","tgt":"Cá đủ màu sắc bơi quanh chúng tôi."},{"fr":"À midi, l'équipage a grillé les calamars pêchés le matin même.","tgt":"Buổi trưa, người trên thuyền nướng mực vừa câu được sáng hôm đó."},{"fr":"J'ai essayé de pêcher, mais je n'ai rien attrapé du tout.","tgt":"Tôi thử câu cá nhưng chẳng được con nào."},{"fr":"Le soleil se reflétait sur l'eau comme dans un miroir.","tgt":"Mặt trời phản chiếu trên mặt nước như trong một tấm gương."},{"fr":"Sur le chemin du retour, tout le monde s'est endormi sur le pont.","tgt":"Trên đường về, ai cũng ngủ thiếp đi trên boong thuyền."},{"fr":"On dit ici que cent récits ne valent pas un seul coup d'œil.","tgt":"Người ta bảo: trăm nghe không bằng một thấy."},{"fr":"C'était sans doute la plus belle journée de tout le voyage.","tgt":"Đó có lẽ là ngày đẹp nhất của cả chuyến đi."}]},{"title":"Le marché de nuit de Dương Đông","phrases":[{"fr":"Le marché de nuit de Dương Đông ouvre vers six heures du soir.","tgt":"Chợ đêm Dương Đông mở cửa khoảng sáu giờ tối."},{"fr":"Les fruits de mer sont exposés vivants dans de grandes bassines.","tgt":"Hải sản còn sống được bày trong những chậu nước lớn."},{"fr":"On choisit son poisson, puis on le fait griller sur place.","tgt":"Mình chọn cá, rồi nhờ người ta nướng tại chỗ."},{"fr":"Ici, le poisson se vend au poids, et non à la pièce.","tgt":"Ở đây cá được bán theo cân, chứ không bán theo con."},{"fr":"Avant de commander, mieux vaut toujours demander le prix.","tgt":"Trước khi gọi món thì nên hỏi giá."},{"fr":"Le vendeur a pesé le crabe juste devant nous.","tgt":"Người bán cân con cua ngay trước mặt chúng tôi."},{"fr":"On y trouve aussi des stands de perles et de poivre.","tgt":"Ở đó cũng có các quầy bán ngọc trai và hồ tiêu."},{"fr":"L'odeur des brochettes grillées attire tous les passants.","tgt":"Mùi xiên nướng thu hút khách qua đường."},{"fr":"Nous nous sommes installés sur de petits tabourets en plastique.","tgt":"Chúng tôi ngồi trên những chiếc ghế nhựa nhỏ."},{"fr":"Je n'ai jamais mangé de crevettes aussi fraîches de toute ma vie.","tgt":"Cả đời tôi chưa bao giờ ăn tôm tươi đến thế."}]},{"title":"En scooter sur les routes de l'île","phrases":[{"fr":"Nous avons loué un scooter pour la journée à cent cinquante mille dongs.","tgt":"Chúng tôi thuê một chiếc xe máy cả ngày với giá một trăm năm mươi nghìn đồng."},{"fr":"Le loueur a gardé une photocopie de mon passeport.","tgt":"Người cho thuê giữ một bản sao hộ chiếu của tôi."},{"fr":"Vérifie bien les freins avant de partir.","tgt":"Kiểm tra kỹ phanh trước khi đi nhé."},{"fr":"Les routes côtières sont superbes, mais parfois couvertes de sable.","tgt":"Đường ven biển rất đẹp, nhưng có chỗ đầy cát."},{"fr":"Il faut toujours porter un casque, même pour un petit trajet.","tgt":"Lúc nào cũng phải đội mũ bảo hiểm, kể cả khi đi gần."},{"fr":"Nous sommes tombés en panne d'essence au milieu de nulle part.","tgt":"Chúng tôi hết xăng giữa nơi đồng không mông quạnh."},{"fr":"Un jeune homme nous a vendu un litre d'essence dans une bouteille.","tgt":"Một cậu thanh niên bán cho chúng tôi một lít xăng đựng trong chai."},{"fr":"Sans lui, nous aurions dû pousser le scooter sur des kilomètres.","tgt":"Không có cậu ấy thì chúng tôi đã phải dắt xe mấy cây số."},{"fr":"La forêt du nord de l'île est encore très sauvage.","tgt":"Rừng ở phía bắc đảo vẫn còn rất hoang sơ."},{"fr":"Rouler le long de la mer au coucher du soleil, c'est le vrai bonheur.","tgt":"Chạy xe dọc bờ biển lúc hoàng hôn thật là hạnh phúc."}]},{"title":"Surpris par une averse tropicale","phrases":[{"fr":"Le ciel s'est couvert d'un coup en début d'après-midi.","tgt":"Đầu giờ chiều, trời bỗng kéo mây đen."},{"fr":"La pluie est tombée si fort qu'on ne voyait plus la route.","tgt":"Mưa to đến mức không nhìn thấy đường nữa."},{"fr":"Nous nous sommes abrités sous l'auvent d'une petite épicerie.","tgt":"Chúng tôi trú mưa dưới mái hiên một tiệm tạp hóa nhỏ."},{"fr":"La patronne nous a offert du thé chaud en attendant.","tgt":"Bà chủ tiệm mời chúng tôi uống trà nóng trong lúc chờ."},{"fr":"À la saison des pluies, les averses durent rarement plus d'une heure.","tgt":"Vào mùa mưa, mưa rào hiếm khi kéo dài quá một tiếng."},{"fr":"En quelques minutes, les rues se sont transformées en ruisseaux.","tgt":"Chỉ trong vài phút, đường phố đã biến thành những dòng suối."},{"fr":"Les gens d'ici enfilent un poncho et reprennent tranquillement leur route.","tgt":"Người dân ở đây mặc áo mưa vào rồi lại thong thả đi tiếp."},{"fr":"Nous étions trempés jusqu'aux os.","tgt":"Chúng tôi ướt như chuột lột."},{"fr":"Une fois l'averse passée, l'air est devenu enfin respirable.","tgt":"Mưa tạnh, không khí mới dễ thở hơn hẳn."},{"fr":"Comme dit le proverbe vietnamien, après la pluie, le ciel s'éclaircit.","tgt":"Như tục ngữ có câu: sau cơn mưa trời lại sáng."}]},{"title":"Faire une réclamation à l'hôtel","phrases":[{"fr":"Excusez-moi, je voudrais faire une réclamation.","tgt":"Xin lỗi, tôi muốn khiếu nại một việc."},{"fr":"J'avais réservé une chambre avec vue sur la mer.","tgt":"Tôi đã đặt một phòng nhìn ra biển."},{"fr":"Or, la chambre qu'on nous a donnée donne sur le parking.","tgt":"Thế nhưng phòng mà khách sạn đưa cho chúng tôi lại nhìn ra bãi đỗ xe."},{"fr":"En plus, la climatisation ne marche plus depuis hier soir.","tgt":"Thêm nữa, điều hòa không chạy từ tối qua."},{"fr":"Voici la confirmation de réservation, avec le prix convenu.","tgt":"Đây là xác nhận đặt phòng, có ghi rõ giá đã thỏa thuận."},{"fr":"Je comprends bien que ce n'est pas de votre faute.","tgt":"Tôi hiểu đây không phải lỗi của anh."},{"fr":"Mais j'aimerais qu'on trouve une solution avant ce soir.","tgt":"Nhưng tôi mong được giải quyết trước tối nay."},{"fr":"Serait-il possible de changer de chambre ?","tgt":"Liệu có đổi phòng cho tôi được không ạ?"},{"fr":"Sinon, je me permettrai de demander un remboursement partiel.","tgt":"Nếu không, tôi xin được hoàn lại một phần tiền."},{"fr":"Le réceptionniste s'est excusé et nous a donné une chambre de catégorie supérieure.","tgt":"Anh lễ tân xin lỗi và nâng hạng phòng cho chúng tôi."}]},{"title":"Un delta qui change vite","phrases":[{"fr":"Phú Quốc attire de plus en plus de visiteurs.","tgt":"Phú Quốc càng ngày càng thu hút nhiều du khách."},{"fr":"Les hôtels sont de plus en plus nombreux le long de la côte.","tgt":"Khách sạn dọc bờ biển càng ngày càng nhiều."},{"fr":"Les prix augmentent de plus en plus vite.","tgt":"Giá cả càng ngày càng tăng nhanh."},{"fr":"Les routes du delta sont de plus en plus modernes.","tgt":"Đường sá ở miền Tây càng ngày càng hiện đại."},{"fr":"De plus en plus de jeunes partent travailler en ville.","tgt":"Ngày càng nhiều thanh niên lên thành phố làm việc."},{"fr":"Les marchés flottants deviennent de plus en plus petits.","tgt":"Các chợ nổi càng ngày càng nhỏ lại."},{"fr":"J'arrive à comprendre le vietnamien de mieux en mieux.","tgt":"Tôi nghe tiếng Việt càng ngày càng khá lên."},{"fr":"Plus on reste ici, plus on a envie de rester.","tgt":"Càng ở lâu, càng muốn ở lại."},{"fr":"Plus on descend vers le sud, plus il fait chaud.","tgt":"Càng đi về phía nam, trời càng nóng."},{"fr":"Il faudra protéger ces paysages, de plus en plus fragiles.","tgt":"Cần phải bảo vệ những cảnh quan ngày càng mong manh này."}],"tip":{"title":"« Càng ngày càng » : de plus en plus","example":"Phú Quốc attire de plus en plus de visiteurs. — Phú Quốc <b>càng ngày càng</b> thu hút nhiều du khách.","body":"Pour dire de plus en plus, le vietnamien utilise une image très parlante : « càng ngày càng », mot à mot plus jour plus, c'est-à-dire chaque jour un peu plus. On le place juste devant le verbe ou l'adjectif : « càng ngày càng nhiều », de plus en plus nombreux, ou « càng ngày càng nóng », de plus en plus chaud. Dans la conversation, on raccourcit souvent en « ngày càng », comme dans « ngày càng nhiều thanh niên », de plus en plus de jeunes. Le même petit mot sert aussi pour notre plus ceci, plus cela : « càng ở lâu, càng muốn ở lại », plus on reste, plus on a envie de rester. « Càng » se dit avec un ton descendant, posé et grave. Pour le retenir, imaginez une marche que l'on gravit un peu plus chaque jour.","lit":"Phú Quốc · plus (càng) · jour (ngày) · plus (càng) · attirer · nombreux · visiteurs","say":{"Càng ngày càng":"Càng ngày càng","càng ngày càng":"càng ngày càng","càng ngày càng nhiều":"càng ngày càng nhiều","càng ngày càng nóng":"càng ngày càng nóng","ngày càng":"ngày càng","ngày càng nhiều thanh niên":"ngày càng nhiều thanh niên","càng ở lâu, càng muốn ở lại":"càng ở lâu, càng muốn ở lại","Càng":"Càng"}}},{"title":"Raconter son voyage en détail","phrases":[{"fr":"Laisse-moi te raconter notre voyage dans le delta du début à la fin.","tgt":"Để tôi kể cho anh nghe chuyến đi miền Tây của chúng tôi từ đầu đến cuối."},{"fr":"Nous avons d'abord passé trois jours à Cần Thơ.","tgt":"Đầu tiên chúng tôi ở Cần Thơ ba ngày."},{"fr":"Ensuite, nous avons traversé le delta en bus jusqu'à Rạch Giá.","tgt":"Sau đó chúng tôi đi xe khách xuyên qua miền Tây đến Rạch Giá."},{"fr":"Ce qui m'a le plus marqué, c'est la gentillesse des gens.","tgt":"Điều làm tôi ấn tượng nhất là sự tốt bụng của người dân."},{"fr":"Le moment le plus drôle, c'était notre panne d'essence sur l'île.","tgt":"Lúc buồn cười nhất là khi chúng tôi hết xăng trên đảo."},{"fr":"Le seul vrai souci, c'était cette chambre qui donnait sur le parking.","tgt":"Rắc rối duy nhất là cái phòng nhìn ra bãi đỗ xe."},{"fr":"Si c'était à refaire, je resterais plus longtemps chez l'habitant.","tgt":"Nếu được đi lại, tôi sẽ ở nhà dân lâu hơn."},{"fr":"On dit qu'un seul jour de route apprend plus que bien des livres.","tgt":"Người ta bảo: đi một ngày đàng, học một sàng khôn."},{"fr":"Pendant ces trois semaines, j'ai vraiment compris ce proverbe.","tgt":"Ba tuần vừa qua tôi đã thật sự thấm thía câu ấy."},{"fr":"Je te montrerai les photos ce week-end, si tu veux.","tgt":"Cuối tuần này tôi cho anh xem ảnh nhé, nếu anh muốn."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a emmenés du delta du Mékong jusqu'à l'île de Phú Quốc.","tgt":"Học phần này đã đưa chúng ta từ đồng bằng sông Cửu Long ra tận đảo Phú Quốc."},{"fr":"Nous savons maintenant marchander, réclamer et raconter en vietnamien.","tgt":"Giờ đây chúng ta đã biết mặc cả, khiếu nại và kể chuyện bằng tiếng Việt."},{"fr":"Donner un conseil ou dire un but nous semble désormais naturel.","tgt":"Khuyên ai đó hay nói về mục đích, giờ đã trở nên tự nhiên với chúng ta."},{"fr":"Notre vietnamien progresse vraiment de jour en jour.","tgt":"Tiếng Việt của chúng ta càng ngày càng tiến bộ."},{"fr":"Nous comprenons bien mieux l'accent du Sud qu'au début.","tgt":"Chúng ta đã nghe giọng miền Nam dễ hơn lúc đầu nhiều."},{"fr":"Chaque proverbe appris nous rapproche un peu plus des gens d'ici.","tgt":"Mỗi câu tục ngữ học được lại đưa chúng ta đến gần người Việt hơn một chút."},{"fr":"Il est temps de s'accorder une petite pause bien méritée.","tgt":"Đã đến lúc nghỉ ngơi một chút, chúng ta xứng đáng được như vậy."},{"fr":"Prenez le temps de réécouter les leçons les plus difficiles.","tgt":"Hãy dành thời gian nghe lại những bài khó nhất."},{"fr":"Le prochain module sera consacré aux conversations de la vie sociale.","tgt":"Học phần tiếp theo sẽ dành cho những cuộc trò chuyện xã giao."},{"fr":"Bravo, et à très vite pour la suite du voyage.","tgt":"Chúc mừng các bạn, hẹn sớm gặp lại ở chặng tiếp theo."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouver Hanoï, des années après","phrases":[{"fr":"Je viens tout juste d'arriver à Hanoï, et je me sens déjà chez moi.","tgt":"Tôi mới chân ướt chân ráo đến Hà Nội mà đã thấy như ở nhà."},{"fr":"Les rues du vieux quartier sont toujours noires de monde.","tgt":"Phố cổ lúc nào cũng đông như kiến."},{"fr":"En revoyant mes amis, on s'est serré la main avec une joie immense.","tgt":"Gặp lại bạn bè, chúng tôi tay bắt mặt mừng."},{"fr":"Ici, je me sens comme un poisson dans l'eau.","tgt":"Ở đây tôi thấy mình như cá gặp nước."},{"fr":"Hier soir, il pleuvait à verse sur le vieux quartier.","tgt":"Tối qua trời mưa như trút nước ở phố cổ."},{"fr":"Le matin, la circulation avance à pas de tortue.","tgt":"Buổi sáng xe cộ đi chậm như rùa."},{"fr":"Le bánh mì du coin de la rue se vend comme des petits pains.","tgt":"Bánh mì ở góc phố bán đắt như tôm tươi."},{"fr":"Loin des yeux, loin du cœur, dit-on, mais notre amitié a tenu bon.","tgt":"Người ta nói xa mặt cách lòng, nhưng tình bạn của chúng tôi vẫn bền chặt."},{"fr":"Au marché, les fruits sont presque donnés.","tgt":"Hoa quả ở chợ rẻ như bèo."},{"fr":"Toute la ville est joyeuse comme un jour de Tết.","tgt":"Cả thành phố vui như Tết."}],"tip":{"title":"Les « thành ngữ » : les expressions toutes faites","example":"Les rues du vieux quartier sont toujours noires de monde. — Phố cổ lúc nào cũng <b>đông như kiến</b>.","body":"Les « thành ngữ », ce sont des expressions toutes faites, souvent des comparaisons imagées, que les Vietnamiens glissent partout dans la conversation. Comme en français où l'on dit fort comme un bœuf, on dit ici « đông như kiến », mot à mot bondé comme les fourmis, pour une rue noire de monde. La construction est presque toujours la même : un adjectif, puis « như », qui veut dire comme, puis une image. Vous pouvez ainsi dire « chậm như rùa », lent comme une tortue, ou « vui như Tết », joyeux comme au « Tết ». Certaines expressions vont par paires, comme « tay bắt mặt mừng », les mains qui se serrent et les visages qui se réjouissent, pour des retrouvailles chaleureuses. Astuce : apprenez-les comme de petites chansons de quatre syllabes, avec leur rythme, et essayez d'en placer une dans chaque conversation.","lit":"vieux quartier · à tout moment · [aussi] · bondé · comme · fourmi","say":{"thành ngữ":"thành ngữ","đông như kiến":"đông như kiến","như":"như","chậm như rùa":"chậm như rùa","vui như Tết":"vui như Tết","tay bắt mặt mừng":"tay bắt mặt mừng"}}},{"title":"Le lac Hoàn Kiếm au petit matin","phrases":[{"fr":"À cinq heures du matin, le lac Hoàn Kiếm est déjà plein de vie.","tgt":"Mới năm giờ sáng mà hồ Hoàn Kiếm đã nhộn nhịp rồi."},{"fr":"Des groupes de personnes âgées font de la gymnastique au bord de l'eau.","tgt":"Từng nhóm người già tập thể dục bên bờ hồ."},{"fr":"La brume légère sur le lac donne au paysage un air de rêve.","tgt":"Làn sương mỏng trên mặt hồ khiến cảnh vật như trong mơ."},{"fr":"J'aime faire le tour du lac avant que la ville ne se réveille.","tgt":"Tôi thích đi dạo quanh hồ trước khi thành phố thức giấc."},{"fr":"Une dame m'a proposé de danser avec son groupe.","tgt":"Một bác gái rủ tôi nhảy cùng nhóm của bác."},{"fr":"Le pont rouge se reflète dans l'eau calme.","tgt":"Cây cầu màu đỏ soi bóng xuống mặt nước phẳng lặng."},{"fr":"À cette heure-ci, l'air est encore frais et agréable.","tgt":"Giờ này không khí vẫn còn mát mẻ, dễ chịu."},{"fr":"Un vieux monsieur m'a raconté qu'il venait ici tous les matins depuis quarante ans.","tgt":"Một ông cụ kể với tôi rằng ông ra đây mỗi sáng suốt bốn mươi năm nay."},{"fr":"Les marchandes ambulantes installent déjà leurs paniers de fleurs.","tgt":"Mấy cô bán hàng rong đã bày gánh hoa ra rồi."},{"fr":"Pour moi, c'est le plus beau moment de la journée à Hanoï.","tgt":"Với tôi, đây là khoảnh khắc đẹp nhất trong ngày ở Hà Nội."}]},{"title":"Les petites formules des voisins","phrases":[{"fr":"Dès qu'elle me voit, la voisine me demande si j'ai mangé.","tgt":"Vừa thấy tôi, bà hàng xóm đã hỏi cháu ăn cơm chưa."},{"fr":"Oui, j'ai déjà mangé, et vous, madame, vous avez mangé ?","tgt":"Dạ, cháu ăn rồi, bà ăn cơm chưa ạ?"},{"fr":"Doucement, on a tout notre temps.","tgt":"Từ từ thôi, mình còn nhiều thời gian mà."},{"fr":"Courage, c'est presque fini !","tgt":"Cố lên, sắp xong rồi!"},{"fr":"Ce n'est rien du tout, ne t'en fais pas.","tgt":"Không sao đâu, đừng lo."},{"fr":"Ici, demander si on a mangé, c'est simplement une façon de dire bonjour.","tgt":"Ở đây, hỏi ăn cơm chưa chỉ là một cách chào hỏi thôi."},{"fr":"Mange doucement, sinon tu vas te brûler.","tgt":"Ăn từ từ thôi, không thì bỏng đấy."},{"fr":"Avant mon examen, tout le monde me disait courage.","tgt":"Trước kỳ thi, ai cũng bảo tôi cố lên."},{"fr":"On me demande souvent où je vais, sans attendre de vraie réponse.","tgt":"Người ta hay hỏi tôi đi đâu đấy mà chẳng cần câu trả lời thật."},{"fr":"Allons-y doucement, la ruelle est glissante.","tgt":"Mình đi từ từ thôi, ngõ trơn lắm."}],"tip":{"title":"Les expressions du quotidien : « ăn cơm chưa », « từ từ », « cố lên »","example":"Doucement, on a tout notre temps. — <b>Từ từ</b> thôi, mình còn nhiều thời gian mà.","body":"Au Viêt Nam, « ăn cơm chưa », mot à mot manger riz déjà, est souvent une simple façon de dire bonjour : on répond « ăn rồi », j'ai déjà mangé, et on retourne gentiment la question. « Từ từ » veut dire doucement, pas à pas ; on l'entend partout, pour calmer quelqu'un ou pour savourer un plat, et on ajoute souvent « thôi » à la fin pour adoucir. Dans l'exemple, « từ từ thôi » se décompose en doucement, puis seulement, exactement comme notre doucement, va. « Cố lên » signifie courage, vas-y, mot à mot faire effort, monter : on le lance à un ami avant un examen ou en haut d'une côte. Astuce : ces trois formules font sourire à coup sûr, car elles montrent que vous parlez comme les gens d'ici.","lit":"doucement · seulement · nous · encore · beaucoup · temps · [insistance]","say":{"ăn cơm chưa":"ăn cơm chưa","từ từ":"từ từ","cố lên":"cố lên","ăn rồi":"ăn rồi","Từ từ":"Từ từ","thôi":"thôi","từ từ thôi":"từ từ thôi","Cố lên":"Cố lên"}}},{"title":"Le café à l'œuf","phrases":[{"fr":"Je t'emmène goûter le café à l'œuf dans un petit café caché au fond d'une ruelle.","tgt":"Mình dẫn cậu đi uống cà phê trứng ở một quán nhỏ khuất trong ngõ nhé."},{"fr":"Pour y arriver, on traverse une boutique et on monte un escalier étroit.","tgt":"Phải đi qua một cửa hàng rồi leo cầu thang hẹp mới tới được."},{"fr":"La mousse d'œuf est onctueuse et ne sent pas du tout l'œuf cru.","tgt":"Lớp kem trứng béo ngậy mà không hề tanh."},{"fr":"On raconte que cette boisson est née à une époque où le lait était rare.","tgt":"Nghe nói món này ra đời vào thời sữa còn hiếm."},{"fr":"On pose la tasse dans un bol d'eau chaude pour qu'elle reste tiède.","tgt":"Người ta đặt tách vào bát nước nóng cho cà phê khỏi nguội."},{"fr":"Ça se déguste lentement, à la petite cuillère.","tgt":"Món này phải thưởng thức từ từ bằng thìa nhỏ."},{"fr":"Pour moi, c'est plus un dessert qu'un vrai café.","tgt":"Với tôi, nó giống món tráng miệng hơn là cà phê."},{"fr":"Tu le préfères chaud ou glacé ?","tgt":"Cậu thích uống nóng hay đá?"},{"fr":"Depuis la terrasse, on aperçoit les toits du vieux quartier.","tgt":"Từ sân thượng có thể nhìn thấy mái nhà phố cổ."},{"fr":"Chaque fois que je bois ce café, je repense à mes premiers jours ici.","tgt":"Mỗi lần uống cà phê trứng, tôi lại nhớ những ngày đầu ở đây."}]},{"title":"Les amis ont changé","phrases":[{"fr":"On dirait que tu as maigri ces derniers temps.","tgt":"Hình như dạo này cậu gầy đi thì phải."},{"fr":"Tu as l'air plus serein qu'avant.","tgt":"Trông cậu có vẻ thanh thản hơn trước."},{"fr":"On dirait qu'il va pleuvoir, rentrons vite.","tgt":"Hình như trời sắp mưa, mình về nhanh đi."},{"fr":"Ton nouveau travail a l'air de vraiment te plaire.","tgt":"Có vẻ cậu thích công việc mới lắm."},{"fr":"Il me semble qu'on s'est déjà rencontrés quelque part.","tgt":"Hình như chúng ta đã gặp nhau ở đâu rồi thì phải."},{"fr":"Minh a l'air fatigué ce soir, il travaille trop.","tgt":"Tối nay anh Minh có vẻ mệt, anh ấy làm việc nhiều quá."},{"fr":"Ce quartier semble beaucoup plus calme qu'avant.","tgt":"Khu này có vẻ yên tĩnh hơn trước nhiều."},{"fr":"Il me semble que c'est toi qui m'as appris ce mot.","tgt":"Hình như chính cậu dạy tôi từ này."},{"fr":"Lan est toujours aussi drôle, elle n'a pas changé du tout.","tgt":"Lan vẫn vui tính như xưa, chẳng thay đổi gì cả."},{"fr":"Nos enfants ont l'air de bien s'entendre.","tgt":"Có vẻ con cậu với con tôi chơi rất hợp nhau."}],"tip":{"title":"« Hình như » et « có vẻ » : on dirait que","example":"On dirait que tu as maigri ces derniers temps. — <b>Hình như</b> dạo này cậu gầy đi <b>thì phải</b>.","body":"Pour donner une impression sans l'affirmer, on place « hình như » en tête de phrase : c'est notre on dirait que, ou il me semble que. Souvent, on ajoute « thì phải » tout au bout, ce qui renforce le doute, comme un petit je crois final. Dans l'exemple, on dit mot à mot : on dirait, ces temps-ci, toi, maigrir, je crois bien. « Có vẻ », lui, se place devant un adjectif ou un verbe et veut dire avoir l'air : « có vẻ mệt », avoir l'air fatigué, ou « có vẻ vui », avoir l'air content. Retenez ceci : « hình như » ouvre la phrase sur un doute, alors que « có vẻ » décrit ce que l'on voit sur quelqu'un.","lit":"on dirait · ces temps-ci · tu · maigre · [devenir] · [doute]","say":{"Hình như":"Hình như","có vẻ":"có vẻ","hình như":"hình như","thì phải":"thì phải","Có vẻ":"Có vẻ","có vẻ mệt":"có vẻ mệt","có vẻ vui":"có vẻ vui"}}},{"title":"Débattre entre amis : la ville qui change","phrases":[{"fr":"Je trouve que la ville perd un peu de son charme avec tous ces immeubles.","tgt":"Tôi thấy thành phố mất dần nét duyên vì quá nhiều nhà cao tầng."},{"fr":"Je ne suis pas d'accord, les gens ont aussi droit à plus de confort.","tgt":"Tôi không đồng ý, người dân cũng có quyền được sống tiện nghi hơn chứ."},{"fr":"Selon toi, faudrait-il interdire les scooters dans le vieux quartier ?","tgt":"Theo cậu, có nên cấm xe máy trong phố cổ không?"},{"fr":"Sans scooter, comment les gens iraient-ils travailler ?","tgt":"Không có xe máy thì mọi người đi làm bằng gì?"},{"fr":"Tu marques un point, mais l'air devient vraiment étouffant.","tgt":"Cậu nói cũng có lý, nhưng không khí ngột ngạt thật sự."},{"fr":"Les rues piétonnes du week-end sont une excellente idée.","tgt":"Phố đi bộ cuối tuần là một ý tưởng rất hay."},{"fr":"On peut moderniser la ville sans effacer son passé.","tgt":"Có thể hiện đại hóa thành phố mà không xóa đi quá khứ của nó."},{"fr":"Laisse-moi finir, je n'ai pas encore expliqué mon idée.","tgt":"Để tôi nói hết đã, tôi chưa giải thích xong ý mình."},{"fr":"Bon, on n'arrivera pas à se mettre d'accord ce soir.","tgt":"Thôi, tối nay chắc mình không thống nhất được đâu."},{"fr":"Ce que j'aime avec toi, c'est qu'on peut débattre sans se fâcher.","tgt":"Điều tôi quý ở cậu là mình có thể tranh luận mà không giận nhau."}]},{"title":"Les préparatifs du Tết","phrases":[{"fr":"Une semaine avant le Tết, toute la famille fait le grand ménage.","tgt":"Trước Tết một tuần, cả nhà tổng vệ sinh nhà cửa."},{"fr":"Le marché aux fleurs déborde de branches de pêcher en fleur.","tgt":"Chợ hoa ngập tràn những cành đào."},{"fr":"La grand-mère de mon amie m'a appris à envelopper le bánh chưng.","tgt":"Bà của bạn tôi dạy tôi gói bánh chưng."},{"fr":"On veille la marmite de bánh chưng jusqu'au matin, près du feu.","tgt":"Mọi người thức canh nồi bánh chưng đến sáng bên bếp lửa."},{"fr":"Les rues se vident peu à peu, car beaucoup rentrent dans leur village natal.","tgt":"Phố xá vắng dần vì nhiều người về quê ăn Tết."},{"fr":"Nous avons choisi un kumquat couvert de petits fruits dorés.","tgt":"Chúng tôi đã chọn một cây quất trĩu quả vàng óng."},{"fr":"Il ne faut pas oublier les enveloppes rouges pour les enfants.","tgt":"Đừng quên chuẩn bị phong bao lì xì cho trẻ con."},{"fr":"Pendant le Tết, on évite de se disputer et de dire des mots tristes.","tgt":"Ngày Tết, người ta tránh cãi nhau và nói những lời buồn."},{"fr":"L'odeur des feuilles de dong me rappellera toujours ce Tết-là.","tgt":"Mùi lá dong sẽ mãi nhắc tôi nhớ cái Tết năm ấy."},{"fr":"Je n'aurais jamais imaginé fêter le Tết dans une famille d'ici.","tgt":"Tôi chưa bao giờ nghĩ mình lại được ăn Tết cùng một gia đình Hà Nội."}]},{"title":"Le Tết en famille : les règles à respecter","phrases":[{"fr":"Le premier jour, on doit d'abord aller présenter ses vœux aux grands-parents.","tgt":"Mùng một, phải đến chúc Tết ông bà trước."},{"fr":"J'ai été obligé de trinquer avec chacun des oncles.","tgt":"Tôi buộc phải uống một chén rượu với mỗi chú."},{"fr":"Tu n'es pas obligé de tout finir, mange ce que tu peux.","tgt":"Cậu không phải ăn hết đâu, ăn được bao nhiêu thì ăn."},{"fr":"En recevant l'enveloppe rouge, il faut souhaiter une bonne santé aux aînés.","tgt":"Khi nhận lì xì, phải chúc sức khỏe người lớn."},{"fr":"Malheureusement, j'ai dû repartir avant la fin des fêtes.","tgt":"Tiếc là tôi buộc phải đi trước khi hết Tết."},{"fr":"Est-ce qu'on doit enlever ses chaussures en entrant ?","tgt":"Vào nhà có phải cởi giày không?"},{"fr":"À cause du mauvais temps, nous avons été obligés d'annuler la sortie.","tgt":"Vì trời xấu, chúng tôi buộc phải hủy chuyến đi chơi."},{"fr":"Le premier visiteur de l'année doit être quelqu'un de joyeux.","tgt":"Người xông đất đầu năm phải là người vui vẻ."},{"fr":"Tu dois absolument goûter la confiture de gingembre de ma mère.","tgt":"Cậu phải nếm thử mứt gừng mẹ tôi làm."},{"fr":"Personne ne m'y oblige, mais j'aime aider à la cuisine.","tgt":"Không ai bắt tôi phải làm, nhưng tôi thích phụ bếp."}],"tip":{"title":"« Phải » et « buộc phải » : être obligé de","example":"À cause du mauvais temps, nous avons été obligés d'annuler la sortie. — Vì trời xấu, chúng tôi <b>buộc phải</b> hủy chuyến đi chơi.","body":"Pour dire qu'on doit faire quelque chose, on place simplement « phải » devant le verbe : « phải đi », il faut partir. Quand la contrainte vient de l'extérieur et qu'on n'a vraiment pas le choix, on dit « buộc phải », mot à mot lié, devoir, un peu comme notre être contraint de. Dans l'exemple, on entend : à cause du mauvais temps, nous, « buộc phải », annuler la sortie. Pour dire qu'on n'est pas obligé, on met « không phải » devant le verbe : « không phải ăn hết », pas besoin de tout finir. Et pour demander si c'est obligatoire, on encadre le verbe : « có phải cởi giày không », faut-il enlever ses chaussures. Astuce : « phải » tout seul, c'est le devoir ordinaire, « buộc phải », c'est le devoir qu'on subit.","lit":"parce que · temps · mauvais · nous · contraint · devoir · annuler · [classificateur] · sortir · s'amuser","say":{"Phải":"Phải","buộc phải":"buộc phải","phải":"phải","phải đi":"phải đi","không phải":"không phải","không phải ăn hết":"không phải ăn hết","có phải cởi giày không":"có phải cởi giày không"}}},{"title":"Nuancer son opinion","phrases":[{"fr":"Ce n'est pas tout à fait faux, mais c'est un peu exagéré.","tgt":"Không hẳn là sai, nhưng hơi quá một chút."},{"fr":"D'un côté je te comprends, de l'autre je vois les choses autrement.","tgt":"Một mặt tôi hiểu cậu, mặt khác tôi lại nhìn nhận khác."},{"fr":"Tout dépend des circonstances, à mon avis.","tgt":"Theo tôi, cái đó còn tùy hoàn cảnh."},{"fr":"Je ne dirais pas que c'est mauvais, juste que ce n'est pas pour moi.","tgt":"Tôi không nói là nó dở, chỉ là nó không hợp với tôi thôi."},{"fr":"En partie, oui, mais pas complètement.","tgt":"Đúng một phần, nhưng không hoàn toàn."},{"fr":"Sans vouloir te contredire, j'ai lu quelque chose de différent.","tgt":"Không phải tôi muốn cãi cậu, nhưng tôi đọc thấy khác."},{"fr":"Il y a du vrai dans ce que tu dis.","tgt":"Cậu nói cũng có phần đúng."},{"fr":"Je comprends ton point de vue, même si je ne le partage pas.","tgt":"Tôi hiểu quan điểm của cậu, dù tôi không đồng tình."},{"fr":"Disons que chacun a ses goûts.","tgt":"Thôi thì mỗi người một sở thích vậy."},{"fr":"Je me suis peut-être trompé, je vais encore y réfléchir.","tgt":"Có lẽ tôi đã nhầm, để tôi suy nghĩ thêm."}]},{"title":"La cuisine de la grand-mère","phrases":[{"fr":"À quatre-vingts ans, la grand-mère de Lan cuisine encore pour toute la famille.","tgt":"Tám mươi tuổi rồi mà bà của Lan vẫn nấu ăn cho cả nhà."},{"fr":"Elle ne mesure jamais rien, elle cuisine au jugé.","tgt":"Bà chẳng bao giờ đong đếm, bà nấu theo cảm giác."},{"fr":"Son phở a un goût que je n'ai retrouvé nulle part ailleurs.","tgt":"Phở của bà có một hương vị mà tôi chưa tìm thấy ở đâu khác."},{"fr":"D'après elle, le secret, c'est de laisser mijoter le bouillon toute une nuit.","tgt":"Theo bà, bí quyết là ninh nước dùng suốt một đêm."},{"fr":"Elle m'a appris à rouler les nems sans les déchirer.","tgt":"Bà dạy tôi cuốn nem mà không bị rách."},{"fr":"À chaque repas, elle me sert plus que je ne peux manger.","tgt":"Bữa nào bà cũng gắp cho tôi nhiều hơn tôi ăn nổi."},{"fr":"« Mange encore, tu es trop maigre ! », me répète-t-elle sans cesse.","tgt":"Bà cứ bảo tôi: ăn thêm đi, cháu gầy quá!"},{"fr":"Je note toutes ses recettes dans un petit carnet.","tgt":"Tôi ghi lại tất cả công thức của bà vào một cuốn sổ nhỏ."},{"fr":"Cuisiner avec elle, c'est aussi écouter ses histoires d'autrefois.","tgt":"Nấu ăn cùng bà cũng là được nghe bà kể chuyện ngày xưa."},{"fr":"J'espère réussir un jour son bún chả aussi bien qu'elle.","tgt":"Tôi mong một ngày nào đó sẽ làm được món bún chả ngon như bà."}]},{"title":"Une soirée de bière fraîche","phrases":[{"fr":"On se retrouve ce soir pour une bière pression au coin de la rue ?","tgt":"Tối nay mình ra quán bia hơi đầu phố nhé?"},{"fr":"Nous sommes assis sur de petits tabourets en plastique, en plein trottoir.","tgt":"Chúng tôi ngồi ghế nhựa thấp ngay trên vỉa hè."},{"fr":"Un, deux, trois, santé !","tgt":"Một, hai, ba, dô!"},{"fr":"Ici, un verre de bière coûte à peine dix mille dongs.","tgt":"Ở đây một cốc bia chỉ khoảng mười nghìn đồng."},{"fr":"On commande des cacahuètes grillées et du tofu frit pour grignoter ?","tgt":"Mình gọi thêm lạc rang với đậu rán để nhắm nhé?"},{"fr":"Plus la soirée avance, plus les discussions s'animent.","tgt":"Càng về khuya, câu chuyện càng sôi nổi."},{"fr":"Pas si vite, je n'ai pas l'habitude de boire autant.","tgt":"Từ từ thôi, tôi không quen uống nhiều thế này."},{"fr":"Désolé, je m'arrête là, je dois encore rentrer en scooter.","tgt":"Xin lỗi, tôi không uống nữa, tôi còn phải đi xe máy về."},{"fr":"Mon ami a tenu à payer pour toute la table.","tgt":"Bạn tôi nhất định đòi trả tiền cho cả bàn."},{"fr":"Ce genre de soirée toute simple, c'est ce qui m'a le plus manqué.","tgt":"Những buổi tối giản dị như thế này là điều tôi nhớ nhất."}]},{"title":"Les proverbes des anciens","phrases":[{"fr":"Ma professeure aimait répéter : à force de limer le fer, on en fait une aiguille.","tgt":"Cô giáo tôi hay nói: có công mài sắt, có ngày nên kim."},{"fr":"Ce proverbe veut dire qu'avec de la patience, on finit par réussir.","tgt":"Câu tục ngữ này có nghĩa là kiên trì thì sẽ thành công."},{"fr":"« En buvant l'eau, souviens-toi de la source », dit le proverbe.","tgt":"Tục ngữ có câu: uống nước nhớ nguồn."},{"fr":"Les grands-parents s'en servent pour rappeler la gratitude envers les anciens.","tgt":"Ông bà hay dùng câu đó để nhắc con cháu biết ơn người đi trước."},{"fr":"Mieux vaut un bon voisin qu'un frère éloigné, disent les Vietnamiens.","tgt":"Người Việt có câu: bán anh em xa, mua láng giềng gần."},{"fr":"Mes voisins de Hanoï m'ont prouvé que ce proverbe est vrai.","tgt":"Hàng xóm ở Hà Nội đã cho tôi thấy câu tục ngữ ấy thật đúng."},{"fr":"« Un jour de voyage, un tamis de sagesse » : c'est tout à fait mon expérience.","tgt":"Đi một ngày đàng, học một sàng khôn, với tôi đúng là như vậy."},{"fr":"Un arbre seul ne fait pas une colline, mais trois arbres ensemble forment une haute montagne.","tgt":"Một cây làm chẳng nên non, ba cây chụm lại nên hòn núi cao."},{"fr":"Les mots ne coûtent rien, alors choisissons-les pour faire plaisir.","tgt":"Lời nói chẳng mất tiền mua, lựa lời mà nói cho vừa lòng nhau."},{"fr":"Citer un proverbe au bon moment fait toujours sourire les gens d'ici.","tgt":"Nói một câu tục ngữ đúng lúc bao giờ cũng làm người ở đây mỉm cười."}],"tip":{"title":"Les « tục ngữ » : les proverbes vietnamiens","example":"Ma professeure aimait répéter : à force de limer le fer, on en fait une aiguille. — Cô giáo tôi hay nói: <b>có công mài sắt, có ngày nên kim</b>.","body":"Les « tục ngữ » sont des proverbes : à la différence des « thành ngữ », qui sont des morceaux de phrase, ce sont des phrases complètes qui donnent une leçon de vie. Ils sont souvent construits en deux moitiés qui se répondent, avec le même rythme. Dans l'exemple, « có công mài sắt, có ngày nên kim » se décompose ainsi : avoir effort, limer fer, avoir jour, devenir aiguille, autrement dit, avec de la patience on finit par réussir. Vous entendrez aussi « uống nước nhớ nguồn », en buvant l'eau, se souvenir de la source, ou « đi một ngày đàng, học một sàng khôn », un jour de voyage, un tamis de sagesse, où « đàng » et « sàng » riment. Astuce : introduisez-les par « người ta nói », comme on dit, et dites-les lentement, en marquant une petite pause au milieu.","lit":"professeure · je · souvent · dire · avoir · effort · limer · fer · avoir · jour · devenir · aiguille","say":{"tục ngữ":"tục ngữ","thành ngữ":"thành ngữ","có công mài sắt, có ngày nên kim":"có công mài sắt, có ngày nên kim","uống nước nhớ nguồn":"uống nước nhớ nguồn","đi một ngày đàng, học một sàng khôn":"đi một ngày đàng, học một sàng khôn","đàng":"đàng","sàng":"sàng","người ta nói":"người ta nói"}}},{"title":"Les différences entre générations","phrases":[{"fr":"Mes amis disent que leurs parents ne comprennent pas leur métier.","tgt":"Bạn bè tôi bảo bố mẹ họ không hiểu nghề của họ."},{"fr":"Autrefois, trois générations vivaient sous le même toit.","tgt":"Ngày xưa, ba thế hệ sống chung dưới một mái nhà."},{"fr":"Aujourd'hui, beaucoup de jeunes préfèrent habiter seuls en ville.","tgt":"Bây giờ nhiều bạn trẻ thích ở riêng trên thành phố."},{"fr":"Ma tante trouve que les jeunes passent trop de temps sur leur téléphone.","tgt":"Cô tôi cho rằng giới trẻ dành quá nhiều thời gian cho điện thoại."},{"fr":"Les anciens tiennent beaucoup au respect de la hiérarchie des âges.","tgt":"Người lớn tuổi rất coi trọng chuyện kính trên nhường dưới."},{"fr":"Les jeunes, eux, veulent surtout qu'on écoute leur avis.","tgt":"Còn người trẻ thì muốn được lắng nghe ý kiến của mình."},{"fr":"On demande sans cesse à mon amie quand elle va se marier.","tgt":"Người ta cứ hỏi bạn tôi bao giờ lấy chồng."},{"fr":"Elle répond en riant qu'elle n'est pas pressée.","tgt":"Cô ấy cười và bảo là không vội."},{"fr":"Chaque génération pense avoir raison, et c'est bien normal.","tgt":"Thế hệ nào cũng nghĩ mình đúng, chuyện đó bình thường thôi."},{"fr":"Ce qui les rapproche, c'est souvent un bon repas partagé.","tgt":"Điều gắn kết họ thường là một bữa cơm chung ấm cúng."}]},{"title":"Un malentendu culturel","phrases":[{"fr":"Au début, je ne comprenais pas pourquoi on me demandait mon âge.","tgt":"Lúc đầu tôi không hiểu sao người ta cứ hỏi tuổi tôi."},{"fr":"En fait, ça sert à savoir comment s'adresser à quelqu'un.","tgt":"Thật ra, hỏi tuổi là để biết nên xưng hô thế nào."},{"fr":"J'ai appelé « em » une femme plus âgée que moi, quelle honte !","tgt":"Tôi đã gọi một chị lớn tuổi hơn mình là em, xấu hổ quá!"},{"fr":"Elle a éclaté de rire et m'a gentiment corrigé.","tgt":"Chị ấy phá lên cười rồi nhẹ nhàng sửa cho tôi."},{"fr":"Depuis, quand j'ai un doute, je dis toujours « anh » ou « chị ».","tgt":"Từ đó, khi không chắc, tôi luôn gọi là anh hoặc chị."},{"fr":"On m'a aussi appris à tendre les objets aux aînés avec les deux mains.","tgt":"Người ta cũng dạy tôi đưa đồ cho người lớn bằng hai tay."},{"fr":"Refuser une invitation trop directement peut vexer.","tgt":"Từ chối lời mời thẳng thừng quá có thể làm người ta phật lòng."},{"fr":"Ici, quand quelqu'un dit oui, ça ne veut pas forcément dire qu'il est d'accord.","tgt":"Ở đây, nói vâng chưa chắc đã là đồng ý."},{"fr":"Ces petites erreurs m'ont appris plus que n'importe quel livre.","tgt":"Những lỗi nhỏ ấy dạy tôi nhiều hơn bất kỳ cuốn sách nào."},{"fr":"Quand on en reparle aujourd'hui, mes amis et moi, on rit encore.","tgt":"Giờ nhắc lại, tôi với bạn bè vẫn cười mãi."}]},{"title":"Ce que veut dire l'amitié","phrases":[{"fr":"Pour moi, un vrai ami est celui qui reste là dans les moments difficiles.","tgt":"Với tôi, bạn thật là người ở bên mình lúc khó khăn."},{"fr":"Dix ans après, on s'est retrouvés comme si on s'était quittés la veille.","tgt":"Mười năm rồi mà gặp lại cứ như mới chia tay hôm qua."},{"fr":"Huy m'a appelé dès qu'il a appris mon retour.","tgt":"Huy gọi cho tôi ngay khi biết tôi về."},{"fr":"Entre nous, pas besoin de faire de manières.","tgt":"Giữa chúng mình thì không cần khách sáo."},{"fr":"Il m'a hébergé toute une semaine sans rien demander en retour.","tgt":"Cậu ấy cho tôi ở nhờ cả tuần mà chẳng đòi hỏi gì."},{"fr":"On ne se voit pas souvent, mais le lien reste fort.","tgt":"Tuy không gặp nhau thường xuyên nhưng tình cảm vẫn gắn bó."},{"fr":"Je lui dois une grande partie de mes progrès en vietnamien.","tgt":"Tôi tiến bộ tiếng Việt phần lớn là nhờ cậu ấy."},{"fr":"Quand je me trompais, il me corrigeait sans jamais se moquer.","tgt":"Khi tôi nói sai, cậu ấy sửa cho tôi mà chưa bao giờ chế giễu."},{"fr":"L'amitié, ça s'entretient comme une plante.","tgt":"Tình bạn cũng cần vun đắp như một cái cây."},{"fr":"J'espère que nos enfants seront amis, eux aussi.","tgt":"Tôi mong con cái chúng tôi sau này cũng sẽ là bạn của nhau."}]},{"title":"Donner un conseil à un ami","phrases":[{"fr":"Si j'étais toi, je prendrais le temps d'y réfléchir.","tgt":"Nếu là cậu, tôi sẽ dành thời gian suy nghĩ kỹ."},{"fr":"Tu devrais en parler franchement à ta famille.","tgt":"Cậu nên nói thẳng với gia đình."},{"fr":"Ne prends pas de décision sous le coup de la colère.","tgt":"Đừng quyết định lúc đang nóng giận."},{"fr":"À ta place, j'accepterais ce poste à Đà Lạt sans hésiter.","tgt":"Là tôi thì tôi nhận công việc ở Đà Lạt luôn, chẳng do dự."},{"fr":"Ça vaut la peine d'essayer, tu n'as rien à perdre.","tgt":"Đáng để thử đấy, cậu có mất gì đâu."},{"fr":"Écoute ton cœur, mais garde les pieds sur terre.","tgt":"Hãy nghe theo trái tim, nhưng cũng phải thực tế."},{"fr":"Je te dis ça parce que je tiens à toi.","tgt":"Tôi nói vậy vì tôi quý cậu."},{"fr":"Au bout du compte, la décision t'appartient.","tgt":"Cuối cùng thì cậu là người quyết định."},{"fr":"Quoi que tu décides, je serai de ton côté.","tgt":"Dù cậu quyết định thế nào, tôi vẫn ủng hộ cậu."},{"fr":"Courage, tu vas trouver la bonne solution.","tgt":"Cố lên, cậu sẽ tìm ra cách thôi."}]},{"title":"Les souvenirs d'enfance d'une amie","phrases":[{"fr":"Mai a grandi dans un petit village près de la baie d'Hạ Long.","tgt":"Mai lớn lên ở một làng nhỏ gần vịnh Hạ Long."},{"fr":"Enfant, elle gardait les buffles après l'école.","tgt":"Hồi nhỏ, tan học là chị ấy đi chăn trâu."},{"fr":"Elle se souvient des soirées sans électricité, à la lumière d'une lampe à huile.","tgt":"Chị ấy còn nhớ những tối mất điện, ngồi bên ngọn đèn dầu."},{"fr":"Les enfants du village faisaient voler des cerfs-volants au-dessus des rizières.","tgt":"Trẻ con trong làng thả diều trên cánh đồng lúa."},{"fr":"Le Tết était le seul moment de l'année où elle portait des vêtements neufs.","tgt":"Tết là dịp duy nhất trong năm chị ấy được mặc quần áo mới."},{"fr":"Sa mère partait au marché à l'aube avec ses paniers de légumes.","tgt":"Mẹ chị ấy đi chợ từ tờ mờ sáng với gánh rau."},{"fr":"C'était une vie dure, mais elle en garde un souvenir heureux.","tgt":"Cuộc sống ngày ấy vất vả nhưng chị ấy vẫn nhớ về nó với niềm vui."},{"fr":"En l'écoutant, j'ai pensé à mes propres étés chez mes grands-parents.","tgt":"Nghe chị kể, tôi nhớ đến những mùa hè ở nhà ông bà mình."},{"fr":"Nos enfances étaient différentes, mais les émotions se ressemblaient.","tgt":"Tuổi thơ của chúng tôi khác nhau, nhưng cảm xúc thì giống nhau."},{"fr":"Un jour, j'aimerais visiter son village avec elle.","tgt":"Một ngày nào đó, tôi muốn cùng chị ấy về thăm làng."}]},{"title":"Un au revoir à l'aéroport","phrases":[{"fr":"Tous mes amis sont venus m'accompagner à l'aéroport de Nội Bài.","tgt":"Bạn bè đều ra sân bay Nội Bài tiễn tôi."},{"fr":"Je déteste les adieux, alors ne les faisons pas durer.","tgt":"Tôi ghét những cuộc chia tay, nên mình đừng bịn rịn lâu nhé."},{"fr":"Ce n'est pas un adieu, juste un petit au revoir.","tgt":"Đây không phải vĩnh biệt, chỉ là tạm biệt thôi."},{"fr":"Prends soin de toi et donne-moi souvent des nouvelles.","tgt":"Giữ gìn sức khỏe và nhớ thường xuyên báo tin nhé."},{"fr":"La grand-mère de Lan a glissé un paquet de thé dans mon sac.","tgt":"Bà của Lan dúi vào túi tôi một gói chè."},{"fr":"Je reviendrai pour le prochain Tết, c'est promis.","tgt":"Tết sau tôi sẽ quay lại, hứa đấy."},{"fr":"J'ai les larmes aux yeux, mais je suis aussi tellement heureux.","tgt":"Tôi rưng rưng nước mắt, nhưng cũng hạnh phúc vô cùng."},{"fr":"Grâce à vous, Hanoï est devenue ma deuxième maison.","tgt":"Nhờ mọi người, Hà Nội đã trở thành ngôi nhà thứ hai của tôi."},{"fr":"Bon voyage, et envoie-nous un message en arrivant !","tgt":"Thượng lộ bình an, đến nơi nhắn tin cho bọn mình nhé!"},{"fr":"Dans l'avion, je regardais encore les lumières de la ville s'éloigner.","tgt":"Trên máy bay, tôi vẫn nhìn theo ánh đèn thành phố xa dần."}]},{"title":"Regard en arrière sur mon parcours en vietnamien","phrases":[{"fr":"Au début, les six tons du vietnamien me paraissaient impossibles à maîtriser.","tgt":"Lúc đầu, tôi tưởng sáu thanh của tiếng Việt là điều không thể học nổi."},{"fr":"Je confondais sans cesse « ma », « má » et « mà ».","tgt":"Tôi cứ nhầm lẫn ma, má và mà."},{"fr":"Je me souviens de ma première commande de phở, toute hésitante.","tgt":"Tôi vẫn nhớ lần đầu gọi một bát phở, ấp a ấp úng."},{"fr":"Aujourd'hui, je peux discuter pendant des heures avec mes amis.","tgt":"Giờ đây tôi có thể nói chuyện hàng giờ với bạn bè."},{"fr":"J'ai compris que la langue et la culture sont inséparables.","tgt":"Tôi hiểu ra rằng ngôn ngữ và văn hóa không thể tách rời."},{"fr":"Les pronoms de parenté m'ont appris à faire attention aux autres.","tgt":"Cách xưng hô đã dạy tôi biết để ý đến người khác."},{"fr":"Il m'arrive encore de me tromper de ton, et alors ?","tgt":"Thỉnh thoảng tôi vẫn nói sai thanh, nhưng có sao đâu?"},{"fr":"Le plus difficile n'était pas la grammaire, mais oser parler.","tgt":"Khó nhất không phải ngữ pháp mà là dám mở miệng nói."},{"fr":"Toutes ces phrases répétées sur la route ont fini par porter leurs fruits.","tgt":"Bao nhiêu câu nói lẩm nhẩm trên đường cuối cùng cũng đơm hoa kết trái."},{"fr":"Si on m'avait dit ça au début, je ne l'aurais pas cru.","tgt":"Nếu hồi đầu có ai nói thế, chắc tôi chẳng tin."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Je suis capable de suivre une vraie conversation en vietnamien.","tgt":"Tôi đã có thể theo kịp một cuộc trò chuyện thật sự bằng tiếng Việt."},{"fr":"Je sais citer quelques proverbes et expressions au bon moment.","tgt":"Tôi biết dùng vài câu tục ngữ, thành ngữ đúng lúc."},{"fr":"Je sais nuancer mon avis sans blesser personne.","tgt":"Tôi biết bày tỏ ý kiến một cách tế nhị mà không làm ai phật lòng."},{"fr":"Je choisis le bon pronom presque sans réfléchir.","tgt":"Tôi chọn cách xưng hô đúng gần như không cần nghĩ."},{"fr":"Il me reste encore beaucoup à apprendre, et c'est tant mieux.","tgt":"Tôi vẫn còn nhiều điều phải học, và như thế càng tốt."},{"fr":"Mon prochain objectif, c'est de comprendre l'accent de Huế.","tgt":"Mục tiêu tiếp theo của tôi là nghe hiểu giọng Huế."},{"fr":"Je continuerai à parler vietnamien chaque jour, même un peu.","tgt":"Tôi sẽ tiếp tục nói tiếng Việt mỗi ngày, dù chỉ một chút."},{"fr":"Apprendre cette langue a changé ma façon de voir la vie.","tgt":"Học tiếng Việt đã thay đổi cách tôi nhìn cuộc sống."},{"fr":"Je suis fier du chemin parcouru depuis la toute première leçon.","tgt":"Tôi tự hào về chặng đường đã đi từ bài học đầu tiên."},{"fr":"Comme on dit ici, à force de limer le fer, on finit par obtenir une aiguille.","tgt":"Đúng như người ta nói, có công mài sắt, có ngày nên kim."}]}]}]}];
